  ["_CeladonGymErikaPreBattleText"] = "Salve. Che bel\ntempo, vero?\12é cosi' piacevole.\n...Oh cielo...\11Mi sono appisolata.\nBenvenuto.\12Mi chiamo ERIKA.\nSono la CAPOPALESTRA\11di AZZURROPOLI.\12Insegno l'arte\ndell'ikebana. I miei\11POKéMON sono di\11tipo Erba.\12Oh, perdona, non\nsapevo volessi\11sfidarmi.\12Va bene, ma non\nterro' testa bassa.",
  ["_CeladonGymErikaReceivedRainbowBadgeText"] = "Oh!\nAmmetto la sconfitta.\12Sei davvero\nmolto forte.\12Devo conferirti\nil MEDAGLIARCO.",
  ["_CeladonGymRainbowBadgeInfoText"] = "Il MEDAGLIARCO\nfara' ubbidire i POKéMON\11fino al Lv. 50.\12Permette anche di\nusare FORZA dentro\11e fuori la lotta.\12Prendi anche\nquesto con te.",
