  ["_CeladonMart1FDirectorySignText"] = "1P: BANCO INFO\n2P: MERCATO ALLENATORI\n3P: NEGOZIO VIDEOGIOCHI\n4P: REGALI SAGGI\n5P: ERBORISTERIA\nREPARTO SUL TETTO:\nDISTRIBUTORI",
  ["_CeladonMart1FReceptionistText"] = "Salve! Benvenuto\nal GRANDE MAG.\12Il cartello a destra\nindica i reparti.",
  ["_CeladonMart2FCurrentFloorSignText"] = "Strumenti top per\nallenatori!\122P: MERCATO ALLENATORI",
  ["_CeladonMart2FGirlText"] = "Per le lunghe uscite\ndovresti comprare\11una REVIVASPEC.",
  ["_CeladonMart2FMiddleAgedManText"] = "SUPERREPELLENTE\ntiene lontani i POKéM.\11piu' deboli...\12Mh, é un REPELLENTE\npiu' potente!",
  ["_CeladonMart3FClerkReceivedTM18Text"] = "{PLAYER} ha ricevuto\n{RAM:wStringBuffer}!",
  ["_CeladonMart3FClerkTM18ExplanationText"] = "La MT18 é CONTROPIEDE!\nNon quella a cui\11mi appoggio io,\11ovviamente!",
  ["_CeladonMart3FClerkTM18NoRoomText"] = "Il tuo zaino é\npieno di strumenti!",
  ["_CeladonMart3FClerkTM18PreReceiveText"] = "Oh, ciao! Ho\nfinalmente finito i POKé!\12Non hai ancora finito?\nQuesto potrebbe\11esserti utile!",
  ["_CeladonMart3FCurrentFloorSignText"] = "3P: NEGOZIO VIDEOGIOCHI",
  ["_CeladonMart3FFightingGameText"] = "Un picchiaduro!\nSembra difficile!",
  ["_CeladonMart3FGameBoyKid1Text"] = "I POKéMON catturati\nregistrano un Num. ID\11e AO, il nome\11dell'Allenatore Originale\11che li ha catturati!",
  ["_CeladonMart3FGameBoyKid2Text"] = "Bene!\nIl mio amico mi\11scambia il suo\11KANGASKHAN per\11il mio GRAVELER!",
  ["_CeladonMart3FGameBoyKid3Text"] = "Forza GRAVELER!\nAdoro GRAVELER!\nLi colleziono!\11Eh?\12GRAVELER si é\ntrasformato in un\11altro POKéMON!",
  ["_CeladonMart3FLittleBoyText"] = "Puoi identificare\ni POKéMON presi\11negli scambi dal\11loro Numero ID!",
  ["_CeladonMart3FPokemonPosterText"] = "Rosso e Blu!\nSono entrambi POKéMON!",
  ["_CeladonMart3FPuzzleGameText"] = "Un puzzle game!\nCrea dipendenza!",
  ["_CeladonMart3FRPGText"] = "Un GdR! Non c'é\ntempo per quello!",
  ["_CeladonMart3FSNESText"] = "é un Super NES!",
  ["_CeladonMart3FSportsGameText"] = "Un gioco di sport!\nAl babbo piacera'!",
  ["_CeladonMart4FCurrentFloorSignText"] = "Esprimiti con\ni regali!\124P: REGALI SAGGI\nSpeciale Evoluzione!\nPIETRE elementari\11in offerta!",
  ["_CeladonMart4FSuperNerdText"] = "Prendo una BAMBOLA\nPOKé per la mia\11ragazza!",
  ["_CeladonMart4FYoungsterText"] = "Ho sentito una cosa\nutile.\12Puoi fuggire dai\nPOKéMON selvatici\11distraendoli con\11una BAMBOLA POKé!",
  ["_CeladonMart5FCurrentFloorSignText"] = "5P: ERBORISTERIA",
  ["_CeladonMart5FGentlemanText"] = "I potenziatori di\nstatistiche si\11comprano solo qui.\12Usa CALCIO per\naumentare le abilita'\11SPECIALI.\12Usa CARBOS per\naumentare la VELOCITA'.",
  ["_CeladonMart5FSailorText"] = "Sono qui per i\npotenziatori!\12PROTEINA aumenta\nil Attacco.\12FERRO aumenta\nla DIFESA!",
  ["_CeladonMartRoofCurrentFloorSignText"] = "REPARTO SUL TETTO:\nDISTRIBUTORI",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "Ho sete!\nVoglio qualcosa\11da bere!\12Le dai da bere?",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "Quale bibita\nle dai?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "No, grazie!\nAlla fine non ho\11piu' sete!",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "Ho sete!\nVoglio qualcosa\11da bere!",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "Non hai spazio\nper questo!",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER} ha ricevuto\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER} ha ricevuto\n{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER} ha ricevuto\nMT49!",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "\12{RAM:wStringBuffer} contiene\nGELOPUNTO!\12A volte puo'\ncongelare il bersaglio!",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "\12{RAM:wStringBuffer} contiene\nFRANA!\12A volte puo'\nspaventare il bersaglio!",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "\12La MT49 contiene\nTRIPLICE ATTACCO!",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "Evviva!\nACQUA FRESCA!\12Grazie!\nPuoi prendere\11questo da parte mia!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "Evviva!\nLIMONATA!\12Grazie!\nPuoi prendere\11questo da parte mia!",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "Evviva!\nBIBITA!\12Grazie!\nPuoi prendere\11questo da parte mia!",
  ["_CeladonMartRoofSuperNerdText"] = "Mia sorella é un'allenat.\nci credi o no.\12Ma é cosi' immatura\nche mi fa impazzire!",
  ["_CeladonPokecenterBeautyText"] = "Ho pedalato in salita\nsulla PISTA CICLABILE\11da FUCSIAPOLI!",
  ["_CeladonPokecenterGentlemanText"] = "Il FLAUTO POKé\nsveglia i POKéMON\ncon un suono che\11sentono solo loro!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "L'ATTACCO di tutti\ni POKéMON aumenta\11un pochino.\12Permette anche di\nusare FLASH ogni\11volta che lo desideri.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "I POKéMON fino al\nLv. 30 ubbidiranno.\12Piu' alti, diventeranno\ninsoffrenti!\12Permette anche di\nusare TAGLIO fuori\11dallotta.",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "Tutti i POKéMON\nti ubbidiranno!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "I POKéMON fino al\nLv. 70 ubbidiranno.\12Piu' alti, diventeranno\ninsoffrenti!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "Le MEDAGLIE POKéMON\nsono possedute solo\11da esperti.\12Vedo che ne hai\nalmeno una.\12Quelle medaglie\nhanno segreti incredibili!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Vieni a trovarmi\nquando vuoi.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Dunque...\nQuale delle 8\11medaglie devo\11descrivere?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "I POKéMON fino al\nLv. 50 ubbidiranno.\12Piu' alti, diventeranno\ninsoffrenti!\12Permette anche di\nusare FORZA fuori\11dalla lotta.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "La DIFESA di tutti\ni POKéMON aumenta\11un pochino.\12Permette anche di\nusare SURF fuori\11dalla lotta.",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "La VELOCITA' di tutti\ni POKéMON aumenta\11un pochino.\12Permette anche di\nusare VOLO fuori\11dalla lotta.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Le abilita' SPECIALI\ndei tuoi POKéMON\11aumentano un po'.",
  ["_CeruleanCityBikeShopSign"] = "Erba e grotte\naffrontate facili!\11NEGOZIO BICI",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "Pugno SLOWBRO!\nNo! Hai sbagliato\11di nuovo!",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "Ok! SLOWBRO!\nUsa SONICBOOM!\11Forza, SLOWBRO\11presta attenzione!",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "SLOWBRO, RITIRATA!\nNo! é sbagliato!\12é cosi' difficile\ncontrollare i POKéMON!\12L'ubbidienza dipende\n膵dalle tue abilita'\11di allenatore!",
  ["_CeruleanCityCooltrainerF2Text"] = "Voglio una BICICLETTA\nrosso fuoco!\12La terro' in casa\ncosi' non si sporca!",
  ["_CeruleanCityCooltrainerMText"] = "Sei un allenatore\n anche tu? Collezionare\11e lottare é dura.",
  ["_CeruleanCityGuardText"] = "La gente qui é stata\nrapinata.\12é ovvio che il\nTEAM ROCKET é\11dietro questo efferato\11crimine!\12Anche la POLIZIA ha\nproblemi con i ROCKET!",
  ["_CeruleanCityGymSign"] = "CERULOPOLI\nPALESTRA POKéMON\11CAPOPALESTRA: MISTY\12La Sirenetta\nSanguigna",
  ["_CeruleanCityRivalDefeatedText"] = "Ehi!\nCalma!\11Hai gia' vinto!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: Ehi,\nsapevi?\12Sono andato da BILL\ne mi ha fatto vedere\11i suoi rari POKéMON!\12Ha aggiunto molte\npagine al mio POKéDEX!\12D'altronde, BILL é\nfamoso nel mondo\11come POKéMANIAC!\12Ha inventato il\nSistema Memoria POKéMON\11su PC!\12Visto che usi il\nsuo sistema, ringrazialo!\12Beh, devo filare!\12Ci becchiamo!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: Ehi!\n{PLAYER}!\12Te la strascichi\nancora qui dietro?\12Io me la cavo alla\ngrande! Ho catturato\11un bel po' di POKéMON\11forti e intelligenti!\12Ecco, fammi vedere\ncosa hai catturato,\11{PLAYER}!",
  ["_CeruleanCityRivalVictoryText"] = "Heh!\nNon sei alla altezza\11del mio genio!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "\12Devo proprio\nmuovermi! Ciao!",
  ["_CeruleanCityRocketIGiveUpText"] = "Fermati!\nMi arrendo! Me ne\11vado quatto quatto!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "Ok! Resituiro'\nla MT che ho rubato!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER} ha recuperato\nla MT28!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "Fai spazio per\nquesto!\12Non posso muovermi\nfinché non te la do!",
  ["_CeruleanCityRocketText"] = "Ehi! Fuori! Não é\nil tuo cortile! Eh?\nIo?\12Sono un innocente\npassante! Non mi\ncredi?",
  ["_CeruleanCitySignText"] = "CERULOPOLI\nUn'aura blu\ne misteriosa\11la circonda",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "SLOWBRO\nha ignorato gli ordini...",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "SLOWBRO ciondola\nin giro...",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "SLOWBRO si é\nfatto un sonnellino...",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "SLOWBRO si é\ngirato dall'altra parte...",
  ["_CeruleanCitySuperNerd1Text"] = "Quel cespuglio\ndavanti al negozio\11é d'intralcio.\12Forse c'é una via\nalternativa.",
  ["_CeruleanCitySuperNerd2Text"] = "Stai facendo un\nenciclopedia sui\11POKéMON? Interessante.",
  ["_CeruleanCitySuperNerd3Text"] = "Questa é la GROTTA\nCERULA! Ci vivono\11POKéMON fortissimi!\12Solo il campione\ndella LEGA POKéMON\11puo' entrare!",
  ["_CeruleanCityTrainerTipsText"] = "CONSIGLI UTILI\12Premere il pulsante B\ndurante l'evoluzione\11annulla l'intero\11processo.",
  ["_CeruleanGymAfterBattleText1"] = "Devi affrontare\naltri allenatori\11per scoprire quanto\11vali davvero.",
  ["_CeruleanGymAfterBattleText2"] = "MISTY continuera'\na migliorare!\12Non perdera' con\nuno come te!",
  ["_CeruleanGymBattleText1"] = "Valgo molto piu'\ndi te!\12MISTY puo' aspettare!",
  ["_CeruleanGymBattleText2"] = "Splash!\nSono il primo!\nFacciamolo!",
  ["_CeruleanGymEndBattleText1"] = "Mi hai\nsopraffatto!",
  ["_CeruleanGymEndBattleText2"] = "Non puo'\nessere!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "Hai battuto MISTY!\nChe ti avevo detto?\12Io e te, ragazzo,\nsiamo una bella\11squadra!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "Ehi! Futuro\ncampione!\12Ecco il mio consiglio!\12La CAPOPALESTRA MISTY\né un asso dei POKéMON\11Acqua!\12Puoi prosciugarli\ncon i POKéMON Pianta!\12O fulminarli con\nl'elettricita'!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "La MEDAGLIACASCATA\nfa ubbidire i POKéMON\11fino al Lv. 30!\12Inclusi quelli\nscambiati!\12C'é di piu': ora\npuoi usare TAGLIO!\12Puoi tagliare i\npiccoli cespugli\11per aprire vie!\12Prendi anche la\nmi MT preferita!",
  ["_CeruleanGymMistyPreBattleText"] = "Ciao, sei una faccia\nnuova!\12Gli allenatori che\nvogliono diventare\11pro devono avere\11una politica sui POKéMON!\12Qual é il tuo\napproccio quando\11catturi i POKéMON?\12La mia politica é\nun'offensiva totale\11con POKéMON Acqua!",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "Acciderboli!\nCi sai fare!\12Va bene!\12Prendi la MEDAGLIAC.\nper dimostrare che\11mi hai battuta!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER} ha ricevuto\nla MT11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "La MT11 insegna\nBOLLARAGGIO!\12Usala su un POKéMON\nacquatico!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "Faresti meglio a\nfare spazio!",
  ["_CeruleanMartCooltrainerFText"] = "Hai visto qualche\nCARAM. RARA?\12Dovrebbe far salire\ni POKéMON di\11un livello!",
  ["_CeruleanMartCooltrainerMText"] = "Usa REPELLENTE per\ntenere insetti e POKéM.\11deboli alla larga.\12Metti il tuo POKéMON\npiu' forte in cima\11alla lista per\11risultati ottimali!",
  ["_CeruleanPokecenterGentlemanText"] = "Hai sentito parlare\ndi BILL?\12Tutti lo chiamano\nPOKéMANIAC!\12Penso che la gente\nsia solo gelosa\11di BILL.\12Chi non vorrebbe\nvantarsi dei propri\11POKéMON?",
  ["_CeruleanPokecenterGuyText"] = "BILL ha un sacco\ndi POKéMON!\12Colleziona anche\nquelli rari!",
  ["_CeruleanPokecenterSuperNerdText"] = "Quel BILL!\nHo sentito che\11fara' di tutto\11per avere POKéMON rari!",
  ["_CeruleanTradeHouseGrannyText"] = "A mio marito piacciono\nscambiare POKéMON.\12Se sei un collezionista,\nti andrebbe di\11scambiare con lui?",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "Miserabili ROCKET!\nGuarda che cosa\11hanno combinato!\12Hanno rubato una MT\nper insegnare a\11scavare a un POKéMON!\12Mi é costata un\nocchio della testa!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "Quel che é perso,\né perso!\12Ho deciso di insegnare\na DIGLETT a scavare\11senza MT!",
  ["_CeruleanTrashedHouseGirlText"] = "Il TEAM ROCKET\nstara' cercando di\11scavarsi un varco!",
  ["_CeruleanTrashedHouseWallHoleText"] = "Il TEAM ROCKET ha\nlasciato una via d'uscita!",
  ["_ChampionsRoomOakComeWithMeText"] = "OAK: {PLAYER}!\12Capisci che la tua\nvittoria non é\11dovuta solo a te!\12Il legame con i\ntuo POKéMON é\11meraviglioso!\12{PLAYER}!\nVieni con me!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "OAK: Hai vinto!\nComplimenti!\11Sei il nuovo\11campione della\11LEGA POKéMON!\12Sei cresciuto molto\nda quando sei partito\11con {RAM:wNameBuffer}!\12{PLAYER}, sei\ndiventato grande!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "OAK: {RIVAL}! Sono\ndeluso!\12Sono venuto quando\nho saputo che avevi\11battuto i SUPERQUATTRO!\12Ma quando sono arrivato,\navevi gia' perso!\12{RIVAL}! Capisci\nperché hai perso?\12Hai dimenticato di\ntratte i tuoi POKéMON\11con amore e fiducia!\12Senza di essi, non\ndiventerai mai un\11campione!",
  ["_ChampionsRoomOakText"] = "OAK: {PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "Perché?\nPerché ho perso?\12Non ho mai commesso\nerrori crescendo i\11miei POKéMON...\12Dannazione! Sei tu\nil nuovo campione\11della LEGA POKéMON!\12Anche se faccio\nfatica ad ammetterlo.",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: Ehi!\nNon vedevo l'ora\11di vederti, {PLAYER}!\12Il mio rivale deve\nessere forte!\12Mentre completavo\nil POKéDEX, ho cercato\11ovunque POKéMON forti!\12Non solo, ho creato\nsquadre in grado\11di battere ogni tipo!\12Ed ora!\nSono il campione\11della LEGA POKéMON!\12{PLAYER}! Sai cosa\nsignifica?\12Te lo dico io!\nSono l'allenatore\11piu' forte del mondo!",
  ["_ChanseyDexEntry"] = "Un POKéMON raro e\nsfuggente, che si\ndice porti\12felicita' a chi\nriesce a\ncatturarlo.",
  ["_ChargeMoveEffectText"] = "{USER}",
  ["_CharizardDexEntry"] = "Sputa fuoco capace\ndi fondere i\nmassi. A volte\12causa incendi\nboschivi senza\nvolerlo.",
  ["_CharmanderDexEntry"] = "Preferisce i\nluoghi caldi.\nQuando piove, la\12punta della sua\ncoda emette\nvapore.",
  ["_CharmeleonDexEntry"] = "Quando agita la\ncoda infuocata,\nalza la\12temperatura a\nlivelli\ninsopportabili.",
  ["_ChooseABoxText"] = "Scegli un BOX\nPOKéMON.",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "FUOCOBOMBA é\nl'ultima tecnica\11di fuoco!\12Non sprecarla sui\nPOKéMON Acqua!",
  ["_CinnabarGymBlainePreBattleText"] = "Ah!\nSono BLAINE! Sono\11il CAPOPALESTRA\11di ISOLA CANNELLA!\12I miei POKéMON di\nfuoco inceneriranno\11gli sfidanti!\12Ha! Faresti meglio\navere ANTISCOTTATURA!",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER} ha ricevuto\n{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "Sono esaurito!\nHai conquistato\11la MEDAGLIAVULCANO!",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "\12La MT38 contiene\nFUOCOBOMBA!\12Insegnala ai POKéMON\ndi tipo Fuoco!\12CHARMELEON o\nPONYTA sono ottime\11scelte!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "Fai spazio per\nil mio regalo!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "Ah!\nLa MEDAGLIAVULCANO\naccresce le abilita'\11SPECIALI dei POKéMON!\12Tieni, puoi avere\nanche questo!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}! Hai battuto\nquel testardo!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "Ehi! Futuro\ncampione!\12L'irascibile BLAINE\né un esperto di POKéM.\11Fuoco!\12Spenta il suo spirito\ncon l'acqua!\12Meglio prendere\ndelle ANTISCOTTATURA!",
  ["_CinnabarGymQuizCorrectText"] = "Risposta esatta!\nAvanti, passa pure!",
  ["_CinnabarGymQuizIncorrectText"] = "Spiacente! Sbagliato!",
  ["_CinnabarGymQuizIntroText"] = "Quiz sui POKéMON!\nRispondi bene e la\11porta si aprira'!\12Sbaglia e dovrai\naffrontare un allenatore!\12Se vuoi conservare\ni tuoi POKéMON per\11il CAPOPALESTRA...\12Rispondi bene!\nSi comincia!",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Il fuoco, o per\nessere precisi, la\11combustione...\12Blah, blah, blah,\nblah...",
  ["_CinnabarGymSuperNerd1BattleText"] = "Sai quanto puo'\nscaldarsi il fuoco\11di un POKéMON?",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "Urca!\nChe calore!",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "Non riesco a fare\na meno di rubare\11i POKéMON altrui!",
  ["_CinnabarGymSuperNerd2BattleText"] = "Ero un ladro, ma\nho messo la testa\11a posto come allenatore!",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "Mi\narrendo!",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "Le mie teorie\nsono troppo complesse\11per te!",
  ["_CinnabarGymSuperNerd3BattleText"] = "Non puoi vincere!\nHo studiato i\11POKéMON a fondo!",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "Waaa!\nI miei studi!",
  ["_CinnabarGymSuperNerd4AfterBattleText"] = "Vorrei tanto che\nesistesse un POKéMON\11ladro! Lo userei!",
  ["_CinnabarGymSuperNerd4BattleText"] = "Adoro usare i\nPOKéMON di fuoco!",
  ["_CinnabarGymSuperNerd4EndBattleText"] = "Troppo caldo\nda gestire!",
  ["_CinnabarGymSuperNerd5AfterBattleText"] = "BLAINE si era perso\ntra i monti quando\11apparve un POKéMON\11volatile infuocato.\12La sua luce aiuto'\nBLAINE a trovare\11la via d'uscita!",
  ["_CinnabarGymSuperNerd5BattleText"] = "So perché BLAINE\né diventato allenatore!",
  ["_CinnabarGymSuperNerd5EndBattleText"] = "Ahi!",
  ["_CinnabarGymSuperNerd6AfterBattleText"] = "A noi fan dei POKéM.\nFuoco piacciono PONYTA\11e NINETALES!",
  ["_CinnabarGymSuperNerd6BattleText"] = "Sono stato in molte\nPALESTRE, ma questa\11é la mia preferita!",
  ["_CinnabarGymSuperNerd6EndBattleText"] = "Urca!\nTroppo caldo!",
  ["_CinnabarGymSuperNerd7AfterBattleText"] = "L'acqua batte il\nfuoco! Ma il fuoco\11scioglie il ghiaccio!",
  ["_CinnabarGymSuperNerd7BattleText"] = "Il fuoco é debole\ncontro l'H2O!",
  ["_CinnabarGymSuperNerd7EndBattleText"] = "Oh!\nFiamma spenta!",
  ["_CinnabarIslandDoorIsLockedText"] = "La porta é\nchiusa a chiave...",
  ["_CinnabarIslandGamblerText"] = "Gli scienziati fanno\nesperimenti nell'edificio\11bruciato.",
  ["_CinnabarIslandGirlText"] = "BLAINE della PAL.\ndi ISOLA CANNELLA é\11un tipo strano che\11vive qui da decenni.",
