  ["_CinnabarLabFossilRoomScientist1SeesFossilText"] = "Oh! Quello é\n{RAM:wNameBuffer}!\12é il fossile di\n{RAM:wStringBuffer}, un\11POKéMON estinto!\12La mia Macchina della\nResurrezione lo\11fara' rivivere!",
