  ["_FuchsiaCitySafariGameSignText"] = "GIOCO SAFARI\nCATTURA-POKéMON!",
  ["_FuchsiaCitySafariZoneSignText"] = "PARADISO POKéMON\nZONA SAFARI",
  ["_FuchsiaCitySignText"] = "FUCSIAPOLI\nEcco il rosa\npassione!",
  ["_FuchsiaCitySlowpokeSignText"] = "Nome: SLOWPOKE\nAmichevole e molto\nlento nei movimenti.",
  ["_FuchsiaCityVoltorbSignText"] = "Nome: VOLTORB\nL'esatta immagine\ndi una POKé BALL.",
  ["_FuchsiaCityWardensHomeSignText"] = "ZONA SAFARI\nCASA DEL GUARDIA",
  ["_FuchsiaCityYoungster1Text"] = "Hai provato il\nGIOCO SAFARI? Alcuni\11POKéMON si trovano\11solo li'.",
  ["_FuchsiaCityYoungster2Text"] = "Quella Poké Ball\nper terra é in\11realta' un POKéMON.",
  ["_FuchsiaGoodRodHouseFishingGuruHowAreTheFishText"] = "Salve, {PLAYER}!\nCome abboccano\11i pesci?",
  ["_FuchsiaGoodRodHouseFishingGuruNoRoomText"] = "Oh no!\nNon hai spazio\11per il mio regalo!",
  ["_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText"] = "Ottimo! Mi piace\nil tuo stile!\12Prendi questo e\npesca, giovanotto!\12{PLAYER} ha ricevuto\nun {RAM:wStringBuffer}!",
  ["_FuchsiaGoodRodHouseFishingGuruText"] = "Sono il fratello\nmaggiore del GURU\11PESCATORE!\12Adoro letteralmente\npescare!\12Ti piace pescare?",
  ["_FuchsiaGoodRodHouseFishingGuruThatsSoDisappointingText"] = "Oh... Che delusione...",
  ["_FuchsiaGymGymGuideBeatKogaText"] = "é incredibile come\ni ninja terrorizzino\11ancora oggi!",
  ["_FuchsiaGymGymGuideChampInMakingText"] = "Ehi! Futuro\ncampione!\12La PALESTRA DI FUCSIAP.\né un labirinto di\11muri invisibili!\12KOGA sembra vicino,\nma é bloccato!\12Devi trovare i varchi\nnei muri per raggiungerlo!",
  ["_FuchsiaGymKogaBeforeBattleText"] = "KOGA: Fwahahaha!\nUn semplice bambino\11come te osa sfidarmi?\12Molto bene,\nti mostrero' il terrore\11di un maestro ninja!\12Proverai la disperazione\ndi veleno e sonno!",
  ["_FuchsiaGymKogaPostBattleAdviceText"] = "Se colpiti da\nTOSSINA, i POKéMON\11soffrono sempre piu'\11con l'avanzare della lotta!\12Terrorizzera' di\ncerto i nemici!",
  ["_FuchsiaGymKogaReceivedSoulBadgeText"] = "Uhm!\nHai dimostrato\11il tuo valore!\12Tieni! Prendi la\nMEDAGLIASUOLO!",
  ["_FuchsiaGymKogaReceivedTM06Text"] = "{PLAYER} ha ricevuto\n{RAM:wStringBuffer}!",
  ["_FuchsiaGymKogaSoulBadgeInfoText"] = "Ora che possiedi\nla MEDAGLIASUOLO,\11la DIFESA dei tuoi\11POKéMON aumenta!\12Ti permette anche\ndi usare SURF fuori\11dallotta!\12Ah, prendi anche\nquesto!",
  ["_FuchsiaGymKogaTM06ExplanationText"] = "\12La MT06 contiene\nTOSSINA!\12é una tecnica segreta\nvecchia di oltre\11400 anni!",
  ["_FuchsiaGymKogaTM06NoRoomText"] = "Fa' spazio per\nquesto, ragazzo!",
  ["_FuchsiaGymRocker1AfterBattleText"] = "Quindi unisci la\nforza all'ingegno?\11Buona strategia!",
  ["_FuchsiaGymRocker1BattleText"] = "La forza non é\nil fattore chiave\11per i POKéMON!\12é la strategia!\12Ti mostrero' come\nbattere la forza bruta!",
  ["_FuchsiaGymRocker1EndBattleText"] = "Cosa?\nStraordinario!",
  ["_FuchsiaGymRocker2AfterBattleText"] = "Continuero' ad\nallenarmi sotto KOGA,\nil mio maestro ninja!",
  ["_FuchsiaGymRocker2BattleText"] = "Volevo diventare\nun ninja, cosi' sono\11entrato in PALESTRA!",
  ["_FuchsiaGymRocker2EndBattleText"] = "Sono fritto!",
  ["_FuchsiaGymRocker3AfterBattleText"] = "Adoro veleno e\ntecniche di sonno,\11perché persistono\11dopo la lotta!",
  ["_FuchsiaGymRocker3BattleText"] = "Vediamo se batti\nle mie tecniche\11speciali!",
  ["_FuchsiaGymRocker3EndBattleText"] = "Mi hai\ningannato!",
  ["_FuchsiaGymRocker4AfterBattleText"] = "Mi hai impressionato!\nEcco un indizio!\12Cerca con attenzione\ni varchi nei muri\11invisibili!",
  ["_FuchsiaGymRocker4BattleText"] = "Fermati li'!\nI nostri muri\11invisibili ti\11fanno impazzire?",
  ["_FuchsiaGymRocker4EndBattleText"] = "Urca!\nCi é riuscito!",
  ["_FuchsiaGymRocker5AfterBattleText"] = "Ho ancora molto\nda imparare!",
  ["_FuchsiaGymRocker5BattleText"] = "Studio la via dei\nninja col maestro\11KOGA!\12I ninja usano gli\nanimali da sempre!",
  ["_FuchsiaGymRocker5EndBattleText"] = "Awoo!",
  ["_FuchsiaGymRocker6AfterBattleText"] = "Dove c'é luce,\nc'é ombra!\12Luce e ombra!\nQuale scegli?",
  ["_FuchsiaGymRocker6BattleText"] = "Il maestro KOGA\ndiscende da una stirpe\11di lunghi ninja!\12Tu da chi discendi?",
  ["_FuchsiaGymRocker6EndBattleText"] = "Ho perso\ni gettoni!",
  ["_FuchsiaMartCooltrainerFText"] = "Hai provato VELOCITA' X?\nAccelera un POKéMON\11in lotta!",
  ["_FuchsiaMartMiddleAgedManText"] = "Hai una bandiera\ndella ZONA SAFARI?\12E carte o calendari?",
  ["_FuchsiaMeetingRoomSafariZoneWorker1"] = "Soprannominammo\nil GUARDIA SLOWPOKE.\12Lui e il GUARDIA\nsembrano svagati!",
  ["_FuchsiaMeetingRoomSafariZoneWorker2"] = "Il GUARDIA sa moltissimo\nsui POKéMON!\12Ha persino fossili\ndi rari POKéMON\11estinti!",
  ["_FuchsiaMeetingRoomSafariZoneWorker3"] = "Il GUARDIA é entrato,\nma non si capiva.\12Credo abbia un\nproblema di parlato!",
  ["_FuchsiaPokecenterCooltrainerFText"] = "C'é uno stretto sentiero\na ovest di VIRIDIA.\12Porta al quartier\ngenerale della LEGA.\11Il Q.G. governa\11tutti gli allenatori.",
  ["_FuchsiaPokecenterRockerText"] = "Non puoi vincere\ncon un solo POKéMON\11forte.\12é dura, ma devi\ncrescerli in modo\11equilibrato.",
  ["_FullHealText"] = "La salute di\n{RAM:wNameBuffer} é tornata!",
  ["_FullyParalyzedText"] = "{USER}\né completamente paralizzato!",
  ["_GainedText"] = "{RAM:wNameBuffer} ha guadagnato\n",
  ["_GameCornerBeauty1Text"] = "Benvenuto!\nPuoi scambiare\11i gettoni per\11favolosi premi\11nella porta accanto.",
  ["_GameCornerBeauty2Text"] = "Penso che queste\nmacchine abbiano\11probabilita' diverse.",
  ["_GameCornerClerk1CantAffordTheCoinsText"] = "Non puoi permetterti\ni gettoni!",
  ["_GameCornerClerk1CoinCaseIsFullText"] = "Ops! Il SALVAGETTONI\né pieno.",
  ["_GameCornerClerk1DoYouNeedSomeGameCoinsText"] = "Benvenuto alla SALA\nGETTONI ROCKET!\12Ti servono gettoni?\nCostano Â¥1000 per\1150 gettoni. Ne vuoi?",
  ["_GameCornerClerk1DontHaveCoinCaseText"] = "Non hai il SALVAGETTONI!",
  ["_GameCornerClerk1PleaseComePlaySometimeText"] = "No? Torna a\ngiocare qualche volta!",
