  ["_GameCornerFishingGuruWinsComeAndGoText"] = "Le vittorie vanno\ne vengono.",
  ["_GameCornerGamblerText"] = "I giochi fanno paura!\né facile diventarne\11dipendenti!",
  ["_GameCornerGentlemanCloselyWatchTheReelsText"] = "Il trucco é osservare\ni rulli da vicino!",
  ["_GameCornerGentlemanReceived20CoinsText"] = "{PLAYER} ha ricevuto\n20 gettoni!",
  ["_GameCornerGentlemanThrowingMeOffText"] = "Ehi, che fai? Mi\ndistrai!\12Prendi dei gettoni,\nsgombra il campo!",
  ["_GameCornerGentlemanYouGotYourOwnCoinsText"] = "Hai gia' i tuoi\ngettoni!",
  ["_GameCornerGymGuideChampInMakingText"] = "Ehi!\nHai cose migliori\11da fare, futuro\11campione!\12La CAPOPALESTRA di\nCELASTOPOLI é ERIKA!\12Usa POKéMON Erba!\nSembra docile, ma\11non farti ingannare!",
  ["_GameCornerGymGuideTheyOfferRarePokemonText"] = "Offrono rari POKéMON\nda scambiare con\11i gettoni.\12Ma non riesco\nproprio a vincere!",
  ["_GameCornerMiddleAgedMan1Text"] = "Zitto. Si dice\nche questo posto\11sia gestito dal\11TEAM ROCKET.",
