  ["_GameCornerOutToLunchText"] = "FUORI A PRANZO\nQuesto é riservato.",
  ["_GameCornerPosterSwitchBehindPosterText"] = "Ehi!\nUn interruttore\11dietro il poster!?\11Premiamolo!",
