  ["_GolbatDexEntry"] = "Una volta che\ncolpisce, non\nsmette di\12risucchiare\nenergia dalla\nvittima anche se\12diventa troppo\npesante per\nvolare.",
  ["_GoldeenDexEntry"] = "La pinna caudale\nsvolazza come un\nelegante abito da\12ballo, valendogli\nil titolo di\nRegina del Mare.",
