  ["_GrimerDexEntry"] = "Compare in zone\nsporche. Vive\nassorbendo i\12rifiuti inquinati\npompati fuori\ndalle fabbriche.",
  ["_GroundRoseText"] = "Il terreno si é\nsollevato altrove!",
  ["_GrowlitheDexEntry"] = "Molto protettivo\nverso il suo\nterritorio. Abbaia\12e morde per\nrespingere gli\nintrusi.",
  ["_GyaradosDexEntry"] = "Raro da vedere in\nnatura. Enorme e\nferoce, é in grado\12di radere al suolo\nintere citta' in\nun raptus.",
  ["_GymStatueText1"] = "{RAM:wGymCityName}\nPALESTRA POKéMON\11CAPOPALESTRA: {RAM:wGymLeaderName}\12ALLENATORI VINCENTI:\n{RIVAL}",
  ["_GymStatueText2"] = "{RAM:wGymCityName}\nPALESTRA POKéMON\11CAPOPALESTRA: {RAM:wGymLeaderName}\12ALLENATORI VINCENTI:\n{RIVAL}\11{PLAYER}",
  ["_HMCantDeleteText"] = "Le tecniche MN\nnon si cancellano!",
  ["_HallOfFameOakText"] = "OAK: Ekhm!\nCongratulazioni\11{PLAYER}!\12Questo piano é la\nSALA MAGNA POKéMON!\12I campioni della\nLEGA POKéMON\11vengono onorati\11qui per le loro\11imprese!\12Anche i loro\nPOKéMON sono\11registrati nella\11SALA MAGNA!\12{PLAYER}! Hai\nlottato duro per\11diventare il\11nuovo campione!\12Congratulazioni,\n{PLAYER}, tu e\11i tuoi POKéMON\11entrate nella SALA!",
  ["_HasSubstituteText"] = "{USER}\nha un SOSTITUTO!",
  ["_HaunterDexEntry"] = "Grazie alla sua\ncapacita' di\nattraversare i\12muri, si dice\nprovenga da altra\ndimensione.",
  ["_HereYouGoText"] = "Prego!",
  ["_HiddenItemBagFullText"] = "Ma {PLAYER} non\nha piu' spazio per\11altri strumenti!",
