  ["_HitmonchanDexEntry"] = "Senza apparente\nmovimento, sferra\nraffiche di pugni\12cosi' veloci da\nessere impossibili\nda vedere.",
  ["_HitmonleeDexEntry"] = "Quando ha fretta,\nle sue zampe si\nallungano\12progressivamente,\npercorrendo lunghi\npassi fluidi.",
  ["_HookedMonAttackedText"] = "Il {RAM:wEnemyMonNick}\nallamato ha\11attaccato!",
  ["_HorseaDexEntry"] = "Noto per abbattere\ninsetti volanti\ncon precisione\12grazie a getti di\ninchiostro\ndall'acqua.",
  ["_HurtByBurnText"] = "{USER}\né ferito dalla\nscottatura!",
  ["_HurtByLeechSeedText"] = "PARASSITA prosciuga\n{USER}!",
  ["_HurtByPoisonText"] = "{USER}\né ferito dal\nveleno!",
  ["_HurtItselfText"] = "Si é ferito da\nsolo nella confusione!",
  ["_HypnoDexEntry"] = "Quando fissa un\nnemico, usa varie\nmosse PSI come\12IPNOSI e\nCONFUSIONE.",
  ["_IceHealText"] = "{RAM:wNameBuffer} é\nscongelato!",
  ["_IgnoredOrdersText"] = "{RAM:wBattleMonNick}\nignora gli ordini!",
  ["_IndigoPlateauHQText"] = "Altopiano INDACO\nSEDE LEGA POKéMON",
  ["_IndigoPlateauLobbyCooltrainerFText"] = "Da qui in poi,\naffronterai i SUPER\11QUATTRO uno a uno!\12Se vinci, si apre\nla porta per il\11successivo!\11Buona fortuna!",
  ["_IndigoPlateauLobbyGymGuideText"] = "Ehila'! Campione\nin erba!\12Alla LEGA POKéMON\ndevi affrontare i\11SUPER QUATTRO.\12Se perdi, ricominci\nda capo! Ci siamo!\12Dacci dentro!",
  ["_IndigoPlateauStatuesText1"] = "ALTOPIANO INDACO",
  ["_IndigoPlateauStatuesText2"] = "L'obiettivo degli\nallenatori!\11SEDE LEGA POKéMON",
  ["_IndigoPlateauStatuesText3"] = "La massima\nautorita' POKéMON\11SEDE LEGA POKéMON",
  ["_IntoText"] = "\nsu {RAM:wNameBuffer}!",
  ["_IntroducePlayerText"] = "Innanzitutto,\ncome ti chiami?",
  ["_IntroduceRivalText"] = "Questo é mio\nnipote. é il tuo\11rivale da quando\11eravate piccoli.\12...Mhm, qual era\nil suo nome?",
  ["_IsConfusedText"] = "{USER}\né confuso!",
  ["_IsEvolvingText"] = "Cosa? {RAM:wStringBuffer}\nsta' evolvendosi!",
