  ["_ItemUseBallText03"] = "Oh! Sembrava\ncatturato! ",
  ["_ItemUseBallText04"] = "Acciderboli! Ci\neravamo quasi!",
  ["_ItemUseBallText05"] = "Ottimo!\n{RAM:wEnemyMonNick}\ncatturato!",
  ["_ItemUseBallText06"] = "Nuovi dati del\nPOKéDEX per\11{RAM:wEnemyMonNick}!",
