  ["_ItemUseNoEffectText"] = "Non ha alcun\neffetto.",
  ["_ItemUseNotTimeText"] = "OAK: {PLAYER}!\nNon é il momento\11di usarlo! ",
  ["_ItemUseNotYoursToUseText"] = "Questo non é\ntuo!",
  ["_ItemUseText001"] = "{PLAYER} usa",
  ["_ItemUseText002"] = "{RAM:wStringBuffer}!",
  ["_ItemWasStoredText"] = "{RAM:wNameBuffer} é\nstato depositato via PC.",
  ["_ItemfinderFoundItemText"] = "Si'! Il CERCASTRUMENTI\nindica che c'é\11uno strumento vicino.",
  ["_ItemfinderFoundNothingText"] = "No! Il CERCASTRUMENTI\nnon risponde.",
  ["_ItemsCantBeUsedHereText"] = "Non si possono\nusare strumenti qui.",
  ["_ItsABiteText"] = "Oh!\nAbboccano!",
  ["_IvysaurDexEntry"] = "Quando il bulbo\nsulla sua schiena\ncresce, sembra\12perdere la forza\ndi reggersi sulle\nzampe posteriori.",
  ["_JigglypuffDexEntry"] = "Quando i grandi\nocchi si\nilluminano, canta\12una dolce melodia\nche fa\naddormentare i\12nemici.",
  ["_JolteonDexEntry"] = "Accumula ioni\nnegativi nell'aria\nper scagliare\12fulmini da 10000\nvolt.",
  ["_JustAMomentText"] = "Un momento.",
  ["_JynxDexEntry"] = "Ancheggia\nsaduttivamente\nmentre cammina,\12inducendo la gente\na ballare in\nsintonia con lui.",
  ["_KabutoDexEntry"] = "Un POKéMON risorto\nda un fossile\ntrovato molto\12tempo fa nel fondo\noceanico.",
  ["_KabutopsDexEntry"] = "La sua forma\nsaffilata é ideale\nper nuotare.\12Taglia la preda\ncon gli artigli e\nne beva i fluidi.",
  ["_KabutopsFossilText"] = "Fossile KABUTOPS\nUn POKéMON\11primitivo e raro.",
  ["_KadabraDexEntry"] = "Emette speciali\nonde alfa dal\ncorpo che causano\12emicrania a chi si\ntrova nelle\nvicinanze.",
  ["_KakunaDexEntry"] = "Quasi incapace di\nmuoversi, puo'\nsolo indurire il\12guscio per\nproteggersi dai\npredatori.",
  ["_KangaskhanDexEntry"] = "Il piccolo esce\nraramente dalla\ntasca protettiva\12della madre finché\nnon compie 3 anni.",
  ["_KeptGoingAndCrashedText"] = "{USER}\ncontinua e si\11schianta!",
  ["_KinglerDexEntry"] = "La chela grande ha\nuna potenza di\nschiacciamento.\12Tuttavia, le\ngrandi dimensioni\nla rendono\12pesante.",
  ["_KoffingDexEntry"] = "Poiché immagazzina\nvari gas tossici\nnel corpo, rischia\12di esplodere senza\nalcun preavviso.",
  ["_KrabbyDexEntry"] = "Le sue chele non\nsono solo potenti\narmi, ma servono\12per mantenere\nl'equilibrio\ncamminando.",
  ["_LancesRoomLanceAfterBattleText"] = "Non posso ancora\ncredere che i miei\11draghi abbiano\11perso, {PLAYER}!\12Ora sei tu il\ncampione della\11LEGA POKéMON!\12O meglio, lo saresti\nse non avessi un\11ultimo ostacolo.\12Devi affrontare\nun altro allenatore!\11Il suo nome é...\12{RIVAL}!\nHa battuto i SUPER\11QUATTRO prima di te!\12é lui il vero\ncampione della\11LEGA POKéMON!",
  ["_LancesRoomLanceBeforeBattleText"] = "Ah! Ho sentito\nparlare di te!\12Io sono il capo dei\nSUPER QUATTRO!\nMi chiamo LANCE e\11addestro draghi!\12Sai che i draghi\nsono POKéMON\11mitologici!\12Sono difficili da\ncatturare, ma la\11loro potenza é\11superiore!\12Sono praticamente\nindistruttibili!\12Bene, pronto a\nperdere?\12La tua sfida finisce\nqui, {PLAYER}!",
  ["_LancesRoomLanceEndBattleText"] = "Basta!\nOdio ammetterlo,\nma sei un maestro\11di POKéMON!",
  ["_LaprasDexEntry"] = "Un POKéMON\ncacciato quasi\nfino\12all'estinzione.\nPuo' traghettare\nle persone\12sull'acqua.",
  ["_LavenderCuboneHouseBrunetteGirlGhostIsGoneText"] = "Il FANTASMA della\nTORRE POKéMON é\11sparito!\12Qualcuno deve aver\nplacato la sua\11anima irrequieta!",
  ["_LavenderCuboneHouseBrunetteGirlPoorCubonesMotherText"] = "Odio quei\norribili ROCKET!\12La madre di quel\npovero CUBONE...\12é stata uccisa\ncercando di\11fuggire dal TEAM!",
  ["_LavenderCuboneHouseCuboneText"] = "CUBONE: Kyarugoo!",
  ["_LavenderMartBaldingGuyText"] = "Cerco strumenti\nche aumentano le\11abilita' dei POKéMON\11durante una\11lotta.\12ATTACCO X, DIFESA\nX, VELOCITA' X e\11SPECIAL X.\12Sai dove trovarli?",
  ["_LavenderMartCooltrainerMNuggetText"] = "Ho trovato una\nPEPITA sui monti.\12Pensavo fosse\ninutile, ma l'ho\11venduta a ¥5000!",
  ["_LavenderMartCooltrainerMReviveText"] = "Conosci REVITALIZ.?\nRivitalizza qualsiasi\11POKéMON esausto!",
  ["_LavenderPokecenterGentlemanText"] = "Il TEAM ROCKET\nfarebbe di tutto\11per il denaro!",
  ["_LavenderPokecenterGuyText"] = "I CUBONE portano\ni teschi, vero?\12La gente li paga\nmolto!",
  ["_LavenderPokecenterLittleGirlText"] = "Ho visto la madre\ndi CUBONE morire\11sfuggendo al TEAM\11ROCKET!",
  ["_LavenderTownCooltrainerMText"] = "Questa citta' é\nnota come il\11cimitero dei POKéMON.\12Si tengono\ncommemorazioni\11nella TORRE.",
  ["_LavenderTownLittleGirlDoYouBelieveInGhostsText"] = "Credi nei\nFANTASMI?",
  ["_LavenderTownLittleGirlHaHaGuessNotText"] = "Ahahah, immagino\ndi no.\12Quella mano bianca\nsulla tua spalla,\11non é vera.",
  ["_LavenderTownLittleGirlSoThereAreBelieversText"] = "Davvero? Quindi\nci sono credenti...",
  ["_LavenderTownPokemonHouseSignText"] = "CASA POKéMON\nVOLONTARI DI LAVANDULA",
  ["_LavenderTownPokemonTowerSignText"] = "Che le anime dei\nPOKéMON riposino\11TORRE POKéMON",
  ["_LavenderTownSignText"] = "LAVANDULA\nLa nobile citta'\11violacea",
  ["_LavenderTownSilphScopeSignText"] = "Nuovo SCOPISILPH!\12Rendi l'invisibile\nvisibile agli occhi!\12SILPH S.P.A.",
  ["_LavenderTownSuperNerdText"] = "I FANTASMI sono\napparsi nella TORRE.\12Credo siano gli\nspiriti dei POKéMON\11uccisi dai ROCKET.",
  ["_LearnedMove1Text"] = "{RAM:wLearnMoveMonName}\nha imparato\11{RAM:wStringBuffer}!",
  ["_LickitungDexEntry"] = "La lingua puo'\nessere estesa come\nquella di un\12camaleonte. Lascia\nun formicolio\nquando lecca.",
  ["_LightScreenProtectedText"] = "{USER}\né protetto dagli\11attacchi speciali!",
  ["_LinedUpText"] = " in fila!\nVinte {RAM:wStringBuffer} monete!",
  ["_LinkBattleLostText"] = "{PLAYER} ha perso\ncontro {RAM:wTrainerName}!",
  ["_LinkCableHelpText1"] = "CONSIGLI\12Uso del Cavo Link",
  ["_LinkCableHelpText2"] = "Quale voce vuoi\nleggere?",
  ["_LinkCableInfoText1"] = "Collegato un\nGAME BOY a un\11altro, parla con\11l'addetto a destra\11in qualsiasi\11CENTRO POKéMON.",
  ["_LinkCableInfoText2"] = "Il COLOSSEO ti\npermette di lottare\11contro un amico.",
  ["_LinkCableInfoText3"] = "Il CENTRO SCAMBI\nserve per scambiare\11i POKéMON.",
  ["_LinkCanceledText"] = "Il collegamento\né stato annullato.",
  ["_LoafingAroundText"] = "{RAM:wBattleMonNick}\nbighellona.",
  ["_LoreleisRoomLoreleiAfterBattleText"] = "Sei meglio di\nquanto pensassi!\12Avanti! Hai solo\nassaggiato la\11potenza della LEGA!",
  ["_LoreleisRoomLoreleiBeforeBattleText"] = "Benvenuto alla\nLEGA POKéMON!\12Io sono LORELEI\ndei SUPER QUATTRO!\12Nessuno mi batte\ncon i POKéMON\11di ghiaccio!\12Le mosse gelide\nsono potenti!\12I tuoi POKéMON\nsaranno alla mia\11misericordia!\12Ahahah!\nSei pronto?",
  ["_LoreleisRoomLoreleiDontRunAwayText"] = "Voce misteriosa:\nNon scappare!",
  ["_LoreleisRoomLoreleiEndBattleText"] = "Come\nosi!",
  ["_LoweredItsHeadText"] = "\nchina la testa!",
  ["_MachampDexEntry"] = "Con i suoi forti\nmuscoli, sferra\npugni potenti che\12possono scagliare\nla vittima oltre\nl'orizzonte.",
  ["_MachokeDexEntry"] = "Il suo corpo\nmuscoloso é cosi'\npotente che deve\12indossare una\ncintura per\nregolarne i moti.",
  ["_MachopDexEntry"] = "Adora sviluppare i\nmuscoli. Si allena\nin ogni stile di\12lotta marziale per\ndiventare forte.",
  ["_MadeWhirlwindText"] = "\ncrea un turbine!",
  ["_MagazinesText"] = "Riviste POKéMON!\12Quaderni POKéMON!\12Grafici POKéMON!",
  ["_MagikarpDexEntry"] = "In un lontano\npassato era un po'\npiu' forte di\12questi deboli\ndiscendenti\nesistenti oggi.",
  ["_MagmarDexEntry"] = "Il suo corpo\nbrucia con un\nbagliore arancione\12che gli permette\ndi nascondersi tra\nle fiamme.",
  ["_MagnemiteDexEntry"] = "Usa l'antigravita'\nper restare\nsospeso. Compare\12senza preavviso\nusando TUONOSHOCK\ne simili.",
  ["_MagnetonDexEntry"] = "Formato da vari\nMAGNEMITE uniti.\nCompaiono spesso\12quando le macchie\nsolari si\ninfiammano.",
  ["_MankeyDexEntry"] = "Estremamente\nirritabile. Puo'\nessere docile un\12momento e poi\ninfiltrarsi in un\nattacco furente.",
  ["_MarowakDexEntry"] = "L'osso che porta é\nla sua arma. Lo\nlancia abilmente\12come un boomerang\nper mandare KO i\nbersagli.",
  ["_MartSignText"] = "Ogni strumento\nsoddisfa i bisogni!\11BOTTEGA POKéMON",
  ["_MeowthDexEntry"] = "Adora gli oggetti\ncircolari. Gira di\nnotte per le\12strade in cerca di\nspiccioli caduti.",
  ["_MetapodDexEntry"] = "Questo POKéMON é\nvulnerabile agli\nattacchi finché il\12guscio é morbido,\nesponendo il corpo\ntenero.",
  ["_MewDexEntry"] = "Cosi' raro che\nmolti esperti lo\nritengono un\12miraggio. Pochi lo\nhanno visto in\ntutto il mondo.",
  ["_MewtwoBattleText"] = "Mew!",
  ["_MewtwoDexEntry"] = "Creato da uno\nscienziato dopo\nanni di orribili\12esperimenti di\ningegneria\ngenetica e DNA.",
  ["_MimicLearnedMoveText"] = "{USER}\nha imparato\11{RAM:wNameBuffer}!",
  ["_MirrorMoveFailedText"] = "SPECCHIOMOSSA\nfallita!",
  ["_MoltresDexEntry"] = "Noto come\nl'uccello\nleggendario del\12fuoco. Ogni\nbattito delle ali\ncrea un\12abbagliante lampo\ndi fiamme.",
  ["_MonCannotLearnMachineMoveText"] = "{RAM:wNameBuffer} non é\ncompatibile con\11{RAM:wStringBuffer}.\12Non puo' imparare\n{RAM:wStringBuffer}.",
  ["_MonIsTakenOutText"] = "{RAM:wStringBuffer} é\nestratto.\11Ottenuto {RAM:wStringBuffer}.",
  ["_MonWasReleasedText"] = "{RAM:wStringBuffer} é\nliberato fuori.\11Ciao {RAM:wStringBuffer}!",
  ["_MonWasStoredText"] = "{RAM:wStringBuffer} é\nnel Box {RAM:wBoxNumString}.",
  ["_MoneyForWinningText"] = "{PLAYER} vince\n¥{NUM:wAmountMoneyWon, 3 | LEADING_ZEROES | LEFT_ALIGN}!",
  ["_MonsStatsFellText"] = "Il {RAM:wStringBuffer}\ndi {TARGET}",
  ["_MonsStatsRoseText"] = "Il {RAM:wStringBuffer}\ndi {USER}",
  ["_MoveDisabledText"] = "La mossa é\ndisattivata!",
  ["_MoveIsDisabledText"] = "Il {RAM:wNameBuffer}\ndi {USER} é\11disattivato!",
  ["_MoveNameText"] = "{RAM:wStringBuffer}!",
  ["_MoveNoPPText"] = "PP esauriti per\nquesta mossa!",
  ["_MoveWasDisabledText"] = "Il {RAM:wNameBuffer}\ndi {TARGET} é\11disattivato!",
  ["_MrFujisHouseLittleGirlPokemonAreNiceToHugText"] = "é cosi' caldo!\nI POKéMON sono\11belli da abbracciare!",
  ["_MrFujisHouseLittleGirlThisIsMrFujisHouseText"] = "Questa é la casa\ndi MR. FUJI.\12é molto gentile!\12Cura i POKéMON\nabbandonati e\11orfani!",
  ["_MrFujisHouseMrFujiHasMyFluteHelpedYouText"] = "MR. FUJI: Ti é\nutile il mio FLAUTO?",
  ["_MrFujisHouseMrFujiIThinkThisMayHelpYourQuestText"] = "MR. FUJI: {PLAYER}.\12La tua ricerca del\nPOKéDEX fallira'\11senza amore per\11i POKéMON.\12Penso che questo\nti aiutera'.",
  ["_MrFujisHouseMrFujiPokeFluteExplanationText"] = "\12Al suono del FLAUTO\nPOKéMON, quelli\11addormentati\11si sveglieranno.\12Funziona con tutti\ni POKéMON dormienti.",
  ["_MrFujisHouseMrFujiPokeFluteNoRoomText"] = "Devi fare\nspazio per questo!",
  ["_MrFujisHouseMrFujiPokedexText"] = "Lotteria Mensile\nGrandioso Premio!\12Il modulo é...\12Sparita! é stata\nritagliata!",
  ["_MrFujisHouseMrFujiReceivedPokeFluteText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_MrFujisHouseNidorinoText"] = "NIDORINO: Gaoo!",
  ["_MrFujisHousePsyduckText"] = "PSYDUCK: Gwappa!",
  ["_MrFujisHouseSuperNerdMrFujiHadBeenPrayingText"] = "MR. FUJI pregava\nda solo per la\11madre di CUBONE.",
  ["_MrFujisHouseSuperNerdMrFujiIsntHereText"] = "Strano, MR. FUJI\nnon c'é.\11Dove sara' andato?",
  ["_MrMimeDexEntry"] = "Se viene\ninterrotto mentre\nmima, prendera' a\12sberle il\ncolpevole con le\nsue grandi mani.",
  ["_MrPsychicsHouseMrPsychicReceivedTM29Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_MrPsychicsHouseMrPsychicTM29ExplanationText"] = "MT29 é PSICHICO!\12Puo' ridurre le\nabilita' SPECIALI\11del bersaglio.",
  ["_MrPsychicsHouseMrPsychicTM29NoRoomText"] = "Dove pensi di\nmettere questo?",
  ["_MrPsychicsHouseMrPsychicYouWantedThisText"] = "...Aspetta! Non\ndire una parola!\12Lo volevi!",
  ["_MtMoon1FBewareZubatSign"] = "Attenzione! ZUBAT\né un succhiasangue!",
  ["_MtMoon1FCooltrainerF1AfterBattleText"] = "Come si esce\nda qui?",
  ["_MtMoon1FCooltrainerF1BattleText"] = "Wow! Qui dentro\né molto piu' grande\11di quanto credessi!",
  ["_MtMoon1FCooltrainerF1EndBattleText"] = "Oh!\nHo perso!",
  ["_MtMoon1FCooltrainerF2AfterBattleText"] = "Ho sentito che\nci sono fossili\11molto rari qui.",
  ["_MtMoon1FCooltrainerF2BattleText"] = "Cosa? Aspetto\ni miei amici qui.",
  ["_MtMoon1FCooltrainerF2EndBattleText"] = "Ho perso?",
  ["_MtMoon1FHikerAfterBattleText"] = "I ragazzi come\nte non dovrebbero\11stare qui!",
  ["_MtMoon1FHikerBattleText"] = "UAU! Mi hai\nspaventato! Ah, sei\11solo un ragazzo!",
  ["_MtMoon1FHikerEndBattleText"] = "Acciderboli!\nSpaventato di\11nuovo!",
  ["_MtMoon1FSuperNerdAfterBattleText"] = "Devo trovare\nPOKéMON piu' forti.",
  ["_MtMoon1FSuperNerdBattleText"] = "Cosa! Non\nprendermi alle\11spalle!",
  ["_MtMoon1FSuperNerdEndBattleText"] = "Il mio POKéMON\nnon basta!",
  ["_MtMoon1FYoungster1AfterBattleText"] = "Sono venuto qui\nper fare il bullo\11con le ragazze.",
  ["_MtMoon1FYoungster1BattleText"] = "Sei venuto anche\ntu a esplorare?",
  ["_MtMoon1FYoungster1EndBattleText"] = "Perdere é\nuno schifo!",
  ["_MtMoon1FYoungster2AfterBattleText"] = "Li ho visti!\nSono sicuro siano\11del TEAM ROCKET!",
  ["_MtMoon1FYoungster2BattleText"] = "Uomini sospetti\nnella grotta.\11E tu?",
  ["_MtMoon1FYoungster2EndBattleText"] = "Mi hai\npreso!",
  ["_MtMoon1FYoungster3AfterBattleText"] = "ZUBAT é tosto!\nMa puo' essere\11utile se ne\11catturi uno.",
  ["_MtMoon1FYoungster3BattleText"] = "Attraversa la\ngrotta per arrivare\11a CELESTOPOLI!",
  ["_MtMoon1FYoungster3EndBattleText"] = "Ho\nperso.",
  ["_MtMoonB2FDomeFossilYouWantText"] = "Vuoi il\nFossile Dome?",
  ["_MtMoonB2FHelixFossilYouWantText"] = "Vuoi il\nFossile Helix?",
  ["_MtMoonB2FReceivedFossilText"] = "{PLAYER} ottiene\n{RAM:wStringBuffer}!",
  ["_MtMoonB2FRocket1AfterBattleText"] = "Mi hai fatto\narrabbiare! Il TEAM\11ti mettera' al bando!",
  ["_MtMoonB2FRocket1BattleText"] = "Il TEAM ROCKET\ntrovera' i fossili,\11li rivendera' per\11fare soldi!",
  ["_MtMoonB2FRocket1EndBattleText"] = "Argh!\nOra sono furioso!",
  ["_MtMoonB2FRocket2AfterBattleText"] = "Mannaggia!\nI miei soci non\11la passeranno liscia!",
  ["_MtMoonB2FRocket2BattleText"] = "Noi del TEAM\nROCKET siamo\11gangster POKéMON!",
  ["_MtMoonB2FRocket2EndBattleText"] = "Ho rovinato\ntutto!",
  ["_MtMoonB2FRocket3AfterBattleText"] = "Se trovi un\nfossile, dammelo\11e sparisci!",
  ["_MtMoonB2FRocket3BattleText"] = "Facciamo un\naffare grosso qui!\12Sparisci, moccioso!",
  ["_MtMoonB2FRocket3EndBattleText"] = "Vedo che\nsei bravo.",
  ["_MtMoonB2FRocket4AfterBattleText"] = "I POKéMON vivevano\nqui molto prima\11dell'uomo.",
  ["_MtMoonB2FRocket4BattleText"] = "I bambini non\ndovrebbero seccare\11gli adulti!",
  ["_MtMoonB2FRocket4EndBattleText"] = "Che\nrabbia!",
  ["_MtMoonB2FSuperNerdOkIllShareText"] = "Va bene!\nLo divideremo!",
  ["_MtMoonB2FSuperNerdThenThisIsMineText"] = "D'accordo. Allora\nquesto é mio!",
  ["_MtMoonB2FSuperNerdTheresAPokemonLabText"] = "Lontano, all'ISOLA\nCANNELLA, c'é un\11LABORATORIO POKéMON.\12Studiano la\nrigenerazione dei\11fossili.",
  ["_MtMoonB2FSuperNerdTheyreBothMineText"] = "Ehi, ferma!\nLi ho trovati io!\11Sono entrambi miei!",
  ["_MtMoonB2FYouHaveNoRoomText"] = "Senti, non hai\nspazio per questo.",
  ["_MtMoonB2fSuperNerdEachTakeOneText"] = "Ne prendiamo uno\na testa!\11Niente ingordigia!",
  ["_MtMoonPokecenterBenchGuyText"] = "Se hai troppi\nPOKéMON, puoi\11depositarli al PC!",
  ["_MtMoonPokecenterGentlemanText"] = "Il TEAM ROCKET\nattacca i cittadini\11di CELESTOPOLI...\12Il TEAM ROCKET é\nsempre in prima\11pagina!",
  ["_MtMoonPokecenterMagikarpSalesmanIGotADealText"] = "UOMO: Salve!\nHo un affare\11proprio per te!\12Ti do un magnifico\nMAGIKARP per\11soli ¥500!\11Che ne dici?",
  ["_MtMoonPokecenterMagikarpSalesmanNoMoneyText"] = "Ti servono piu'\nsoldi di cosi'!",
  ["_MtMoonPokecenterMagikarpSalesmanNoRefundsText"] = "UOMO: Be', io\nnon faccio rimborsi!",
  ["_MtMoonPokecenterMagikarpSalesmanNoText"] = "No? Lo faccio\nsolo come favore\11per te!",
  ["_MtMoonPokecenterYoungsterText"] = "Ho 6 POKé BALL\npronte alla cintura.\12Al massimo puoi\nportare 6 POKéMON.",
  ["_MukDexEntry"] = "Fittamente coperto\ndi melma vile e\ndisgustosa. Molto\12tossico, anche le\nsue orme lasciano\nveleno.",
  ["_MultiHitText"] = "Colpisce il nemico\n{NUM:wPlayerNumHits, 1, 1} volte!",
  ["_Museum1FGamblerText"] = "Questo é un\nmagnifico\11fossile!",
  ["_Museum1FOldAmberText"] = "L'AMBRA é lucida\ne dorata!",
  ["_Museum1FScientist1AmberIsFossilizedTreeSapText"] = "L'AMBRA é linfa\nd'albero fossile.",
  ["_Museum1FScientist1ComeAgainText"] = "Torna presto!",
  ["_Museum1FScientist1DoYouKnowWhatAmberIsText"] = "Non puoi intrufolarti\ndal retro!\12Oh, insomma!\nSai cos'é\11l'AMBRA?",
  ["_Museum1FScientist1DontHaveEnoughMoneyText"] = "Non hai abbastanza\nsoldi.",
  ["_Museum1FScientist1GoToOtherSideText"] = "Prego, passa\ndall'altra parte!",
  ["_Museum1FScientist1TakePlentyOfTimeText"] = "Prenditi tutto\nil tempo per vederlo!",
  ["_Museum1FScientist1ThankYouText"] = "Ecco, ¥50!\nGrazie!",
  ["_Museum1FScientist1TheresALabSomewhereText"] = "C'é un laboratorio\nda qualche parte\11che cerca di\11resuscitare POKéMON\11antichi dall'AMBRA.",
  ["_Museum1FScientist1WouldYouLikeToComeInText"] = "Il biglietto costa\n¥50 per i bambini.\12Vuoi entrare?",
  ["_Museum1FScientist2GetTheOldAmberCheckText"] = "Ssh! Fai\nanalizzare l'AMBRA\11ANTICA!",
  ["_Museum1FScientist2ReceivedOldAmberText"] = "{PLAYER} riceve\nAMBRA ANTICA!",
  ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "Ssh! Credo che\nquesto pezzo di\11AMBRA contenga\11DNA di POKéMON!\12Sarebbe fantastico\nresuscitare un\11POKéMON da esso!\12Ma i miei colleghi\nmi ignorano!\12Percio' ho un\nfavore da chiederti:\11portalo a un\11LABORATORIO POKéMON!",
  ["_Museum1FScientist2YouDontHaveSpaceText"] = "Non hai spazio\nper questo!",
  ["_Museum1FScientist3Text"] = "Siamo fieri di\ndue fossili di\11rarissimi POKéMON\11preistorici!",
  ["_Museum2FBrunetteGirlText"] = "Voglio un PIKACHU!\né cosi' carino!\12Ho chiesto a papa'\ndi catturarmene uno!",
  ["_Museum2FGrampsText"] = "20 luglio 1969!\nIl 1° allunaggio!\12Ho comprato una\ntelevisione a colori\11per vederlo!",
  ["_Museum2FHikerText"] = "Si', un PIKACHU\narrivera' presto!",
  ["_Museum2FMoonStoneSignText"] = "Meteorite caduto\nnel MONTE LUNA.\11(PIETRALUNARE?)",
  ["_Museum2FScientistText"] = "Abbiamo una mostra\nspaziale in corso.",
  ["_Museum2FSpaceShuttleSignText"] = "NAVETTA SPAZIALE\nCOLUMBIA",
  ["_Museum2FYoungsterText"] = "PIETRALUNARE?\nCosa c'é di cosi'\nspeciale?",
  ["_MustRechargeText"] = "{USER}\ndeve ricaricarsi!",
  ["_NameRatersHouseNameRaterATrulyImpeccableNameText"] = "{RAM:wNameBuffer}, eh?\né un nome davvero\11impeccabile!\12Abbi cura di\n{RAM:wNameBuffer}!",
  ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "Va bene! Torna\nquando vuoi!",
  ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "{RAM:wNameBuffer}, eh?\né un soprannome\11decente!\12Ma vuoi che gli\ndia un nome piu'\11carino?\12Che ne pensi?",
  ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "Ok! Questo POKéMON\nora si chiama\11{RAM:wBuffer}!\12é un nome migliore\ndi prima!",
  ["_NameRatersHouseNameRaterWantMeToRateText"] = "Salve, salve!\nSono il GIUDICE\11ONORARIO!\12Vuoi che valuti\ni soprannomi dei\11tuoi POKéMON?",
  ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "Va bene! Come\nlo chiamiamo?",
  ["_NameRatersHouseNameRaterWhichPokemonText"] = "Quale POKéMON\ndeve essere esaminato?",
  ["_NeedYourPokemonText"] = "Ok. Ci serve\nil tuo POKéMON.",
  ["_NewBadgeRequiredText"] = "No! Serve una\nnuova MEDAGLIA.",
  ["_NewBicycleText"] = "Una nuova e\nlucente BICICLETTA!",
  ["_NidokingDexEntry"] = "Usa la potente\ncoda in battaglia\nper schiacciare,\12stringere e infine\nrompere le ossa\nalla preda.",
  ["_NidoqueenDexEntry"] = "Le sue squame dure\noffrono una solida\nprotezione. Usa la\12sua stazza per\nsferrare potenti\nmosse.",
  ["_NidoranFDexEntry"] = "Sebbene piccolo, i\nsuoi aculei\nvelenosi rendono\12questo POKéMON\npericoloso. La\nfemmina ha corna.",
  ["_NidoranMDexEntry"] = "Irridisce le\norecchie per\npercepire i\12pericoli. Piu' le\ncorna sono grandi,\npiu' il veleno\12secreto é potente.",
  ["_NidorinaDexEntry"] = "Il corno della\nfemmina cresce\nlentamente.\12Preferisce\nattacchi fisici\ncome graffi e\12morsi.",
  ["_NidorinoDexEntry"] = "Un POKéMON\naggressivo e\nrapido\12nell'attaccare. Il\ncorno sulla testa\nsecreta un veleno\12potente.",
  ["_NinetalesDexEntry"] = "Molto intelligente\ne vendicativo.\nAfferrare una\12delle sue code\npuo' causare una\nmaledizione\12millenaria.",
  ["_NoCyclingAllowedHereText"] = "Qui non si puo'\nusare la bici.",
  ["_NoEffectText"] = "Non ha effetto!",
  ["_NoMonText"] = "Cosa? Non ci sono\nPOKéMON qui!",
  ["_NoMoreRoomForItemText"] = "Spazio esaurito\nper gli strumenti!",
  ["_NoMovesLeftText"] = "{RAM:wBattleMonNick} non\nha piu' mosse!",
  ["_NoNibbleText"] = "Neanche un'abboccata!",
  ["_NoRoomToStoreText"] = "Nessun spazio per\ndepositare strumenti.",
  ["_NoRunningText"] = "No! Non si puo'\nfuggire da una\11lotta fra allenatori!",
  ["_NoSurfingHereText"] = "Non si puo' USARE\nSURF su {RAM:wNameBuffer} qui!",
  ["_NoTrade1Text"] = "Uffa!\nVabbé...",
  ["_NoTrade2Text"] = "Be', se non\nlo vuoi tu...",
  ["_NoTrade3Text"] = "Che peccato.",
  ["_NoWillText"] = "Manca la voglia\ndi combattere!",
  ["_NotEnoughCoinsSlotMachineText"] = "Monete\ninsufficienti!",
  ["_NotHealthyEnoughText"] = "Non é abbastanza\nsalutare.",
  ["_NotThisTimeText"] = "Non questa volta!",
  ["_NotVeryEffectiveText"] = "Non é molto\nefficace...",
  ["_NothingHappenedText"] = "Non é accaduto\nnulla!",
  ["_NothingHereText"] = "Sembra che non\nci sia nulla.",
  ["_NothingStoredText"] = "Non c'é nulla\ndepositato.",
  ["_NothingToCutText"] = "Non c'é nulla\nda TAGLIARE!",
  ["_NothingToDepositText"] = "Non hai nulla\nda depositare.",
  ["_OHKOText"] = "KO in un colpo!",
  ["_OKExclamationText"] = "OK!",
  ["_OakLabEmailText"] = "C'é un messaggio\ndi posta qui!\12...\12Chiamata a tutti\ngli allenatori di POKéMON!\12I migliori della\nLEGA POKéMON\11sono pronti a\11sfidare chiunque!\12Porta i tuoi\nmigliori POKéMON e\11scopri il tuo\11livello!\12SEDE LEGA POKéMON\nALTOPIANO INDACO\12PS: PROF. OAK,\npassa a trovarci!\11...",
  ["_OakSpeechText1"] = "Salve!\nBenvenuto nel\11mondo dei POKéMON!\12Mi chiamo OAK!\nPer tutti sono il\11PROF. POKéMON!",
  ["_OakSpeechText2A"] = "Questo mondo é\ninabitato da\11creature dette\11POKéMON!",
  ["_OakSpeechText2B"] = "\12Per alcuni i\nPOKéMON sono\11animali domestici.\12Altri li usano\nper lottare.\12Io...\nStudio i POKéMON\11come professione.",
  ["_OakSpeechText3"] = "{PLAYER}!\nLa tua leggenda\11sta per iniziare!\12Un mondo di sogni\ne avventure ti\11attende con i\11POKéMON! Andiamo!",
  ["_OaksAideComeBackText"] = "Oh, capisco.\12Quando avrai\n{NUM:hOaksAideRequirement, 1, 3} specie,\ntorna a prendere\11{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideGotItemText"] = "{PLAYER} ottiene\n{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "Ottimo! Hai\ncatturato\11{NUM:hOaksAideNumMonsOwned, 1, 3} specie\11di POKéMON!\11Complimenti!\12Ecco a te!",
  ["_OaksAideHiText"] = "Ciao! Ti ricordi di\nme? Sono l'AIUTO\11del PROF. OAK!\12Se hai catturato\n{NUM:hOaksAideRequirement, 1, 3} specie\11di POKéMON,\11dovrei darti\11{RAM:wOaksAideRewardItemName}!\12Allora, {PLAYER}!\nHai catturato\11almeno\11{NUM:hOaksAideRequirement, 1, 3} specie?",
  ["_OaksAideNoRoomText"] = "Oh! Vedo che non\nhai alcuno spazio\11per\11{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Vediamo...\nOh no! Hai\11catturato solo\11{NUM:hOaksAideNumMonsOwned, 1, 3} specie!\12Te ne servono\n{NUM:hOaksAideRequirement, 1, 3} per\11avere\11{RAM:wOaksAideRewardItemName}.",
  ["_OaksLabGirlText"] = "Il PROF. OAK é\nla massima autorita'\11sui POKéMON!\12Molto allenatori\nlo stimano molto!",
  ["_OaksLabGivePokeballsExplanationText"] = "\12Quando appare un\nPOKéMON selvatico,\11é tutto valido.\12Lancia una POKé\nBALL e prova a\ncatturarlo!\12Non funziona\nsempre, pero'.\12Un POKéMON in\nsalute puo' fuggire.\11Ci vuole fortuna!",
  ["_OaksLabLastMonText"] = "Questo é l'ultimo\nPOKéMON di OAK!",
  ["_OaksLabMonEnergeticText"] = "Questo POKéMON\né davvero pieno\ndi energia!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "OAK: Vieni a\ntrovarmi a volte.\12Voglio sapere come\nprocede il tuo\11POKéDEX.",
  ["_OaksLabOak1DeliverParcelText"] = "OAK: Oh, {PLAYER}!\nCome sta il mio\11vecchio POKéMON?\12Be', sembra proprio\nche ti piaccia.\12Devi avere un\ntaleento come\11allenatore!\12Cosa? Hai\nqualcosa per me?\12{PLAYER} consegna\nil PACCO di OAK.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "OAK: Che bello\nvederti! Come va\11il POKéDEX?\11Fammi dare\11un'occhiata!",
  ["_OaksLabOak1ParcelThanksText"] = "\12Ah! é la POKé\nBALL personalizzata\11che ho ordinato!\11Grazie!",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "I POKéMON di tutto\nil mondo ti\11attendono, {PLAYER}!",
  ["_OaksLabOak1RaiseYourYoungPokemonText"] = "OAK: {PLAYER},\ncresci il tuo\11giovane POKéMON\11facendolo lottare!",
  ["_OaksLabOak1ReceivedPokeballsText"] = "OAK: Non puoi\navere dati dettagliati\11vedendoli e basta.\12Devi catturarli!\nUsa questi per\11i POKéMON selvatici.\12{PLAYER} riceve 5\nPOKé BALL!",
  ["_OaksLabOak1WhichPokemonDoYouWantText"] = "OAK: Dunque,\n{PLAYER}, quale\11POKéMON vuoi?",
  ["_OaksLabOak1YourPokemonCanFightText"] = "OAK: Se appare un\nPOKéMON selvatico,\11il tuo puo'\11lottare contro di\11esso!",
  ["_OaksLabOak2Text"] = "?",
  ["_OaksLabOakBePatientText"] = "OAK: Pazienza!\nAnche {RIVAL} ne\11avra' uno!",
  ["_OaksLabOakChooseMonText"] = "OAK: {RIVAL}?\nLasciami pensare...\12Ah, é vero,\nti avevo detto di\11venire! Aspetta!\12Ecco, {PLAYER}!\nCi sono 3 POKéMON!\12Haha!\12Sono dentro le\nPOKé BALL.\12Ero un serio\nallenatore da\11giovane!\12Alla mia eta'\nme ne restano 3,\11ma uno é tuo!\12Scegli!",
  ["_OaksLabOakDontGoAwayYetText"] = "OAK: Ehi! Non\nte ne andare ancora!",
  ["_OaksLabOakGotPokedexText"] = "OAK: {PLAYER} e\n{RIVAL}! Prendete\11questi!\12{PLAYER} riceve il\nPOKéDEX da OAK!",
  ["_OaksLabOakIHaveARequestText"] = "OAK: Ah, giusto!\nHo una richiesta\11per voi due.",
  ["_OaksLabOakMyInventionPokedexText"] = "Sulla scrivania\nc'é la mia invenzione,\11il POKéDEX!\12Registra in automatico\ni dati dei POKéMON\11visti o catturati!\12é un'enciclopedia\nhi-tech!",
  ["_OaksLabOakThatWasMyDreamText"] = "Creare una guida\ncompleta di tutti\11i POKéMON...\12Questo era il sogno\nmio!\nMa sono troppo\11vecchio!\12Voglio che voi\ndue realizziate\11il mio sogno!\12Forza, muovetevi!\nQuesta é una grande\11impresa!",
  ["_OaksLabPokedexText"] = "é un'enciclopedia,\nma le pagine\11sono bianche!",
  ["_OaksLabReceivedMonText"] = "{PLAYER} riceve\nun {RAM:wNameBuffer}!",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: Si'! Non\nsono fantastico?",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: Nonno!\nSono stufo di\11aspettare!",
  ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL}: Heh, non\nho bisogno di fare\11l'avido come te!\12Scegli pure,\n{PLAYER}!",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: Ehi\n{PLAYER}! Il nonno\11non c'é!",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}: Nonno!",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "COSA?\nIncredibile!\11Ho scelto il\11POKéMON sbagliato!",
  ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}: Prendero'\nquesto, allora!",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: Aspetta\n{PLAYER}!\11Vediamo i nostri\11POKéMON!\12Forza, ti sfido!",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}: D'accordo\nnonno! Faccio io!\12{PLAYER}, odio\ndirlo, ma non mi\11servi!\12Lo so! Prestero'\nuna MAPPA CITTA'\11da mia sorella!\12Le diro' di non\ndartela, {PLAYER}!\12Ahahah!",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Il mio\nPOKéMON sembra\11molto piu' forte.",
  ["_OaksLabRivalReceivedMonText"] = "{RIVAL} riceve\nun {RAM:wNameBuffer}!",
  ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}: Ok!\nFaro' lottare il\11mio POKéMON per\11rinforzarlo!\12{PLAYER}! Nonno!\nA presto!",
  ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}: Ehi!\nNonno! E io?",
  ["_OaksLabRivalWhatDidYouCallMeForText"] = "{RIVAL}: Perché\nmi hai chiamato?",
  ["_OaksLabScientistText"] = "Studio i POKéMON\ncome aiuto del\nPROF. OAK.",
  ["_OaksLabThoseArePokeBallsText"] = "Quelle sono POKé\nBALL. Contengono\11POKéMON!",
  ["_OaksLabYouWantBulbasaurText"] = "Dunque! Vuoi il\nPOKéMON pianta,\11BULBASAUR?",
  ["_OaksLabYouWantCharmanderText"] = "Dunque! Vuoi il\nPOKéMON fuoco,\11CHARMANDER?",
  ["_OaksLabYouWantSquirtleText"] = "Dunque! Vuoi il\nPOKéMON acqua,\11SQUIRTLE?",
  ["_OddishDexEntry"] = "Di giorno tiene il\nviso sepolto nel\nterreno. Di notte\12vaga per seminare\ni suoi semi.",
  ["_OhFineThenText"] = "Oh, va bene.",
  ["_OlderFileWillBeErasedText"] = "Il vecchio file\nsara' cancellato per\11salvare. OK?",
  ["_OmanyteDexEntry"] = "Sebbene estinto da\ntempo, in rari\ncasi puo' essere\12rigenerato dai\nfossili con la\ngenetica.",
  ["_OmastarDexEntry"] = "Un POKéMON\npreistorico\nestinto perché la\12pesante conchiglia\ngli impediva di\ncatturare prede.",
  ["_OnceReleasedText"] = "Una volta liberato,\n{RAM:wStringBuffer}\né perso per sempre. OK?",
  ["_OneMoreGoSlotMachineText"] = "Un altro\ngiro?",
  ["_OneTwoAndText"] = "1, 2 e...",
  ["_OnixDexEntry"] = "Crescendo, le\nparti in pietra\ndel corpo si\12induriscono\ndiventando simili\na un diamante\12nero.",
  ["_OopsYouDontHaveEnoughRoomText"] = "Ops! Non hai\nabbastanza spazio.",
  ["_OutOfCoinsSlotMachineText"] = "Acciderboli!\nMonete esaurite!",
  ["_OutOfSafariBallsText"] = "PA: Din-don!\12Le SAFARI BALL\nsono finite!",
  ["_PPIncreasedText"] = "I PP di\n{RAM:wStringBuffer} aumentano.",
  ["_PPMaxedOutText"] = "I PP di\n{RAM:wStringBuffer} sono al massimo.",
  ["_PPRestoredText"] = "I PP sono stati\nripristinati.",
  ["_PalletTownFisherText"] = "La tecnologia é\nincredibile!\12Ora puoi archiviare\ne richiamare oggetti\11e POKéMON come\11dati via PC!",
  ["_PalletTownGirlText"] = "Allevo anch'io\ni POKéMON!\12Quando saranno\nforti, potranno\11proteggermi!",
  ["_PalletTownOakHeyWaitDontGoOutText"] = "OAK: Ehi! Aspetta!\nNon uscire!",
  ["_PalletTownOakItsUnsafeText"] = "OAK: é pericoloso!\nI POKéMON selvatici\11vivono nell'erba!\12Ti serve un tuo\nPOKéMON per\11proteggerti.\11Lo so!\12Vieni con me!",
  ["_PalletTownOaksLabSignText"] = "LABORATORIO DI\nRICERCA POKéMON DI OAK",
  ["_PalletTownPlayersHouseSignText"] = "Casa di {PLAYER}",
  ["_PalletTownRivalsHouseSignText"] = "Casa di {RIVAL}",
  ["_PalletTownSignText"] = "BIANCAVILLA\nLe sfumature di un\11nuovo viaggio!",
  ["_ParalyzedMayNotAttackText"] = "{TARGET}\né paralizzato! Puo'\11non attaccare!",
  ["_ParasDexEntry"] = "Scava per\nsucchiare le\nradici. I funghi\12sulla schiena\ncrescono traendo\nnutrimento\12dall'ospite.",
  ["_ParasectDexEntry"] = "Una coppia di\nparassiti dove il\nfungo ha preso il\12sopravvento\nsull'ospite.\nPreferisce luoghi\12umidi.",
  ["_ParlyzHealText"] = "La paralisi di\n{RAM:wNameBuffer} svanisce!",
  ["_PartyMenuBattleText"] = "Quale POKéMON\nmandare in campo?",
  ["_PartyMenuItemUseText"] = "Usare lo strumento\nsu quale POKéMON?",
  ["_PartyMenuNormalText"] = "Scegli un POKéMON.",
  ["_PartyMenuSwapMonText"] = "Spostare il POKéMON\ndove?",
  ["_PartyMenuUseTMText"] = "Usare la MT su\nquale POKéMON?",
  ["_PersianDexEntry"] = "Sebbene il pelo\nhia molti\nammiratori, é\12difficile da\nallevare per la\nsua indole\12capricciosa.",
  ["_PewterCityCooltrainerFText"] = "Si dice che i\nCLEFAIRY arrivino\11dalla luna!\12Sono apparsi dopo\nche la PIETRALUNARE\11é caduta sul monte.",
  ["_PewterCityCooltrainerMText"] = "Non ci sono molti\nallenatori seri\11qui!\12Sono come PIGLIAMOSCHE,\11ma BROCK di PLUMOPOLI\11é davvero in gamba!",
  ["_PewterCityGymSignText"] = "PLUMOPOLI\nPALESTRA POKéMON\11CAPOPALESTRA: BROCK\12Il roccioso\nallenatore POKéMON!",
  ["_PewterCityMuseumSignText"] = "MUSEO DELLA\nSCIENZA DI PLUMOPOLI",
  ["_PewterCityPokecenterGuyText"] = "Yawn!\12Quando JIGGLYPUFF\ncanta, i POKéMON\11si addormentano...\12...Anche io...\nFiiu...",
  ["_PewterCityPoliceNoticeSignText"] = "AVVISO!\12Dei ladri rubano\nfossili POKéMON al\11MONTE LUNA! Chiamate\11la polizia per info!",
  ["_PewterCitySignText"] = "PLUMOPOLI\nLa citta' dal\11grigio roccioso",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "Hai visitato il\nMUSEO?",
  ["_PewterCitySuperNerd1ItsRightHereText"] = "é proprio qui!\nSi paga per entrare,\11ma ne vale la pena!\11Ci vediamo!",
  ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "Non erano fantastici\ni fossili del\11MONTE LUNA?",
  ["_PewterCitySuperNerd1YouHaveToGoText"] = "Davvero?\nDevi assolutamente\11andarci!",
  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "Psssst!\nSai cosa sto\nfacendo?",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "Spruzzo REPELLENTE\nper tenere i POKéMON\11lontani dal giardino!",
  ["_PewterCitySuperNerd2ThatsRightText"] = "Esatto!\né un duro lavoro!",
  ["_PewterCityTrainerTipsText"] = "CONSIGLI\12Ogni POKéMON che\nprende parte alla\11lotta guadagna ESP!",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "Se hai stoffa,\nva' a sfidare BROCK!",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "Sei un allenatore,\nvero? BROCK cerca\11nuovi sfidanti!\11Seguimi!",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "\12Questa é una\nMEDAGLIA ufficiale\11della LEGA POKéMON!\12I POKéMON di chi\nla possiede sono\11piu' forti!\12Ora puoi usare\nFLASH in ogni\11momento!",
  ["_PewterGymBrockPostBattleAdviceText"] = "Ci sono allenatori\ndi ogni tipo nel\11mondo!\12Sembri molto\ndotato come\11allenatore POKéMON!\12Vai alla PALESTRA\ndi CELESTOPOLI a\11testare le abilita'!",
  ["_PewterGymBrockPreBattleText"] = "Io sono BROCK!\nSono il CAPOPALESTRA\11di PLUMOPOLI!\12Credo in una difesa\ndi roccia e nella\11determinazione!\12Percio' i miei\nPOKéMON sono tutti\11di tipo roccia!\12Vuoi ancora\nsfidarmi?\11Bene! Mostrami\11il tuo meglio!",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "Ti ho sottovalutato.\12Come prova della\nvittoria, ecco la\11MEDAGLIA SASSO!\12{PLAYER} riceve la\nMEDAGLIA SASSO!",
  ["_PewterGymBrockWaitTakeThisText"] = "Aspetta! Prendi\nquesto con te!",
  ["_PewterGymCooltrainerMAfterBattleText"] = "Sei forte, ma non\nquanto BROCK!",
  ["_PewterGymCooltrainerMBattleText"] = "Fermati li',\nragazzino!\12Sei ancora a anni\nluce da BROCK!",
  ["_MisReadPlaceholder"] = "",
  ["_PewterGymCooltrainerMEndBattleText"] = "Maledizione!\nAnni luce mi\nseparano da BROCK!",
  ["_PewterGymGuideAdviceText"] = "Il 1° POKéMON\nin campo é in cima\11alla LISTA POKéMON!\12Cambiando l'ordine\ndei POKéMON, le\11lotte saranno\11piu' facili!",
  ["_PewterGymGuideBeginAdviceText"] = "Bene! Diamo\ninizio allo spettacolo!",
  ["_PewterGymGuideFreeServiceText"] = "é un servizio\ngratuito! Diamo\11inizio alle danze!",
  ["_PewterGymGuidePostBattleText"] = "Proprio come\npensavo! Hai stoffa\11da campione!",
  ["_PewterGymGuidePreAdviceText"] = "Ehila'! Si vede\nche hai la stoffa\11del campione!\12Non sono un\nallenatore, ma so\11come vincere!\12Ti portero' in alto!",
  ["_PewterGymReceivedTM34Text"] = "{PLAYER} riceve\nMT34!",
  ["_PewterGymTM34NoRoomText"] = "Non hai spazio\nper questo!",
  ["_PewterMartSuperNerdText"] = "Cose buone possono\ncapitare se allevi\11con diligenza i\11POKéMON, anche\11quelli deboli!",
  ["_PewterMartYoungsterText"] = "Un vecchio losco\nmi ha fatto comprare\11uno strano POKéMON\11pesce!\12é debolissimo e\né costato ¥500!",
  ["_PewterNidoranHouseLittleBoyText"] = "NIDORAN cuccia!",
  ["_PewterNidoranHouseMiddleAgedManText"] = "Il nostro POKéMON\nviene da uno\11scambio, é duro.\12Un forestiero é\nun POKéMON preso\11tramite scambio.\12Cresce in fretta,\nma puo' ignorare\11un allenatore\11inesperto in lotta!\12Se solo avessimo\nmedaglie...",
  ["_PewterNidoranHouseNidoranText"] = "NIDORAN: Bowbow!",
  ["_PewterPokecenterGentlemanText"] = "Cosa!?\12Il TEAM ROCKET é\nal MONTE LUNA? Eh?\11Sono al telefono!\12Sparisci!",
  ["_PewterPokecenterJigglypuffText"] = "JIGGLYPUFF: Puu\npupuu!",
  ["_PewterSpeechHouseGamblerText"] = "I POKéMON imparano\nnuove tecniche\11crescendo!\12Ma alcune mosse\nvanno insegnate\11dall'allenatore!",
  ["_PewterSpeechHouseYoungsterText"] = "I POKéMON sono\npiu' facili da\11catturare se feriti\11o addormentati!\12Ma non é una\ncertezza assoluta!",
  ["_PickUpPayDayMoneyText"] = "{PLAYER} raccoglie\n¥{NUM:wTotalPayDayMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}!",
  ["_PidgeotDexEntry"] = "A caccia, sfiora\nl'acqua ad alta\nvelocita' per\12ghermire prede\ndistratte come\nMAGIKARP.",
  ["_PidgeottoDexEntry"] = "Molto protettivo\nverso la sua ampia\narea, questo\12POKéMON becca\nferocemente ogni\nintruso.",
  ["_PidgeyDexEntry"] = "Comune nei boschi\ne foreste. Muove\nle ali a livello\12del suolo per\nsollevare sabbia\naccecante.",
  ["_PikachuDexEntry"] = "Quando diversi\nPOKéMON si\nraccolgono, la\12loro elettricita'\npuo' causare forti\ntempeste di\12fulmini.",
  ["_PinsirDexEntry"] = "Se non riesce a\nschiacciare la\nvittima tra le\12chele, la agita e\nla scaglia\nlontano.",
  ["_PlaySlotMachineText"] = "Una slot machine!\nVuoi giocare?",
  ["_PlayedFluteHadEffectText"] = "{PLAYER} suona il\nFLAUTO POKéMON.",
  ["_PlayedFluteNoEffectText"] = "Suonato il FLAUTO\nPOKéMON.\12Che motivetto\norecchiabile!",
  ["_PlayerBlackedOutText"] = "{PLAYER} non ha\npiu' POKéMON validi!\12{PLAYER} é\nk.o.!",
  ["_PlayerBlackedOutText2"] = "{PLAYER} non ha\npiu' POKéMON validi!\12{PLAYER} é\nk.o.!",
  ["_PlayerMon1Text"] = "{RAM:wBattleMonNick}!",
  ["_PlayerMon2Text"] = "{RAM:wBattleMonNick} ",
  ["_PlayerMonFaintedText"] = "{RAM:wBattleMonNick}\né esausto!",
