  ["_PokemartAnythingElseText"] = "Posso fare\nqualcos'altro?",
  ["_PokemartBoughtItemText"] = "Eccolo a te!\nGrazie!",
  ["_PokemartBuyingGreetingText"] = "Prenditi tutto\nil tempo che vuoi.",
  ["_PokemartGreetingText"] = "Salve!\nPosso aiutarti?",
  ["_PokemartItemBagEmptyText"] = "Non hai nulla\nda vendere.",
  ["_PokemartItemBagFullText"] = "Non puoi portare\naltri strumenti.",
  ["_PokemartNotEnoughMoneyText"] = "Non hai abbastanza\nsoldi.",
  ["_PokemartTellBuyPriceText"] = "{RAM:wStringBuffer}?\nFaranno\11¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}. Va bene?",
  ["_PokemartTellSellPriceText"] = "Posso darti\n¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN} per questo.",
  ["_PokemartThankYouText"] = "Grazie!",
  ["_PokemartUnsellableItemText"] = "Non posso dare\nun prezzo a questo.",
