  ["_PokemonCenterFarewellText"] = "Speriamo di\nrivederti presto!",
  ["_PokemonCenterWelcomeText"] = "Benvenuti al nostro\nCENTRO POKéMON!\12Ristabiliamo la piena\nforma dei tuoi\11POKéMON!",
  ["_PokemonFaintedText"] = "{RAM:wNameBuffer}\né esausto!",
