  ["_PokemonFanClubChairFinalText"] = "Salve, {PLAYER}!\12Sei tornato per\nparlare dei miei\11POKéMON?\12No? Che peccato!",
  ["_PokemonFanClubChairmanIntroText"] = "Sono il presidente\ndel Fan Club!\12Ho raccolto oltre\n100 POKéMON!\12Sono molto esigente\nin fatto di POKéMON!\12Quindi...\12Sei venuto a\nsentire la mia\11storia?",
  ["_PokemonFanClubChairmanStoryText"] = "Bene!\nAscoltate allora!\12Il mio RAPIDASH...\12é... carino...\nadorabile...\11intelligente...\12splendido...\11gentile...\12lo adoro!\12Abbracciarlo... quando\nriposa... caldo\11e coccoloso...\11spettacolare...\11...Ops! Guarda\11l'ora! Ti ho\11trattenuto troppo!\12Grazie dell'ascolto!\nPrendi questo!",
  ["_PokemonFanClubExplainBikeVoucherText"] = "\12Scambialo per\nuna BICICLETTA!\12Non temere, il mio\nFEAROW mi porta\11ovunque volando!\12Quindi non mi\nserve la BICI!\12Spero ti piaccia\nandare in bici!",
  ["_PokemonFanClubNoStoryText"] = "Oh. Torna quando\nvorrai ascoltare\11la mia storia!",
  ["_PokemonFanClubPikachuFanBetterText"] = "Uffa! Il mio\nPIKACHU é il doppio\11piu' carino!",
  ["_PokemonFanClubPikachuFanNormalText"] = "Non ammiri la\ncoda del mio\11PIKACHU?",
  ["_PokemonFanClubPikachuText"] = "PIKACHU: Chu!\nPikachu!",
  ["_PokemonFanClubReceivedBikeVoucherText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_PokemonFanClubReceptionistText"] = "Il nostro presidente\nparla sempre di\11POKéMON.",
  ["_PokemonFanClubSeelFanBetterText"] = "Oh cielo!\nIl mio SEEL é\11molto piu' attraente!",
  ["_PokemonFanClubSeelFanNormalText"] = "Adoro il mio\nSEEL!\12Emette un suono\nquando lo stringo!",
  ["_PokemonFanClubSeelText"] = "SEEL: Kyuoo!",
  ["_PokemonFanClubSign1Text"] = "Ascoltiamo tutti\ncon educazione gli\11altri allenatori!",
  ["_PokemonFanClubSign2Text"] = "Se qualcuno si\nvanta, vantati\11pure tu!",
  ["_PokemonFightingFitText"] = "Grazie!\nI tuoi POKéMON\11sono in forma!",
  ["_PokemonMansion1FScientistAfterBattleText"] = "Una chiave? Non\nso di cosa tu\11stia parlando.",
  ["_PokemonMansion1FScientistBattleText"] = "Chi sei? Non\ndovrebbe esserci\11nessuno qui.",
  ["_PokemonMansion1FScientistEndBattleText"] = "Ahi!",
  ["_PokemonMansion1FSwitchNotPressedText"] = "Non ancora!",
  ["_PokemonMansion1FSwitchPressedText"] = "Chi non lo farebbe?",
  ["_PokemonMansion1FSwitchText"] = "Un interruttore\nsegreto!\12Vuoi premerlo?",
  ["_PokemonMansion2FDiary1Text"] = "Diario: 5 luglio\nGuyana, Sud America\12Nuovo POKéMON\nscoperto nel\11profondo della giungla.",
  ["_PokemonMansion2FDiary2Text"] = "Diario: 10 luglio\nAbbiamo battezzato\nil nuovo POKéMON,\nMEW.",
  ["_PokemonMansion2FSuperNerdAfterBattleText"] = "Gli interruttori\naprono e chiudono\11porte alternate!",
  ["_PokemonMansion2FSuperNerdBattleText"] = "Non riesco a uscire!\nQuesto vecchio posto\11é un rompicapo!",
  ["_PokemonMansion2FSuperNerdEndBattleText"] = "Oh no!\nIl mio sacco di\11oggetti!",
  ["_PokemonMansion2FSwitchNotPressedText"] = "Non ancora!",
  ["_PokemonMansion2FSwitchPressedText"] = "Chi non lo farebbe?",
  ["_PokemonMansion2FSwitchText"] = "Un interruttore\nsegreto!\12Vuoi premerlo?",
  ["_PokemonMansion3FDiaryText"] = "Diario: 6 feb.\nMEW ha partorito.\12Abbiamo chiamato\nil piccolo MEWTWO.",
  ["_PokemonMansion3FScientistAfterBattleText"] = "Sei bloccato?\nProva a saltare\11giu' da li'!",
  ["_PokemonMansion3FScientistBattleText"] = "Il mio mentore\nvisse qui un tempo.",
  ["_PokemonMansion3FScientistEndBattleText"] = "Uf!\nTravolgente!",
  ["_PokemonMansion3FSuperNerdAfterBattleText"] = "Chissa' dove é\nandato il mio socio.",
  ["_PokemonMansion3FSuperNerdBattleText"] = "Questo posto é\ncosi' grande!",
  ["_PokemonMansion3FSuperNerdEndBattleText"] = "Ahi!",
  ["_PokemonMansionB1FBurglarAfterBattleText"] = "Puoi trovare roba\nin giro.",
  ["_PokemonMansionB1FBurglarBattleText"] = "Oh no. Dove\nmi trovo ora?",
  ["_PokemonMansionB1FBurglarEndBattleText"] = "Awooh!",
  ["_PokemonMansionB1FDiaryText"] = "Diario: 1 set.\nMEWTWO é troppo\11potente.\12Non siamo riusciti\na frenare la sua\11indole feroce...",
  ["_PokemonMansionB1FScientistAfterBattleText"] = "Mi piace qui!\nFavorisce i\11miei studi!",
  ["_PokemonMansionB1FScientistBattleText"] = "Questo posto é\nideale per un lab.",
  ["_PokemonMansionB1FScientistEndBattleText"] = "A che\nserviva questo?",
  ["_PokemonSellingGreetingText"] = "Cosa vorresti\nvendere?",
  ["_PokemonStuffText"] = "Wow! Un mucchio\ndi roba POKéMON!",
  ["_PokemonTower1FBaldingGuyText"] = "Sono venuto a\npregare per il\11mio CLEFAIRY.\12Sniff! Non riesco\na smettere di\11piangere...",
  ["_PokemonTower1FChannelerText"] = "Sono un MEDIUM!\nCi sono spiriti\11che fanno marachelle!",
  ["_PokemonTower1FGirlText"] = "Il mio GROWLITHE...\nPerché sei morto?",
  ["_PokemonTower1FMiddleAgedWomanText"] = "Sei venuto a\nportare rispetto?\11Sii benedetto!",
  ["_PokemonTower1FReceptionistText"] = "La TORRE POKéMON\nfu eretta in\11memoria dei POKéMON\11deceduti.",
  ["_PokemonTower2FChannelerText"] = "Neanche noi\nidentifichiamo i\11FANTASMI!\12Uno SPETTROSCOPE\nli smaschererebbe.",
  ["_PokemonTower2FRivalDefeatedText"] = "Cosa?\nSei una carogna!\12Ci sono andato\npesante anch'io!",
  ["_PokemonTower2FRivalHowsYourDexText"] = "Come va il\nPOKéDEX, amico?\11Ho appena catturato\11un CUBONE!\12Non trovo ancora\nil MAROWAK adulto!\11Dubbia ce ne siano!\12Be', devo andare!\11Ho molto da fare!\12A presto, amico!",
  ["_PokemonTower2FRivalVictoryText"] = "{RIVAL}: Beh,\nquanti POKéMON\11fifoni hai!\12Rinforzali un\npo' di piu'!",
  ["_PokemonTower2FRivalWhatBringsYouHereText"] = "{RIVAL}: Ehi\n{PLAYER}! Cosa\11ci fai qui?\11I tuoi POKéMON\11non sembrano morti!\12Posso almeno\nfarli svenire!\11Forza, amico!",
  ["_PokemonTower3FChanneler1AfterBattleText"] = "I FANTASMI si\nriconoscono con lo\11SPETTROSCOPE.",
  ["_PokemonTower3FChanneler1BattleText"] = "Urrg... Awaa...\nHuhu... graa..",
  ["_PokemonTower3FChanneler1EndBattleText"] = "Hwa!\nSono salva!",
  ["_PokemonTower3FChanneler2AfterBattleText"] = "Scusa! Ero\nposseduta!",
  ["_PokemonTower3FChanneler2BattleText"] = "Kekeke...\nKwaaah!",
  ["_PokemonTower3FChanneler2EndBattleText"] = "Mhm?\nChe sto facendo?",
  ["_PokemonTower3FChanneler3AfterBattleText"] = "Anche i miei amici\nerano posseduti!",
  ["_PokemonTower3FChanneler3BattleText"] = "Vattene!\nSpirito malvagio!",
  ["_PokemonTower3FChanneler3EndBattleText"] = "Uf!\nLo spirito é via!",
  ["_PokemonTower4FChanneler1AfterBattleText"] = "Devo aver\nsognato...",
  ["_PokemonTower4FChanneler1BattleText"] = "FANTASMA! No!\nKwaaah!",
  ["_PokemonTower4FChanneler1EndBattleText"] = "Dov'é\nil FANTASMA?",
  ["_PokemonTower4FChanneler2AfterBattleText"] = "Non scopriamo\nl'identita' dei\11FANTASMI.",
  ["_PokemonTower4FChanneler2BattleText"] = "Maledetto con\nme! Kwaaah!",
  ["_PokemonTower4FChanneler2EndBattleText"] = "Cosa!",
  ["_PokemonTower4FChanneler3AfterBattleText"] = "Che le anime dei\nPOKéMON riposino\11in pace...",
  ["_PokemonTower4FChanneler3BattleText"] = "Huhuhu...\nNon battermi!",
  ["_PokemonTower4FChanneler3EndBattleText"] = "Eh?\nChi? Cosa?",
  ["_PokemonTower5FChanneler1Text"] = "Vieni, bimbo!\nHo sigillato lo\11spazio con magia!\12Puoi riposare qui!",
  ["_PokemonTower5FChanneler2AfterBattleText"] = "Ero sotto\npossessione!",
  ["_PokemonTower5FChanneler2BattleText"] = "Dammi...\nla tua...\nanima...",
  ["_PokemonTower5FChanneler2EndBattleText"] = "Gasp!",
  ["_PokemonTower5FChanneler3AfterBattleText"] = "Ero posseduta!",
  ["_PokemonTower5FChanneler3BattleText"] = "Tu...\nunisciti...\na noi...",
  ["_PokemonTower5FChanneler3EndBattleText"] = "Che\nincubo!",
  ["_PokemonTower5FChanneler4AfterBattleText"] = "Ho ripreso i\nsensi!",
  ["_PokemonTower5FChanneler4BattleText"] = "Zombi!",
  ["_PokemonTower5FChanneler4EndBattleText"] = "Ah?",
  ["_PokemonTower5FChanneler5AfterBattleText"] = "Caddi nel male\nnonostante l'addestramento!",
  ["_PokemonTower5FChanneler5BattleText"] = "Urgah...\nUrff....",
  ["_PokemonTower5FChanneler5EndBattleText"] = "Whoo!",
  ["_PokemonTower5FPurifiedZoneText"] = "Entrato in zona\nprotetta e pura!\12I POKéMON di\n{PLAYER} sono curati!",
  ["_PokemonTower6FBeGoneText"] = "Viatene...\nIntrusi...",
  ["_PokemonTower6FChanneler1AfterBattleText"] = "Mi sento anemica\ne debole...",
  ["_PokemonTower6FChanneler1BattleText"] = "Dammi...\nil tuo...\nsangue...",
  ["_PokemonTower6FChanneler1EndBattleText"] = "Gemito!",
  ["_PokemonTower6FChanneler2AfterBattleText"] = "I capelli non\nsono caduti! Era\11uno spirito malvagio!",
  ["_PokemonTower6FChanneler2BattleText"] = "Urff... Kwaah!",
  ["_PokemonTower6FChanneler2EndBattleText"] = "Qualcosa\né caduto!",
  ["_PokemonTower6FChanneler3AfterBattleText"] = "Che succede\nqui?",
  ["_PokemonTower6FChanneler3BattleText"] = "Ke..ke...ke...\nke..ke...ke!!",
  ["_PokemonTower6FChanneler3EndBattleText"] = "Keee!",
  ["_PokemonTower6FGhostWasCubonesMotherText"] = "Il FANTASMA era\nl'anima irrequieta\11della madre!",
  ["_PokemonTower6FSoulWasCalmedText"] = "L'anima della\nmadre é calmata.\12é partita per\nl'aldila'!",
  ["_PokemonTower7FMrFujiRescueText"] = "MR. FUJI: Eh?\nSei venuto a\11salvarmi?\12Grazie. Ma sono\nvenuto di mia\11spontanea volonta'.\12Per calmare l'anima\ndella madre di\11CUBONE.\12Penso che lo\nspirito sia andato\11nell'aldila'.\12Ti ringrazio per\nil pensiero!\12Seguimi a casa,\nalla CASA POKéMON\11ai piedi della torre.",
  ["_PokemonTower7FRocket1AfterBattleText"] = "Non lo\ndimentichero'!",
  ["_PokemonTower7FRocket1BattleText"] = "Che vuoi?\nPerché sei qui?",
  ["_PokemonTower7FRocket1EndBattleText"] = "Mi arrendo!",
  ["_PokemonTower7FRocket2AfterBattleText"] = "I POKéMON servono\nsolo a fare soldi!\12Non impicciarti!",
  ["_PokemonTower7FRocket2BattleText"] = "Questo vecchietto\nsi é lamentato\11per i POKéMON\11inutili!\12Discutiamo da\nadulti noi!",
  ["_PokemonTower7FRocket2EndBattleText"] = "Ti prego!\nBasta!",
  ["_PokemonTower7FRocket3AfterBattleText"] = "Non la passerai\nliscia!",
  ["_PokemonTower7FRocket3BattleText"] = "Non salverai\nnessuno, moccioso!",
  ["_PokemonTower7FRocket3EndBattleText"] = "Non sfidare\ni ROCKET!",
  ["_PoliwagDexEntry"] = "Le zampe cresciute\nle impediscono di\ncorrere.\12Preferisce nuotare\nche provare a\nstare in piedi.",
  ["_PoliwhirlDexEntry"] = "Capace di vivere\nin acqua e fuori.\nFuori suda per\12mantenere il corpo\nviscido.",
  ["_PoliwrathDexEntry"] = "Ottimo nuotatore a\nstile libero e a\nrana. Supera\12facilmente i\nmigliori nuotatori\numani.",
  ["_PonytaDexEntry"] = "I suoi zoccoli\nsono 10 volte piu'\nduri di un\12diamante. Calpesta\nqualsiasi cosa\nappiattendola in\12poco tempo.",
  ["_PoofText"] = " Puff!",
  ["_PorygonDexEntry"] = "Un POKéMON fatto\ninteramente di\ncodice di\12programmazione. Si\nmuove liberamente\nnel cyberspazio.",
  ["_PotionText"] = "{RAM:wNameBuffer}\nrecupera {NUM:wHPBarHPDifference, 2, 3}!",
  ["_PowerPlantVoltorbBattleText"] = "Bzzzt!",
  ["_PowerPlantZapdosBattleText"] = "Gyaoo!",
  ["_PrimeapeDexEntry"] = "Sempre furioso e\ntenace. Non smette\ndi inseguire la\12sua preda finché\nnon l'ha\ncatturata.",
  ["_PsyduckDexEntry"] = "Mentre distrae i\nnemici con l'aria\nsvagata, questo\12subdolo POKéMON\nusa poteri\ncinetici.",
  ["_PushStartText"] = "Premi START per\naprire il MENU!",
  ["_RaichuDexEntry"] = "La lunga coda\nfunziona da messa\na terra per\12proteggerlo dalla\nsua stessa alta\ntensione.",
  ["_RaisePPWhichTechniqueText"] = "Aumentare i PP\ndi quale mossa?",
  ["_RanAwayScaredText"] = "{TARGET}\né fuggito per la\npaura!",
  ["_RanFromBattleText"] = "{USER}\nfugge dalla lotta!",
  ["_RapidashDexEntry"] = "Molto competitivo,\nquesto POKéMON\ninsegue chiunque\12si muova veloce\nnella speranza di\nfare una gara.",
  ["_RareCandyText"] = "{RAM:wNameBuffer} sale al\nlivello {NUM:wCurEnemyLevel, 1, 3}!",
  ["_RaticateDexEntry"] = "Usa i baffi per\nmantenere\nl'equilibrio.\12Sembra rallentare\nse vengono\ntagliati.",
  ["_RattataDexEntry"] = "Morde qualsiasi\ncosa attaccando.\nPiccolo e rapido,\12é comune in molti\nluoghi.",
  ["_RedBedroomSNESText"] = "{PLAYER} gioca\nal Super NES!\11...Bene!\11é ora di andare!",
  ["_RedsHouse1FMomLookingGreatText"] = "MAMMA: Oh bene!\nTu e i POKéMON\11state benissimo!\12Badate a voi!",
  ["_RedsHouse1FMomWakeUpText"] = "MAMMA: Giusto.\nTutti i ragazzi\11lasciano casa.\12Lo han detto in TV.\12Il PROF. OAK, qui\naccanto, ti cerca.",
  ["_RedsHouse1FMomYouShouldRestText"] = "MAMMA: {PLAYER}!\nDovresti riposare\11un attimo.",
  ["_RedsHouse1FTVStandByMeMovieText"] = "C'é un film in TV.\nQuattro ragazzi\11camminano sui binari.\12Meglio andare anch'io.",
  ["_RedsHouse1FTVWrongSideText"] = "Ops, lato sbagliato.",
  ["_ReflectGainedArmorText"] = "{USER}\nottiene uno scudo!",
  ["_RegainedHealthText"] = "{USER}\nrecupera salute!",
  ["_ReleaseWhichMonText"] = "Quale POKéMON\nliberare?",
  ["_RepelWoreOffText"] = "L'effetto del\nREPELLENTE svanisce.",
  ["_RequireCoinCaseText"] = "Serve un\nSALVADANAIO!",
  ["_RestorePPWhichTechniqueText"] = "Ripristinare i PP\ndi quale mossa?",
  ["_ReviveText"] = "{RAM:wNameBuffer}\né rivitalizzato!",
  ["_RhydonDexEntry"] = "Protetto da una\npelle corazzata,\npuo' vivere nella\12lava fusa a 3600\ngradi.",
  ["_RhyhornDexEntry"] = "Le sue grandi ossa\nsono 1000 volte\npiu' dure di\12quelle umane. Puo'\nsbalzare via un\ntrim.",
  ["_Rival1WinText"] = "{RIVAL}: Si'! Non\nsono fantastico?",
  ["_RivalDefeatedText"] = "NO!\nNon puo' essere!\11Hai battuto il meglio!\12Dopo tanto lavoro\nper la LEGA?\12Il mio regno é gia'\nterminato?\11Non é giusto!",
  ["_RivalVictoryText"] = "Ahahah!\nHo vinto, ho vinto!\12Sono troppo forte\nper te, {PLAYER}!\12Sei stato bravo\nad arrivare fin qui,\11io sono il genio!\12Bel tentativo, ma\nnon vali nulla!\12Ahahah!",
  ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "Ho visto un MACHOP\nin questo tunnel!",
  ["_RockTunnel1FCooltrainerF1BattleText"] = "Eek! Non fare\nscherzi nel buio!",
  ["_RockTunnel1FCooltrainerF1EndBattleText"] = "Era\ntroppo buio!",
  ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "Sembravi carino\ne innocuo!",
  ["_RockTunnel1FCooltrainerF2BattleText"] = "Sono venuto fin\nqui per i POKéMON!",
  ["_RockTunnel1FCooltrainerF2EndBattleText"] = "Non ho piu'\nPOKéMON!",
  ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "Uf! Ora sono\ntutto sudato!",
  ["_RockTunnel1FCooltrainerF3BattleText"] = "Hai dei POKéMON!\nIniziamo!",
  ["_RockTunnel1FCooltrainerF3EndBattleText"] = "Giochi\nduro!",
  ["_RockTunnel1FHiker1AfterBattleText"] = "Attento a ONIX!\nPuo' stritolarti!",
  ["_RockTunnel1FHiker1BattleText"] = "Questo tunnel é\nmolto lungo, ragazzo!",
  ["_RockTunnel1FHiker1EndBattleText"] = "Doh!\nHai vinto!",
  ["_RockTunnel1FHiker2AfterBattleText"] = "Quel POKéMON\ndormiente al PERCORSO\1112 mi ha costretto\11a una deviazione.",
  ["_RockTunnel1FHiker2BattleText"] = "Mhm. Forse mi\nsono perso...",
  ["_RockTunnel1FHiker2EndBattleText"] = "Calma!\nChe sto facendo?\11Dov'é l'uscita?",
  ["_RockTunnel1FHiker3AfterBattleText"] = "Hai abbastanza\ntalento per scalare!",
  ["_RockTunnel1FHiker3BattleText"] = "I forestieri come\nte devono mostrarmi\11rispetto!",
  ["_RockTunnel1FHiker3EndBattleText"] = "Mi arrendo!",
  ["_RockTunnel1FSignText"] = "TUNNEL ROCCIOSO\nCELESTOPOLI -\11LAVANDULA",
  ["_RockTunnel1FSuperNerdAfterBattleText"] = "Vabbé, prendero'\nun ZUBAT strada facendo!",
  ["_RockTunnel1FSuperNerdBattleText"] = "Lotta POKéMON!\nPronti, via!",
  ["_RockTunnel1FSuperNerdEndBattleText"] = "Game\nover!",
  ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "Voglio andare\na casa!",
  ["_RockTunnelB1FCooltrainerF1BattleText"] = "Gli escursionisti\nlasciano rametti\11come segnavia.",
  ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "Ohhh!\nHo fatto del mio meglio!",
  ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "Amo i piccoli\nPOKéMON, i grandi\11fanno paura!",
  ["_RockTunnelB1FCooltrainerF2BattleText"] = "Non vengo spesso,\nma lottero' con te.",
  ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "Oh!\nHo perso!",
  ["_RockTunnelB1FHiker1AfterBattleText"] = "Punto sulla forza\nperché odio\11pensare!",
  ["_RockTunnelB1FHiker1BattleText"] = "Ahahah! Puoi\nbattere la mia forza?",
  ["_RockTunnelB1FHiker1EndBattleText"] = "Ops!\nBattuto!",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "Tra i monti trovi\nspesso POKéMON\11di tipo roccia.",
  ["_RockTunnelB1FHiker2BattleText"] = "Le mie tecniche\nti faranno piangere!",
  ["_RockTunnelB1FHiker2EndBattleText"] = "Mi arrendo!\nSei un tecnico\11migliore!",
  ["_RockTunnelB1FHiker3AfterBattleText"] = "Crescero' il mio\nPOKéMON per battere\11il tuo, ragazzo!",
  ["_RockTunnelB1FHiker3BattleText"] = "Colpiscimi con\nil tuo meglio!",
  ["_RockTunnelB1FHiker3EndBattleText"] = "Colpo\npartito!",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Quando finisci il\nPOKéDEX, posso\11averlo?",
  ["_RockTunnelB1FSuperNerd1BattleText"] = "Hai un POKéDEX?\nNe voglio uno!",
  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "Accidenti!\nChe invidia!",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "Alcuni si vestono\nda POKéMON per\11divertimento.",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "Conosci i cosplayer\ndi POKéMON?",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "Be',\nquesto é tutto.",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Sono un artista,\nnon un lottatore.",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "Disegno POKéMON\nquando sono a casa.",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "Uf!\nSono esausto!",
  ["_RockTunnelPokecenterFisherText"] = "Ho venduto una\nPEPITA per ¥5000!",
  ["_RockTunnelPokecenterGentlemanText"] = "I tipi elementali\ndei POKéMON li\11rendono forti con\11alcuni e deboli\11con altri!",
  ["_RockTunnelPokecenterGuyText"] = "Ho sentito che\ni FANTASMI infestano\11LAVANDULA!",
  ["_RocketHide3AfterBattleText3"] = "Vai pure avanti!\nMa ti serve la\11CHIAVE ASCENSORE!",
  ["_RocketHideout3BattleText"] = "Ci é arrivata voce\nche stavi arrivando!",
  ["_RocketHideout3EndBattleText3"] = "Cosa?\nHo perso? No!",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "Stai criticando\nil TEAM ROCKET?",
  ["_RocketHideoutB1FRocket1BattleText"] = "Chi sei? Come\nsei arrivato qui?",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "Ahi!\nBattuto!",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "Non la passerai\nliscia, moccioso!",
  ["_RocketHideoutB1FRocket2BattleText"] = "Ti sei introdotto\nnella nostra base?",
  ["_RocketHideoutB1FRocket2EndBattleText"] = "Bruciato!",
  ["_RocketHideoutB1FRocket3AfterBattleText"] = "SPETTROSCOPE?\nNon so dove sia!",
  ["_RocketHideoutB1FRocket3BattleText"] = "Allarme intruso!",
  ["_RocketHideoutB1FRocket3EndBattleText"] = "Non ci\nriesco!",
  ["_RocketHideoutB1FRocket4AfterBattleText"] = "OK, parlero'!\nPrendi l'ascensore\11per il CAPO!",
  ["_RocketHideoutB1FRocket4BattleText"] = "Perché sei venuto\nqui?",
  ["_RocketHideoutB1FRocket4EndBattleText"] = "Questo\nnon va!",
  ["_RocketHideoutB1FRocket5AfterBattleText"] = "Oh no, quella\nlotta ha aperto la porta!",
  ["_RocketHideoutB1FRocket5BattleText"] = "Ti sei perso,\npiccolo ratto?",
  ["_RocketHideoutB1FRocket5EndBattleText"] = "Perché...?",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "La base ROCKET\nha 4 piani interrati.\11Arriverai dal CAPO?",
  ["_RocketHideoutB2FRocketBattleText"] = "Il CAPO dice che\nvedi i FANTASMI\11con lo SPETTROSCOPE!",
  ["_RocketHideoutB2FRocketEndBattleText"] = "Mi\narrendo!",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "SPETTROSCOPE?\nLa macchina rubata.\11é qui da qualche parte.",
  ["_RocketHideoutB3FRocket1BattleText"] = "Smetti di intrometterti\nnegli affari del ROCKET!",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "Oof!\nAtterrato!",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Vedo che cresci\ni POKéMON con cura.\12Un bambino come\nte non capirebbe\11cosa voglio fare.\12Mi faccio da parte\nstavolta!\12Spero ci\nriverremo...",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "Dunque! Devo dire\nche sono colpito\11che tu sia qui!",
  ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "COSA!\nNon puo' essere!",
  ["_RocketHideoutB4FRocket1AfterBattleText"] = "Ce l'hai con\nil TEAM ROCKET?",
  ["_RocketHideoutB4FRocket1BattleText"] = "Ti conosco! Hai\nrovinato i piani\11al MONTE LUNA!",
  ["_RocketHideoutB4FRocket1EndBattleText"] = "Bruciato\ndi nuovo!",
  ["_RocketHideoutB4FRocket2AfterBattleText"] = "CAPO! Scusa se\nho fallito!",
  ["_RocketHideoutB4FRocket2BattleText"] = "Come fai a non\nvedere la bellezza\11del nostro male?",
  ["_RocketHideoutB4FRocket2EndBattleText"] = "Ayaya!",
  ["_RocketHideoutB4FRocket3AfterBattleText"] = "Oh no! Ho perso\nla CHIAVE ASCENSORE!",
  ["_RocketHideoutB4FRocket3BattleText"] = "L'ascensore non\nva? Chi ha la\11CHIAVE ASCENSORE?",
  ["_RocketHideoutB4FRocket3EndBattleText"] = "No!",
  ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "Sembra che serva\nuna chiave.",







  ["_RoseText"] = " rose!",
  ["_Route10CooltrainerF1AfterBattleText"] = "Ho notato dei\nPOKéMANIAC\11che gironzolavano.",
  ["_Route10CooltrainerF1BattleText"] = "Sono stata in una\nPALESTRA POKéMON\11qualche volta.\11Ma ho sempre perso.",
  ["_Route10CooltrainerF1EndBattleText"] = "Oh!\nDi nuovo al tappeto!",
  ["_Route10CooltrainerF2AfterBattleText"] = "I POKéMON qui\nsono cosi' paffuti!\11Dovrebbe essercene\11uno rosa con un\11motivo floreale!",
  ["_Route10CooltrainerF2BattleText"] = "Mi sento un po'\nsvienevole per\11questa dura escursione.",
  ["_Route10CooltrainerF2EndBattleText"] = "Non ce\nla faccio!",
  ["_Route10Hiker1AfterBattleText"] = "E-et-ciu'!\nEt-ciu'!\11Sniff! Tirch!",
  ["_Route10Hiker1BattleText"] = "Ah-ahah-ah-ah!",
  ["_Route10Hiker1EndBattleText"] = "Ah-aha!\nNon sto ridendo!\11Ho il raffreddore!\11E-et-ciu'!",
  ["_Route10Hiker2AfterBattleText"] = "Mi sento gonfio\ndell'aria di monte!",
  ["_Route10Hiker2BattleText"] = "Ah! Quest'aria di\nmonte é deliziosa!",
  ["_Route10Hiker2EndBattleText"] = "Questo\nmi ha schiarito le idee!",
  ["_Route10PowerPlantSignText"] = "CENTRALE ELETTRICA",
  ["_Route10RockTunnelSignText"] = "DIGRAPUNTO",
  ["_Route10SuperNerd1AfterBattleText"] = "Ho altri POKéMON\nrari a casa!",
  ["_Route10SuperNerd1BattleText"] = "Wow, sei un\nPOKéMANIAC anche tu?\11Vuoi vedere la mia\11collezione?",
  ["_Route10SuperNerd1EndBattleText"] = "Uhm.\nNon sono arrabbiato!",
  ["_Route10SuperNerd2AfterBattleText"] = "Mi stai antipatico\nperché mi hai battuto!",
  ["_Route10SuperNerd2BattleText"] = "Ehi ragazzo, vuoi\nvedere i miei POKéMON?",
  ["_Route10SuperNerd2EndBattleText"] = "Oh no!\nI miei POKéMON!",
  ["_Route11DiglettsCaveSignText"] = "GROTTA DIGLETT",
  ["_Route11Gambler1AfterBattleText"] = "I POKéMON sono vita!\nE vivere significa\11azzardare!",
  ["_Route11Gambler1BattleText"] = "Vinci, perdi o pareggi!",
  ["_Route11Gambler1EndBattleText"] = "Atcha!\nNon é andata come volevo!",
  ["_Route11Gambler2AfterBattleText"] = "Non puoi essere un\ncovardo nel mondo\11dei POKéMON!",
  ["_Route11Gambler2BattleText"] = "Competizione!\nNon ne tengo mai abbastanza!",
  ["_Route11Gambler2EndBattleText"] = "Avevo\nuna possibilita'!",
  ["_Route11Gambler3AfterBattleText"] = "Colpo di fortuna!\nSolo fortuna!",
  ["_Route11Gambler3BattleText"] = "Fwahaha! Non ho\nmai perso!",
  ["_Route11Gambler3EndBattleText"] = "La mia\nprima sconfitta!",
  ["_Route11Gambler4AfterBattleText"] = "é solo fortuna.\nColpo di fortuna.",
  ["_Route11Gambler4BattleText"] = "Non avevo mai vinto\nprima...",
  ["_Route11Gambler4EndBattleText"] = "Me lo\nsapevo...",
  ["_Route11Gate1FGuardText"] = "Quando catturi\ntanti POKéMON,\11non é difficile\11trovare i nomi?\12A LAVANDULA\nc'é un esperto di\11nomignoli POKéMON.\12Ti aiutera' anche\na ribattezzarli!",
  ["_Route11Gate2FLeftBinocularsNoSnorlaxText"] = "Hai guardato nei\nbinocoli.\12C'é una vista\nstupenda!",
  ["_Route11Gate2FLeftBinocularsSnorlaxText"] = "Hai guardato nei\nbinocoli.\12Un grosso POKéMON\ndorme sulla strada!",
  ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "Ci sono oggetti a\nterra che non si\11possono vedere.\12CERCASP_ e'\nin grado di rilevarli\11nelle vicinanze.\12Non individua il\npunto esatto,\ndevi cercarli tu!",
  ["_Route11Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli.\12L'unico modo per\nandare da CERULOPOLI\11a LAVANDULA\11é passare per il\11DIGRAPUNTO.",
  ["_Route11SuperNerd1AfterBattleText"] = "Fai girare la voce:\nrisparmia energia!",
  ["_Route11SuperNerd1BattleText"] = "Attento!\nSto posando dei\11cavi!",
  ["_Route11SuperNerd1EndBattleText"] = "é stata\nun'esperienza elettrizzante!",
  ["_Route11SuperNerd2AfterBattleText"] = "Beh, é ora di\ntornare al lavoro.",
  ["_Route11SuperNerd2BattleText"] = "Attento ai fili\nscoperti!",
  ["_Route11SuperNerd2EndBattleText"] = "Urca!\nSei una scintilla!",
  ["_Route11Youngster1AfterBattleText"] = "Ce l'ho messa tutta!\nNon ho rimpianti!",
  ["_Route11Youngster1BattleText"] = "Andiamo, ma\nnon barare!",
  ["_Route11Youngster1EndBattleText"] = "Eh?\nNon é giusto!",
  ["_Route11Youngster2AfterBattleText5"] = "Che vuoi?\nLasciami in pace!",
  ["_Route11Youngster2BattleText"] = "Sono appena diventato\nun allenatore! Ma\11credo di poter vincere!",
  ["_Route11Youngster2EndBattleText"] = "I miei\nPOKéMON no!",
  ["_Route11Youngster3AfterBattleText"] = "C'é un grosso\nPOKéMON che scende\11dalle montagne.\12é forte, se riesci\na prenderlo.",
  ["_Route11Youngster3BattleText"] = "Sono il migliore\ndella mia classe!",
  ["_Route11Youngster3EndBattleText"] = "Acciderboli!\nDevo rendere i miei\11POKéMON piu' forti!",
  ["_Route11Youngster4AfterBattleText"] = "Faro' meglio a\ncercarne di piu' forti!",
  ["_Route11Youngster4BattleText"] = "I miei POKéMON\ndovrebbero essere pronti!",
  ["_Route11Youngster4EndBattleText"] = "Troppo\ngiovane per farlo!",
  ["_Route12CooltrainerMAfterBattleText"] = "Pensa che avrei\npotuto evolvere i\11miei POKéMON con\11una PIETRALUNARE!",
  ["_Route12CooltrainerMBattleText"] = "Hai trovato una\nPIETRALUNARE?",
  ["_Route12CooltrainerMEndBattleText"] = "Ahi!",
  ["_Route12Fisher1AfterBattleText"] = "Resisti! Ho la\nlenza impigliata!",
  ["_Route12Fisher1BattleText"] = "Evviva! Ha abboccato,\nproprio qui!",
  ["_Route12Fisher1EndBattleText"] = "Tch!\nSolo un pesciolino!",
  ["_Route12Fisher2AfterBattleText"] = "Con un AMO migliore\npotrei catturare\11POKéMON migliori!",
  ["_Route12Fisher2BattleText"] = "Pazienza!\nLa pesca richiede\11molta attesa!",
  ["_Route12Fisher2EndBattleText"] = "Quello\né scappato!",
  ["_Route12Fisher3AfterBattleText"] = "Mi hai battuto coi\nPOKéMON, ma io\11ci saccio con la pesca!",
  ["_Route12Fisher3BattleText"] = "Il DRITTO DELLA PESCA\ncontro il BIMBO POKéMON!",
  ["_Route12Fisher3EndBattleText"] = "Troppo\nforte!",
  ["_Route12Fisher4AfterBattleText"] = "Va bene lo stesso.\nPerdere non mi\11scoccia piu' di tanto.",
  ["_Route12Fisher4BattleText"] = "Preferirei\nlavorare!",
  ["_Route12Fisher4EndBattleText"] = "Non é\ncosi' semplice...",
  ["_Route12Fisher5AfterBattleText"] = "Pesco MAGIKARP\nin continuazione,\11ma sono debolissimi!",
  ["_Route12Fisher5BattleText"] = "Non sai mai cosa\npuoi pescare!",
  ["_Route12Fisher5EndBattleText"] = "Scappato!",
  ["_Route12Gate1FGuardText"] = "C'é un punto di\nosservazione al piano superiore.",
  ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "{PLAYER} riceve\nMT39!",
  ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "MT39 contiene\nPIrossino.\12é molto precisa,\nusala nelle lotte\11che non puoi\11permetterti di perdere.",
  ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "Non hai abbastanza\nspazio per questo.",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "Le ceneri del mio\nPOKéMON sono nella\11TORRE POKéMON.\12Tieni questa MT.\nNon mi serve\11piu'...",
  ["_Route12Gate2FLeftBinocularsText"] = "Hai guardato nei\nbinocoli.\12Un pescatore!",
  ["_Route12Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli.\12é la TORRE POKéMON!",
  ["_Route12SignText"] = "PERCORSO 12\nNord per LAVANDULA",
  ["_Route12SnorlaxCalmedDownText"] = "SNORLAX si é\ncalmato! Con un\11grande sbadiglio\11é tornato sui monti!",
  ["_Route12SnorlaxText"] = "Un POKéMON dormiente\nblocca la via!",
  ["_Route12SnorlaxWokeUpText"] = "SNORLAX si é svegliato!\12Ha sferrato un\nattacco furioso!",
  ["_Route12SportFishingSignText"] = "AREA DI PESCA SPORTIVA",
  ["_Route12SuperNerdAfterBattleText"] = "L'acqua é conduttrice\ndi elettricita',\11dovresti friggere\11i POKéMON marini!",
  ["_Route12SuperNerdBattleText"] = "L'elettricita' é la\nmia specialita'!",
  ["_Route12SuperNerdEndBattleText"] = "Spento!",
  ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "Sono il fratello\ndel GURU PESCATORE!\12Adoro pescare!\11Ti piace pescare?",
  ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "\12La pesca é uno\nstile di vita!\12Dai mari ai fiumi,\nesci e prendi il\11pesce grosso!",
  ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "Oh no!\12Avevo un regalo\nper te, ma non\11hai abbastanza spazio!",
  ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "Magnifico! Mi\npiace il tuo stile!\12Prendi questo e\npesca, giovanotto!\12{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_Route12SuperRodHouseFishingGuruThatsDisappointingText"] = "Oh... Che\ndelusione...",
  ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "Ciao, {PLAYER}!\12Usa il SUPERAMO\nin qualsiasi acqua!\11Potrai pescare\11diversi tipi di\11POKéMON.\12Prova a pescare\ndovunque tu possa!",
  ["_Route13Beauty1AfterBattleText"] = "Chissa' se sono\npiu' forti i POKéMON\11maschi o femmine?",
  ["_Route13Beauty1BattleText"] = "Certo, giochero'\ncon te!",
  ["_Route13Beauty1EndBattleText"] = "Oh!\nBrutto cavernicolo!",
  ["_Route13Beauty2AfterBattleText"] = "Non so nulla di\nPOKéMON. Mi piacciono\11solo quelli fighi!",
  ["_Route13Beauty2BattleText"] = "Vuoi POKéMONIzzare\ncon me?",
  ["_Route13Beauty2EndBattleText"] = "é gia'\nfinito?",
  ["_Route13BikerAfterBattleText"] = "Sparisci!",
  ["_Route13BikerBattleText"] = "Che guardi?",
  ["_Route13BikerEndBattleText"] = "Accidenti!\nMarce sgranate!",
  ["_Route13CooltrainerF1AfterBattleText"] = "Voglio diventare\nun bravo allenatore.\11Mi allenero' duro.",
  ["_Route13CooltrainerF1BattleText"] = "Dicono che me la\ncavaimo per la mia eta'!",
  ["_Route13CooltrainerF1EndBattleText"] = "Ohh!\nHo perso!",
  ["_Route13CooltrainerF2AfterBattleText"] = "So che hai preso\nquelle MEDAGLIE dai\11CAPIPALESTRA.",
  ["_Route13CooltrainerF2BattleText"] = "Wow! Che figate\nle tue MEDAGLIE!",
  ["_Route13CooltrainerF2EndBattleText"] = "Non\nbasta!",
  ["_Route13CooltrainerF3AfterBattleText"] = "Devi far lottare i\nPOKéMON per renderli\11piu' forti!",
  ["_Route13CooltrainerF3BattleText"] = "I miei cari POKéMON\nvogliono fare la\11tua conoscenza.",
  ["_Route13CooltrainerF3EndBattleText"] = "Wow!\nHai vinto alla grande!",
  ["_Route13CooltrainerF4AfterBattleText"] = "CALCIO ha aumentato\nla VELOCITA' dei\11miei POKéMON.",
  ["_Route13CooltrainerF4BattleText"] = "Ho trovato CALCIO\nin una grotta.",
  ["_Route13CooltrainerF4EndBattleText"] = "Che\nsbaglio!",
  ["_Route13CooltrainerM1AfterBattleText"] = "I miei POKéMON\nsembrano felici,\nnonostante abbiano perso.",
  ["_Route13CooltrainerM1BattleText"] = "I miei POKéMON\nvolatili vogliono\11fare a botte!",
  ["_Route13CooltrainerM1EndBattleText"] = "La mia\ncombo alata ha perso?",
  ["_Route13CooltrainerM2AfterBattleText"] = "Sono esausto. Credo\nche volero' a casa.",
  ["_Route13CooltrainerM2BattleText"] = "Il vento spira\ndalla mia parte!",
  ["_Route13CooltrainerM2EndBattleText"] = "Il vento\né cambiato!",
  ["_Route13CooltrainerM3AfterBattleText"] = "Vorrei volare\ncome PIDGEY e\11PIDGEOTTO...",
  ["_Route13CooltrainerM3BattleText"] = "Io scelgo sempre\ni POKéMON volatili!",
  ["_Route13CooltrainerM3EndBattleText"] = "Energia\nesaurita!",
  ["_Route13SignText"] = "PERCORSO 13\nNord per PONTE\11SILENZIO",
  ["_Route13TrainerTips1Text"] = "CONSIGLI AGLI ALLENATORI\12Guarda a sinistra\ndi quel palo!",
  ["_Route13TrainerTips2Text"] = "CONSIGLI AGLI ALLENATORI\12Usa SELECT per\ninvertire gli oggetti\11nello zaino!",
  ["_Route14Biker1AfterBattleText"] = "Che c'é, che c'é?\nChe cosa vuoi?",
  ["_Route14Biker1BattleText"] = "Forza, forza.\nAndiamo, andiamo,\11andiamo!",
  ["_Route14Biker1EndBattleText"] = "Argh!\nPerso! Sparisci!",
  ["_Route14Biker2AfterBattleText"] = "Allevare POKéMON\né una noia mortale.",
  ["_Route14Biker2BattleText"] = "Perfetto! Devo\nfar passare il tempo!",
  ["_Route14Biker2EndBattleText"] = "Cosa?\nTu!?",
  ["_Route14Biker3AfterBattleText"] = "é forte aver reso\ni tuoi POKéMON cosi'\11potenti!\12La forza comanda!\nE lo sai!",
  ["_Route14Biker3BattleText"] = "Gareggiamo qui\nperché c'é piu'\11spazio!",
  ["_Route14Biker3EndBattleText"] = "Spazzati via!",
  ["_Route14Biker4AfterBattleText"] = "Chissa' chi vincerebbe\ntra te e me, uno\11contro uno!",
  ["_Route14Biker4BattleText"] = "Lotta POKéMON?\nChe figata! Rissai!",
  ["_Route14Biker4EndBattleText"] = "Spazzato\nvia!",
  ["_Route14CooltrainerM1AfterBattleText"] = "Hai delle MN,\nvero? I POKéMON\11non possono mai\11dimenticare quelle mosse.",
  ["_Route14CooltrainerM1BattleText"] = "Devi usare le MT\nper insegnare mosse\11forti ai POKéMON!",
  ["_Route14CooltrainerM1EndBattleText"] = "Non\nbasta!",
  ["_Route14CooltrainerM2AfterBattleText"] = "Devono imparare\nmosse migliori.",
  ["_Route14CooltrainerM2BattleText"] = "I miei POKéMON\nvolatili sono pronti\11per la battaglia.",
  ["_Route14CooltrainerM2EndBattleText"] = "Non ancora\npronti!",
  ["_Route14CooltrainerM3AfterBattleText"] = "Insegna ai POKéMON\nmosse dello stesso\11tipo per renderli\11piu' potenti.",
  ["_Route14CooltrainerM3BattleText"] = "Le MT sono in vendita\na CELADOPOPOLI!\11Ma pochi hanno le MN!",
  ["_Route14CooltrainerM3EndBattleText"] = "Ahi,\nche sfortuna!",
  ["_Route14CooltrainerM4AfterBattleText"] = "I POKéMON volatili\nsono il mio amore!",
  ["_Route14CooltrainerM4BattleText"] = "Hai insegnato ai\ntuoi POKéMON volatili\11come usare VOLO?",
  ["_Route14CooltrainerM4EndBattleText"] = "Abbattuto\nin fiamme!",
  ["_Route14CooltrainerM5AfterBattleText"] = "I 3 POKéMON leggendari\nsono tutti rapaci.",
  ["_Route14CooltrainerM5BattleText"] = "Hai mai sentito\nparlare dei POKéMON\11leggendari?",
  ["_Route14CooltrainerM5EndBattleText"] = "Perché?\nPerché ho perso?",
  ["_Route14CooltrainerM6AfterBattleText"] = "Vincere o perdere,\nalla fine non\11conta nulla!",
  ["_Route14CooltrainerM6BattleText"] = "Non ne ho voglia,\nma OK! Andiamo!",
  ["_Route14CooltrainerM6EndBattleText"] = "Lo\nsapevo!",
  ["_Route14SignText"] = "PERCORSO 14\nOvest per FUCSIAPOLI",
  ["_Route15Beauty1AfterBattleText"] = "Ti perdono!\nPosso incassare!",
  ["_Route15Beauty1BattleText"] = "Oh, che carino\nche sei!",
  ["_Route15Beauty1EndBattleText"] = "Sembravi\ncosi' carino!",
  ["_Route15Beauty2AfterBattleText"] = "Mi piace tornare\na casa per stare\11con i miei POKéMON!",
  ["_Route15Beauty2BattleText"] = "Allevo POKéMON\nperché vivo da\11sola!",
  ["_Route15Beauty2EndBattleText"] = "Non l'avevo\nchiesto!",
  ["_Route15Biker1AfterBattleText"] = "Si vive una volta\nsola, percio' faccio\11il fuorilegge!\11IL TEAM ROCKET COMANDA!",
  ["_Route15Biker1BattleText"] = "Ehi ragazzo! Forza!\nLi ho appena presi!",
  ["_Route15Biker1EndBattleText"] = "Perché\nno?",
  ["_Route15Biker2AfterBattleText"] = "Stavo solo scherzando\nsui soldi!",
  ["_Route15Biker2BattleText"] = "Sborsa tutti i tuoi\nsoldi quando perdi\11con me, pivello!",
  ["_Route15Biker2EndBattleText"] = "Non puo'\nessere vero!",
  ["_Route15CooltrainerF1AfterBattleText"] = "Non puoi cambiare\nil soprannome dei\11POKéMON scambiati.\12Solo l'Allenatore\nOriginale puo'.",
  ["_Route15CooltrainerF1BattleText"] = "Fammi provare il\nPOKéMON che ho\11appena scambiato!",
  ["_Route15CooltrainerF1EndBattleText"] = "Non\nbasta!",
  ["_Route15CooltrainerF2AfterBattleText"] = "Ho paura dei BIKER,\nsono cosi' brutti\11e cattivi!",
  ["_Route15CooltrainerF2BattleText"] = "Tu hai una faccia\ngentile, credo di\11poterti battere!",
  ["_Route15CooltrainerF2EndBattleText"] = "No,\nsbagliato!",
  ["_Route15CooltrainerF3AfterBattleText"] = "Scambio POKéMON\ncon i miei amici!",
  ["_Route15CooltrainerF3BattleText"] = "Che c'é di figo?\nScambiare POKéMON!",
  ["_Route15CooltrainerF3EndBattleText"] = "Ho detto\nscambio!",
  ["_Route15CooltrainerF4AfterBattleText"] = "Vado ad allenarmi\ncon persone meno forti.",
  ["_Route15CooltrainerF4BattleText"] = "Vuoi giocare con\ni miei POKéMON?",
  ["_Route15CooltrainerF4EndBattleText"] = "Ero\ntroppo impaziente!",
  ["_Route15CooltrainerM1AfterBattleText"] = "Forse non sono\nportato per le lotte.",
  ["_Route15CooltrainerM1BattleText"] = "Quando fischio,\nposso chiamare i\11POKéMON volatili!",
  ["_Route15CooltrainerM1EndBattleText"] = "Ahi!\nChe tragico!",
  ["_Route15CooltrainerM2AfterBattleText"] = "Sapevi che mosse\ncome TERREMOTO non\11hanno alcun effetto\11sui volatili?",
  ["_Route15CooltrainerM2BattleText"] = "Hmm? I miei volatili\ntremano! Tu ci sai\11fare, eh?",
  ["_Route15CooltrainerM2EndBattleText"] = "Proprio\ncome pensavo!",
  ["_Route15Gate1FGuardText"] = "Stai completando\nil POKéDEX?\12L'AIUTANTE DEL PROF. OAK\né passato di qui.",
  ["_Route15Gate2FBinocularsText"] = "Hai guardato nei\nbinocoli.\12Sembra una piccola\nisola!",
  ["_Route15Gate2FOaksAideExpAllText"] = "CONDPIENA da' Punti\nESP a tutti i\11POKéMON con te,\11anche se non lottano.\12Tuttavia, riduce\nla quantita' di\nESP per ciascun\11POKéMON.\12Se non ti serve,\ndeponila tramite PC.",
  ["_Route15SignText"] = "PERCORSO 15\nOvest per FUCSIAPOLI",
  ["_Route15UpstairsBinocularsText"] = "Hai guardato nei\nbinocoli...\12Un grosso uccello\nlucente vola verso\11il mare.",
  ["_Route16Biker1AfterBattleText"] = "Ci piace ciondolare\nqui, che c'é?",
  ["_Route16Biker1BattleText"] = "Che cosa vuoi?",
  ["_Route16Biker1EndBattleText"] = "Non osare\nridere!",
  ["_Route16Biker2AfterBattleText"] = "Lascia stare, chi\nvuole la tua BICI!",
  ["_Route16Biker2BattleText"] = "Che bella BICI!\nFatti sotto!",
  ["_Route16Biker2EndBattleText"] = "Fuori\ncombattimento!",
  ["_Route16Biker3AfterBattleText"] = "Odio perdere!\nSparisci dalla mia vista!",
  ["_Route16Biker3BattleText"] = "Vieni fuori a\ngiocare, topolino!",
  ["_Route16Biker3EndBattleText"] = "Brutto\nratto!",
  ["_Route16Biker4AfterBattleText"] = "Puoi arrivare a\nFUCSIAPOLI da\11CELADOPOPOLI usando\11la strada costiera.",
  ["_Route16Biker4EndBattleText"] = "Kaboom!",
  ["_Route16Biker5AfterBattleText"] = "Mi piacciono i POKéMON\nferoci! Fanno a\11pezzi i nemici!",
  ["_Route16Biker5BattleText"] = "Ho una fame da\nlupi e sono cattivo!",
  ["_Route16Biker5EndBattleText"] = "Male,\nmale, male!",
  ["_Route16Biker6AfterBattleText"] = "Mi piace molestare\nla gente con i miei\11feroci POKéMON!",
  ["_Route16Biker6BattleText"] = "Certo, vengo!",
  ["_Route16Biker6EndBattleText"] = "Non farmi\narrabbiare!",
  ["_Route16CyclingRoadSignText"] = "Goditi la discesa!\nPISTA CICLABILE",
  ["_Route16FlyHouseBrunetteGirlHM02ExplanationText"] = "MN02 contiene VOLO.\nTi riportera' in\11qualsiasi citta'.\12Sfruttala al\nmeglio!",
  ["_Route16FlyHouseBrunetteGirlHM02NoRoomText"] = "Non hai abbastanza\nspazio per questo.",
  ["_Route16FlyHouseBrunetteGirlReceivedHM02Text"] = "{PLAYER} riceve\nMN02!",
  ["_Route16FlyHouseBrunetteGirlText"] = "Oh, hai trovato il\nmio rifugio segreto!\12Ti prego, non dire\na nessuno che sono qui.\11Ti faro' un regalo\11per farti perdonare!",
  ["_Route16FlyHouseFearowText"] = "FEAROW: Kyueen!",
  ["_Route16Gate1FGamblerText"] = "Come sei entrato?\nBuon impegno!",
  ["_Route16Gate1FGuardCyclingRoadExplanationText"] = "La PISTA CICLABILE é\nuna discesa sul mare.\11é una corsa fantastica.",
  ["_Route16Gate1FGuardNoPedestriansAllowedText"] = "I pedoni non sono\nammessi sulla PISTA\11CICLABILE!",
  ["_Route16Gate1FGuardWaitUpText"] = "Ehi tu! Aspetta,\nper favore!",
  ["_Route16Gate2FLeftBinocularsText"] = "Hai guardato nei\nbinocoli.\12é il CENTRO\nCOMMERCIALE!",
  ["_Route16Gate2FLittleBoyText"] = "Vado a fare un giro\ncon la mia ragazza!",
  ["_Route16Gate2FLittleGirlText"] = "Andiamo a fare\nun giro insieme!",
  ["_Route16Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli.\12C'é un lungo\nsentiero sull'acqua!",
  ["_Route16SignText"] = "PERCORSO 16\nCELADOPOPOLI -\11FUCSIAPOLI",
  ["_Route16SnorlaxReturnedToMountainsText"] = "Con un grande\nsbadiglio, SNORLAX\11é tornato sui monti!",
  ["_Route16SnorlaxWokeUpText"] = "SNORLAX si é svegliato!\12Ha sferrato un\nattacco furioso!",
  ["_Route16Text7"] = "Un POKéMON dormiente\nblocca la via!",
  ["_Route16biker4BattleText"] = "Ehi, mi hai\nappena urtato!",
  ["_Route17Biker10AfterBattleText"] = "Devo fare un\npo' di sonno!",
  ["_Route17Biker10BattleText"] = "Vattene ragazzo!\nSono distrutto!",
  ["_Route17Biker10EndBattleText"] = "Sei\nsoddisfatto?",
  ["_Route17Biker1AfterBattleText"] = "Ci sono begli oggetti\ngiu' sulla PISTA\11CICLABILE!",
  ["_Route17Biker1BattleText"] = "Non ci sono soldi a\nbattere i ragazzini!",
  ["_Route17Biker1EndBattleText"] = "Spento\nfuori!",
  ["_Route17Biker2AfterBattleText"] = "Potrei scaraventarti\nfuori di qui con\11una panciata!",
  ["_Route17Biker2BattleText"] = "Che vuoi, pivello?",
  ["_Route17Biker2EndBattleText"] = "Urca!",
  ["_Route17Biker3AfterBattleText"] = "Adoro correre in\ndiscesa!",
  ["_Route17Biker3BattleText"] = "Vai a FUCSIAPOLI?",
  ["_Route17Biker3EndBattleText"] = "Schiantato e\nbruciato!",
  ["_Route17Biker4AfterBattleText"] = "Cerchi avventure?",
  ["_Route17Biker4BattleText"] = "Siamo BIKER!\nStelle della strada!",
  ["_Route17Biker4EndBattleText"] = "Fumato!",
  ["_Route17Biker5AfterBattleText"] = "Ho preso il mio\nVOLTORB alla CENTRALE\11ABANDONATA.",
  ["_Route17Biker5BattleText"] = "Lascia che VOLTORB\nti fulmini!",
  ["_Route17Biker5EndBattleText"] = "Messo\nal tappeto!",
  ["_Route17Biker6AfterBattleText"] = "Forse alcuni POKéMON\nhanno bisogno di\11PIETRE per evolversi.",
  ["_Route17Biker6BattleText"] = "I miei POKéMON non\nsi evolvono! Perché?",
  ["_Route17Biker6EndBattleText"] = "Ma guarda\nte!",
  ["_Route17Biker7AfterBattleText"] = "Scommetto che ho\nperso peso qui!",
  ["_Route17Biker7BattleText"] = "Ho bisogno di un\npo' di esercizio!",
  ["_Route17Biker7EndBattleText"] = "Uff!\nBel allenamento!",
  ["_Route17Biker8AfterBattleText"] = "Preparati a lottare\nper le tue idee!",
  ["_Route17Biker8BattleText"] = "Fai il ribelle!",
  ["_Route17Biker8EndBattleText"] = "Aaaargh!",
  ["_Route17Biker9AfterBattleText"] = "La discesa rende\ndifficile sterzare!",
  ["_Route17Biker9BattleText"] = "Bella BICI!\nCome si guida?",
  ["_Route17Biker9EndBattleText"] = "Acciderboli!",
  ["_Route17CyclingRoadEndsSignText"] = "PISTA CICLABILE\nLa pendenza finisce qui!",
  ["_Route17NoticeSign1Text"] = "é un avviso!\12Attenzione agli\noggetti scartati!",
  ["_Route17NoticeSign2Text"] = "é un avviso!\12Non buttare la partita,\nbutta le POKé BALL!",
  ["_Route17SignText"] = "PERCORSO 17\nCELADOPOPOLI -\11FUCSIAPOLI",
  ["_Route17TrainerTips1Text"] = "CONSIGLI AGLI ALLENATORI\12Tutti i POKéMON\nsono unici.\12Anche quelli dello\nstesso tipo e livello\11crescono con\11ritmi diversi.",
  ["_Route17TrainerTips2Text"] = "CONSIGLI AGLI ALLENATORI\12Premi il Pulsante A o\nB per restare fermo\11sulla pendenza.",
  ["_Route18CooltrainerM1AfterBattleText"] = "Vorrei tanto una\nBICI!",
  ["_Route18CooltrainerM1BattleText"] = "Controllo sempre\nogni zona erbosa\11per nuovi POKéMON.",
  ["_Route18CooltrainerM1EndBattleText"] = "Tch!",
  ["_Route18CooltrainerM2AfterBattleText"] = "Nei fine settimana\nraccolgo anche\11POKéMON marini!",
  ["_Route18CooltrainerM2BattleText"] = "Kurukkoo!\nTi piace il mio\11verso da uccello?",
  ["_Route18CooltrainerM2EndBattleText"] = "Dovevo\nproprio scocciarti!",
  ["_Route18CooltrainerM3AfterBattleText"] = "Questo é il mio\nposto preferito per\11la caccia ai POKéMON!",
  ["_Route18CooltrainerM3BattleText"] = "Questo é il mio\nterritorio! Fuori di qui!",
  ["_Route18CooltrainerM3EndBattleText"] = "Acciderboli!",
  ["_Route18CyclingRoadSignText"] = "PISTA CICLABILE\nVietato l'accesso\11ai pedoni!",
  ["_Route18Gate1FGuardCyclingRoadUphillText"] = "Da qui in poi la\nPISTA CICLABILE é\11tutta in salita.",
  ["_Route18Gate1FGuardExcuseMeText"] = "Ehi tu!",
  ["_Route18Gate1FGuardYouNeedABicycleText"] = "Ti serve una BICICLETTA\nper la PISTA CICLABILE!",
  ["_Route18Gate2FLeftBinocularsText"] = "Hai guardato nei\nbinocoli.\12BIANCAVILLA é a ovest!",
  ["_Route18Gate2FRightBinocularsText"] = "Hai guardato nei\nbinocoli.\12Ci sono persone\nche nuotano!",
  ["_Route18SignText"] = "PERCORSO 18\nCELADOPOPOLI -\11FUCSIAPOLI",
  ["_Route19CooltrainerM1AfterBattleText"] = "Grazie, ragazzo!\nSono pronto per una\11nuotata!",
  ["_Route19CooltrainerM1BattleText"] = "Devo scaldarmi\nprima di nuotare!",
  ["_Route19CooltrainerM1EndBattleText"] = "Tutto\nriscaldato!",
  ["_Route19CooltrainerM2AfterBattleText"] = "Attenzione ai\nTENTACOOL!",
  ["_Route19CooltrainerM2BattleText"] = "Aspetta! Ti viene\nun attacco cardiaco!",
  ["_Route19CooltrainerM2EndBattleText"] = "Ooh!\nChe gelido!",
  ["_Route19SignText"] = "PERCORSO MARINO 19\nFUCSIAPOLI -\11ISOLE SPUMA",
  ["_Route19Swimmer1AfterBattleText"] = "Posso battere i\nPOKéMON a nuoto!",
  ["_Route19Swimmer1BattleText"] = "Adoro nuotare!\nE tu?",
  ["_Route19Swimmer1EndBattleText"] = "Tuffo\na pancia!",
  ["_Route19Swimmer2AfterBattleText"] = "Vedo un paio\ndi isole!",
  ["_Route19Swimmer2BattleText"] = "Cosa c'é oltre\nl'orizzonte?",
  ["_Route19Swimmer2EndBattleText"] = "Glub!",
  ["_Route19Swimmer3AfterBattleText"] = "Devi pescare per\ntrovare POKéMON marini!",
  ["_Route19Swimmer3BattleText"] = "Ho provato ad\nimmergermi per i\11POKéMON, ma nulla!",
  ["_Route19Swimmer3EndBattleText"] = "Aiuto!",
  ["_Route19Swimmer4AfterBattleText"] = "Guardo il mare\nper dimenticare!",
  ["_Route19Swimmer4BattleText"] = "Guardo il mare\nper dimenticare!",
  ["_Route19Swimmer4EndBattleText"] = "Ooh!\nChe trauma!",
  ["_Route19Swimmer5AfterBattleText"] = "C'é ancora molta\nstrada per le\11ISOLE SPUMA.",
  ["_Route19Swimmer5BattleText"] = "Oh, adoro il tuo\nmezzo! Posso averlo\11se vinco?",
  ["_Route19Swimmer5EndBattleText"] = "Oh!\nHo perso!",
  ["_Route19Swimmer6AfterBattleText"] = "Il mio ragazzo\nvoleva nuotare fino\11alle ISOLE SPUMA.",
  ["_Route19Swimmer6BattleText"] = "Nuotare é fantastico!\nLe scottature no!",
  ["_Route19Swimmer6EndBattleText"] = "Che shock!",
  ["_Route19Swimmer7AfterBattleText"] = "Ho un crampo!\nGlub, glub...",
  ["_Route19Swimmer7BattleText"] = "Queste acque sono\ntraditrici!",
  ["_Route19Swimmer7EndBattleText"] = "Ooh!\nPericoloso!",
  ["_Route19Swimmer8AfterBattleText"] = "LAPRAS é cosi'\ngrande, ti terra'\11sicuramente asciutto.",
  ["_Route19Swimmer8BattleText"] = "Ho nuotato fino\nqui, ma sono stanco.",
  ["_Route19Swimmer8EndBattleText"] = "Sono\nesausto...",
  ["_Route1SignText"] = "PERCORSO 1\nBIANCAVILLA -\11VIRIDIA",
  ["_Route1Youngster1AlsoGotPokeballsText"] = "Abbiamo anche delle\nPOKé BALL per\11catturare POKéMON!",
  ["_Route1Youngster1GotPotionText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_Route1Youngster1MartSampleText"] = "Ciao! Lavoro in un\nPOKé MARKET.\12é un negozio utile,\nvisitalo a\11VIRIDIA.\12Sai che c'é? Ti\ndo' un campione!\11Eccolo!",
  ["_Route1Youngster1NoRoomText"] = "Hai troppa roba\ncon te!",
  ["_Route1Youngster2Text"] = "Vedi quei dislivelli\nlungo la strada?\12é un po' spaventoso,\nma puoi saltare\11giu'.\12Puoi tornare a\nBIANCAVILLA piu'\11rapidamente in quel modo.",
  ["_Route20CooltrainerMAfterBattleText"] = "I miei uccelli\nnon possono portarmi\11indietro con VOLO!",
  ["_Route20CooltrainerMBattleText"] = "Sono arrivato qui\nin sella al mio\11POKéMON volatile!",
  ["_Route20CooltrainerMEndBattleText"] = "Oh\nno!",
  ["_Route20SeafoamIslandsSignText"] = "ISOLE SPUMA",
  ["_Route20Swimmer1AfterBattleText"] = "Vorrei tanto\ncavalcare i POKéMON.",
  ["_Route20Swimmer1BattleText"] = "Qui l'acqua\né bassa.",
  ["_Route20Swimmer1EndBattleText"] = "Splash!",
  ["_Route20Swimmer2AfterBattleText"] = "C'é un'enorme\ncaverna sotto\11quest'isola.",
  ["_Route20Swimmer2BattleText"] = "SPUMA é un\nrifugio tranquillo!",
  ["_Route20Swimmer2EndBattleText"] = "Smetti!",
  ["_Route20Swimmer3AfterBattleText"] = "Vuoi galleggiare\ncon me?",
  ["_Route20Swimmer3BattleText"] = "Adoro galleggiare\ninsieme ai pesci!",
  ["_Route20Swimmer3EndBattleText"] = "Ahi!",
  ["_Route20Swimmer4AfterBattleText"] = "Una volta SPUMA\nera un'isola sola!",
  ["_Route20Swimmer4BattleText"] = "Sei in vacanza\nanche tu?",
  ["_Route20Swimmer4EndBattleText"] = "Nessuna\npieta'!",
  ["_Route20Swimmer5AfterBattleText"] = "Avrei dovuto\nallenare i POKéMON,\nnon me stesso!",
  ["_Route20Swimmer5BattleText"] = "Guarda il mio\nfisico bestiale!",
  ["_Route20Swimmer5EndBattleText"] = "Imbranato!",
  ["_Route20Swimmer6AfterBattleText"] = "Cavalcare un POKéMON\nsembra proprio forte!",
  ["_Route20Swimmer6BattleText"] = "Perché cavalchi un\nPOKéMON? Non sai\11nuotare?",
  ["_Route20Swimmer6EndBattleText"] = "Ahi!\nSilurato!",
  ["_Route20Swimmer7AfterBattleText"] = "Le mie perle\nverranno piu' grandi\11dentro CLOYSTER?",
  ["_Route20Swimmer7BattleText"] = "Il mio ragazzo mi\nha dato grandi perle!",
  ["_Route20Swimmer7EndBattleText"] = "Non toccare\nle mie perle!",
  ["_Route20Swimmer8AfterBattleText"] = "I POKéMON hanno\noccupato una villa\11abbandonata a\11ISOLA CANNELLA!",
  ["_Route20Swimmer8BattleText"] = "Ho nuotato fino a\nqui da ISOLA CANNELLA!",
  ["_Route20Swimmer8EndBattleText"] = "Sono\ncosi' deluso!",
  ["_Route20Swimmer9AfterBattleText"] = "CANNELLA é un'isola\nvulcanica!",
  ["_Route20Swimmer9BattleText"] = "CANNELLA, a ovest,\nha un LABORATORIO\11per POKéMON.",
  ["_Route20Swimmer9EndBattleText"] = "Aspetta!",
  ["_Route21Fisher1AfterBattleText"] = "Non riesco a prendere\nniente di buono!",
  ["_Route21Fisher1BattleText"] = "Vuoi sapere se i\npesci abboccano?",
  ["_Route21Fisher1EndBattleText"] = "Accidenti!",
  ["_Route21Fisher2AfterBattleText"] = "Sembra che io\npeschi solo MAGIKARP!",
  ["_Route21Fisher2BattleText"] = "Ho fatto un grosso\nbottino! Ci provi?",
  ["_Route21Fisher2EndBattleText"] = "Maledetti\nMAGIKARP!",
  ["_Route21Fisher3AfterBattleText"] = "Ero solo arrabbiato\nperché non riuscivo\11a prendere nulla.",
  ["_Route21Fisher3BattleText"] = "Ehi, non spaventare\ni pesci!",
  ["_Route21Fisher3EndBattleText"] = "Scusa!\nNon volevo!",
  ["_Route21Fisher4AfterBattleText"] = "Oh aspetta! Ha\nabboccato! Evviva!",
  ["_Route21Fisher4BattleText"] = "Tienimi compagnia\nfinché non prendo qualcosa!",
  ["_Route21Fisher4EndBattleText"] = "Questo ha fatto\npassare il tempo.",
  ["_Route21Swimmer1AfterBattleText"] = "Mi piacciono anche\ni monti!",
  ["_Route21Swimmer1BattleText"] = "Il mare purifica\nil mio corpo e l'anima!",
  ["_Route21Swimmer1EndBattleText"] = "Ayah!",
  ["_Route21Swimmer2AfterBattleText"] = "A chi assomiglio?\nA un salvagente\11bucato? Sparisci!",
  ["_Route21Swimmer2BattleText"] = "Cosa c'é che non\nva se nuoto?",
  ["_Route21Swimmer2EndBattleText"] = "Colpo\nbasso!",
  ["_Route21Swimmer3AfterBattleText"] = "Dove hai catturato\ni tuoi POKéMON?",
  ["_Route21Swimmer3BattleText"] = "Ho catturato tutti\ni miei POKéMON in mare!",
  ["_Route21Swimmer3EndBattleText"] = "Sub!!\nGiu'!!",
  ["_Route21Swimmer4AfterBattleText"] = "Sono esausto!\nMa mi restano la\11gara di bici e\11la maratona!",
  ["_Route21Swimmer4BattleText"] = "Ora sono impegnato\nin un triathlon!",
  ["_Route21Swimmer4EndBattleText"] = "Ansimante...\nansimante...",
  ["_Route21Swimmer5AfterBattleText"] = "Sono cotto al\nsole!",
  ["_Route21Swimmer5BattleText"] = "Ahh! Senti il\nsole e il vento!",
  ["_Route21Swimmer5EndBattleText"] = "Ahi!\nHo perso!",
  ["_Route22GateGuardGoRightAheadText"] = "Oh! Quella é la\nMEDAGLIA SASSO!\11Prendi pure!",
  ["_Route22GateGuardICantLetYouPassText"] = "\12Le regole sono\nregole. Non posso\11lasciarti passare.",
  ["_Route22GateGuardNoBoulderbadgeText"] = "Solo i veri abili\nallenatori possono\11passare.\12Non hai ancora\nla MEDAGLIA SASSO!",
  ["_Route22PokemonLeagueSignText"] = "LEGA POKéMON\nIngresso Principale",
  ["_Route22Rival1DefeatedText"] = "Acciderboli!\nHai avuto solo\11fortuna!",
  ["_Route22Rival1VictoryText"] = "{RIVAL}: Cosa?\nPerché ho 2\11POKéMON?\12Dovresti catturarne\11altri anche tu!",
  ["_Route22Rival2DefeatedText"] = "Cosa!?\12Sono stato\nsolo disattento!",
  ["_Route22Rival2VictoryText"] = "{RIVAL}: Hahaha!\n{PLAYER}! é il tuo\11meglio? Non vali\11un tubo, amico!\12Va ad allenarti\nancora! Perdente!",
  ["_Route22RivalAfterBattleText1"] = "Ho sentito che la\nLEGA POKéMON ha\11molti allenatori forti!\12Devo capire come\nsuperarli!\12Smettila di ciondolare\ne datti una mossa!",
  ["_Route22RivalAfterBattleText2"] = "Questo mi ha\nsganciato! Sono pronto\11per la LEGA POKéMON!\12{PLAYER}, ti serve\npiu' pratica!\12Ma lo sai anche\ntu! Me ne vado.\nCi si vede!",
  ["_Route22RivalBeforeBattleText1"] = "{RIVAL}: Ehi!\n{PLAYER}!\12Vai alla\nLEGA POKéMON?\12Scordatelo! Probabilmente\nnon hai MEDAGLIE!\12La guardia non\nti fara' passare!\12A proposito, i tuoi\nPOKéMON sono\11diventati piu' forti?",
  ["_Route22RivalBeforeBattleText2"] = "{RIVAL}: Cosa?\n{PLAYER}! Che\11sorpresa vederti\11qui!\12Quindi vai alla\nLEGA POKéMON?\12Hai raccolto anche\ntutte le MEDAGLIE?\11Forte!\12Allora ti concero'\nper le feste {PLAYER}\ncome riscaldamento\11per la LEGA!\12Vieni avanti!",
  ["_Route23GoRightAheadText"] = "\12Bene allora!\nPrendi pure!",
  ["_Route23OhThatIsTheBadgeText"] = "Puoi passare solo\nse hai con te\11{RAM:wNameBuffer}!\12Oh! Quella é\n{RAM:wNameBuffer}!",
  ["_Route23VictoryRoadGateSignText"] = "Varco della Via Vittoria\n- LEGA POKéMON",
  ["_Route23YouDontHaveTheBadgeYetText"] = "Puoi passare solo\nse hai con te\11{RAM:wNameBuffer}!\12Non hai ancora\n{RAM:wNameBuffer}!\12Devi averla per\nraggiungere la\11LEGA POKéMON!",
  ["_Route24CooltrainerF1AfterBattleText"] = "Ce l'ho messa tutta,\nnon ho rimpianti!",
  ["_Route24CooltrainerF1BattleText"] = "Sono la n. 4!\nTi stai stancando?",
  ["_Route24CooltrainerF1EndBattleText"] = "Ho perso\nanche io!",
  ["_Route24CooltrainerF2AfterBattleText"] = "Ce l'ho messa tutta,\nnon ho rimpianti!",
  ["_Route24CooltrainerF2BattleText"] = "Sono la seconda!\nOra si fa sul serio!",
 ["_Route24CooltrainerF2EndBattleText"] = "Come ho\npotuto perdere?",
  ["_Route24CooltrainerM1DefeatedText"] = "Arrgh!\nCi sai fare!",
  ["_Route24CooltrainerM1JoinTeamRocketText"] = "A proposito, ti\nandrebbe di entrare\11nel TEAM ROCKET?\12Siamo un gruppo\ndedicato al male\11grazie ai POKéMON!\12Vuoi unirti?\12Sei sicuro?\12Forza, unisciti a noi!\12Ti sto dicendo\ndi unirti!\12OK, hai bisogno\ndi convinzione!\12Ti faro' un'offerta\nche non potrai\11rifiutare!",
  ["_Route24CooltrainerM1NoRoomText"] = "Non hai abbastanza\nspazio!",
  ["_Route24CooltrainerM1ReceivedNuggetText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_Route24CooltrainerM1YouBeatOurContestText"] = "Complimenti!\nHai battuto i nostri\115 allenatori!",
  ["_Route24CooltrainerM1YouCouldBecomeATopLeaderText"] = "Con le tue capacita'\npotresti diventare\11un capo nel\11TEAM ROCKET!",
  ["_Route24CooltrainerM1YouJustEarnedAPrizeText"] = "\12Hai appena vinto\nun premio favoloso!",
  ["_Route24CooltrainerM2AfterBattleText"] = "Mi sono nascosto\nperché la gente sul\11ponte mi spaventava!",
  ["_Route24CooltrainerM2BattleText"] = "Ho visto la tua\nimpresa dall'erba!",
  ["_Route24CooltrainerM2EndBattleText"] = "Non\ncredevo!",
  ["_Route24CooltrainerM3AfterBattleText"] = "Ce l'ho messa tutta,\nnon ho rimpianti!",
  ["_Route24CooltrainerM3BattleText"] = "OK! Sono il n. 5!\nTi faro' a pezzi!",
  ["_Route24CooltrainerM3EndBattleText"] = "Urca!\nTroppo forte!",
  ["_Route24Youngster1AfterBattleText"] = "Ce l'ho messa tutta,\nnon ho rimpianti!",
  ["_Route24Youngster1BattleText"] = "Ecco il n. 3!\nNon saro' un osso facile!",
  ["_Route24Youngster1EndBattleText"] = "Ahi!\nSchiacciato al suolo!",
  ["_Route24Youngster2AfterBattleText"] = "Ce l'ho messa tutta,\nnon ho rimpianti!",
  ["_Route24Youngster2BattleText"] = "Questo é il PONTE\nNUGGET! Batti 5 di\11noi e vinci un\11premio favoloso!\12Pensi di farcela?",
  ["_Route24Youngster2EndBattleText"] = "Urca!\nRoba forte!",
  ["_Route25BillSignText"] = "VILLA MARINA\nQui abita BILL",
  ["_Route25CooltrainerF1AfterBattleText"] = "Vorrei che il mio\nragazzo fosse bravo\11come te!",
  ["_Route25CooltrainerF1BattleText"] = "Ciao! Il mio ragazzo\né un figo!",
  ["_Route25CooltrainerF1EndBattleText"] = "Ero in cattive\ncondizioni!",
  ["_Route25CooltrainerF2AfterBattleText"] = "Vieni dal MONTE\nLUNA? Posso avere\11un CLEFAIRY?",
  ["_Route25CooltrainerF2BattleText"] = "Il mio amico ha un\nPOKéMON carino.\11Che invidia!",
  ["_Route25CooltrainerF2EndBattleText"] = "Non sono\ncosi' invidiosa!",
  ["_Route25CooltrainerMAfterBattleText"] = "Pazienza. La mia\nragazza mi consolera'.",
  ["_Route25CooltrainerMBattleText"] = "Sono un tipo forte.\nHo una ragazza!",
  ["_Route25CooltrainerMEndBattleText"] = "Ahi,\naccidenti...",
  ["_Route25Hiker1AfterBattleText"] = "Acciderboli!\nUno ZUBAT mi ha\11morsoso laggiu'.",
  ["_Route25Hiker1BattleText"] = "Vengo giu' dal MONTE\nLUNA, ma sono pronto!",
  ["_Route25Hiker1EndBattleText"] = "Ti sei\nimpegnato duro!",
  ["_Route25Hiker2AfterBattleText"] = "Il collezionista\nha moltissimi POKéMON\11rari.",
  ["_Route25Hiker2BattleText"] = "Vado a trovare un\ncollezionista di\11POKéMON al capo!",
  ["_Route25Hiker2EndBattleText"] = "Mi hai\npreso.",
  ["_Route25Hiker3AfterBattleText"] = "Il sentiero in\nbasso é una scorciatoia\11per CERULOPOLI.",
  ["_Route25Hiker3BattleText"] = "Vai a trovare BILL?\nPrima lottiamo!",
  ["_Route25Hiker3EndBattleText"] = "Ci sai\nproprio fare.",
  ["_Route25Youngster1AfterBattleText"] = "Tutti i POKéMON\nhanno debolezze. é\11meglio allevarne\11di vari tipi.",
  ["_Route25Youngster1BattleText"] = "Gli allenatori locali\nvengono qui ad\11allenarsi!",
  ["_Route25Youngster1EndBattleText"] = "Te la\ncavi.",
  ["_Route25Youngster2AfterBattleText"] = "Sulla M.N. ANNA\nho visto allenatori\11di tutto il mondo.",
  ["_Route25Youngster2BattleText"] = "Mio padre mi ha\nportato a una festa\11fantastica sulla\11M.N. ANNA a VERMIGLIA!",
  ["_Route25Youngster2EndBattleText"] = "Non sono\narrabbiato!",
  ["_Route25Youngster3AfterBattleText"] = "Se il tuo POKéMON\né confuso o dorme,\11sostituiscilo!",
  ["_Route25Youngster3BattleText"] = "Sapevo che avrei\ndovuto lottare con te!",
  ["_Route25Youngster3EndBattleText"] = "Sapevo\nche avrei perso!",
  ["_Route2DiglettsCaveSignText"] = "GROTTA DIGLETT",
  ["_Route2GateOaksAideFlashExplanationText"] = "La MN FLASH illumina\nanche i sotterranei\11piu' bui.",
  ["_Route2GateYoungsterText"] = "Una volta che un\nPOKéMON impara FLASH,\11puoi attraversare\11la GROTTA DIGLETT.",
  ["_Route2SignText"] = "PERCORSO 2\nVIRIDIA -\11PLUMOPOLI",
  ["_Route2TradeHouseScientistText"] = "Un POKéMON svenuto\nnon puo' lottare. Ma\11puo' ancora usare\11mosse come TAGLIO!",
  ["_Route3CooltrainerF1AfterBattleText"] = "Smettila di fissare\nse non vuoi lottare!",
  ["_Route3CooltrainerF1BattleText"] = "Mi hai guardato,\nvero?",
  ["_Route3CooltrainerF1EndBattleText"] = "Sei\nproprio cattivo!",
  ["_Route3CooltrainerF2AfterBattleText"] = "Evita le lotte\nnon facendoti\11vedere dalla gente!",
  ["_Route3CooltrainerF2BattleText"] = "Quella tua occhiata,\né cosi' intrigante!",
  ["_Route3CooltrainerF2EndBattleText"] = "Sii gentile!",
  ["_Route3CooltrainerF3AfterBattleText"] = "Il PERCORSO 4 é\nai piedi del MONTE LUNA.",
  ["_Route3CooltrainerF3BattleText"] = "Eek! Mi hai\ntoccato?",
  ["_Route3CooltrainerF3EndBattleText"] = "Tutto qui?",
  ["_Route3SignText"] = "PERCORSO 3\nMONTE LUNA",
  ["_Route3Text1"] = "Uff... Meglio\nriposare un po'...\11Mh... \12Quel tunnel da\nCERULOPOLI ti\11 sfinisce!",
  ["_Route3Youngster1AfterBattleText"] = "Ci sono altri tipi\ndi POKéMON oltre\11a quelli del bosco!",
  ["_Route3Youngster1BattleText"] = "Ehi! Ti ho visto\nnel BOSCO VIRIDIA!",
  ["_Route3Youngster1EndBattleText"] = "Mi hai\nbattuto di nuovo!",
  ["_Route3Youngster2AfterBattleText"] = "Stai depositando i\nPOKéMON sul PC? Ogni\11BOX puo' contenerne 20!",
  ["_Route3Youngster2BattleText"] = "Ciao! Mi piacciono\ni pantaloncini!\11Sono comodi e\11facili da indossare!",
  ["_Route3Youngster2EndBattleText"] = "Non ci\nposso credere!",
  ["_Route3Youngster3AfterBattleText"] = "Se un BOX POKéMON\nnel PC si riempie,\11passa a un altro!",
  ["_Route3Youngster3BattleText"] = "Sei un allenatore?\nLottiamo!",
  ["_Route3Youngster3EndBattleText"] = "Se avessi avuto\nnuovi POKéMON\11avrei vinto!",
  ["_Route3Youngster4AfterBattleText"] = "Indosso sempre\npantaloncini, anche\11in inverno!",
  ["_Route3Youngster4BattleText"] = "Ehi! Non porti i\npantaloncini!",
  ["_Route3Youngster4EndBattleText"] = "Perso!\nPerso! Perso!",
  ["_Route3Youngster5AfterBattleText"] = "I POKéMON allenati\nsono piu' forti di\11quelli selvatici!",
  ["_Route3Youngster5BattleText"] = "Puoi lottare contro\nil mio nuovo POKéMON!",
  ["_Route3Youngster5EndBattleText"] = "Fatto\ne finito!",
  ["_Route4CooltrainerF1Text"] = "Ahi! Sono inciampata\nsu un POKéMON\11roccioso, GEODUDE!",
  ["_Route4CooltrainerF2AfterBattleText"] = "Forse non ci sono\naltri funghi qui.\12Credo di averli\npresi tutti.",
  ["_Route4CooltrainerF2BattleText"] = "Sono venuta a\nprendere il mio\11POKéMON fungo!",
  ["_Route4CooltrainerF2EndBattleText"] = "Oh! Il mio\ncaro POKéMON fungo!",
  ["_Route4MtMoonSignText"] = "MONTE LUNA\nIngresso Tunnel",
  ["_Route4SignText"] = "PERCORSO 4\nMONTE LUNA -\11CERULOPOLI",
  ["_Route5UndergroundPathSignText"] = "SOTTERRANEO\nCERULOPOLI -\11VERMIGLIA",
  ["_Route6CooltrainerAfterBattleText"] = "Sussurro...\nsussurro...",
  ["_Route6CooltrainerF1BattleText"] = "Scusa! Questa é una\nconversazione privata!",
  ["_Route6CooltrainerF1EndBattleText"] = "Ugh!\nOdio perdere!",
  ["_Route6CooltrainerF2AfterBattleText"] = "Voglio diventare\npiu' forte! Qual é\11il tuo segreto?",
  ["_Route6CooltrainerF2BattleText"] = "Io? Beh, OK.\nGiochiamo!",
  ["_Route6CooltrainerF2EndBattleText"] = "Non ha\nfunzionato!",
  ["_Route6CooltrainerM1BattleText"] = "Chi c'é?\nSmettila di origliare!",
  ["_Route6CooltrainerM1EndBattleText"] = "Proprio\nnon riesco a vincere!",
  ["_Route6CooltrainerM2AfterBattleText"] = "Dovrei portare con\nme piu' POKéMON\11per sicurezza.",
  ["_Route6CooltrainerM2BattleText"] = "Mh? Vuoi parlare\ncon me?",
  ["_Route6CooltrainerM2EndBattleText"] = "Non ho\niniziato io!",
  ["_Route6UndergroundPathSignText"] = "SOTTERRANEO\nCERULOPOLI -\11VERMIGLIA",
  ["_Route6Youngster1AfterBattleText"] = "Mi piacciono gli\ninsetti, torno nel\11BOSCO VIRIDIA.",
  ["_Route6Youngster1BattleText"] = "Non ci sono molti\ninsetti qui fuori.",
  ["_Route6Youngster1EndBattleText"] = "No!\nScherzi!",
  ["_Route6Youngster2AfterBattleText"] = "I miei POKéMON\nsono deboli? O sono\11scarso io?",
  ["_Route6Youngster2BattleText"] = "Non ti ho mai\nvisto in giro!\11Ci sai fare?",
  ["_Route6Youngster2EndBattleText"] = "Ci sai\nproprio fare!",
  ["_Route7UndergroundPathSignText"] = "SOTTERRANEO\nCELADOPOPOLI -\11LAVANDULA",
  ["_Route8CooltrainerF1AfterBattleText"] = "Quando i POKéMON\ncrescono diventano\11brutti! Non dovrebbero\11evolversi!",
  ["_Route8CooltrainerF1BattleText"] = "Mi piace NIDORAN,\npercio' li raccolgo!",
  ["_Route8CooltrainerF1EndBattleText"] = "Perché? Perché??",
  ["_Route8CooltrainerF2AfterBattleText"] = "Penso che PIDGEY\ne RATTATA siano\11carini!",
  ["_Route8CooltrainerF2BattleText"] = "MEOWTH é cosi' carino,\nmiao, miao, miao!",
  ["_Route8CooltrainerF2EndBattleText"] = "Miao!",
  ["_Route8CooltrainerF3AfterBattleText"] = "La guardia di\nZAFFERANOPOLI non\11ci fa passare.\11é proprio cattiva!",
  ["_Route8CooltrainerF3BattleText"] = "Dobbiamo sembrare\nstupiducci a star\11qui cosi'!",
  ["_Route8CooltrainerF3EndBattleText"] = "Guarda cosa\nhai fatto!",
  ["_Route8CooltrainerF4AfterBattleText"] = "Ho sentito che\nCLEFAIRY si evolve\11se esposto a una\11PIETRALUNARE.",
  ["_Route8CooltrainerF4BattleText"] = "Qual é un POKéMON\ncarino, rotondo\11e soffice?",
  ["_Route8CooltrainerF4EndBattleText"] = "Fermati!\12Non essere cosi'\ncattivo col mio CLEFAIRY!",
  ["_Route8Gambler1AfterBattleText"] = "La dea bendata non\né con me oggi!",
  ["_Route8Gambler1BattleText"] = "Bene! Lanciamo\ni dadi!",
  ["_Route8Gambler1EndBattleText"] = "Acciderboli!\nMancato di poco!",
  ["_Route8Gambler2AfterBattleText"] = "Il gioco d'azzardo\ne i POKéMON sono\11come le ciliegie!\11Non puoi smettere!",
  ["_Route8Gambler2BattleText"] = "Sono un tipo che\nrischia sempre!",
  ["_Route8Gambler2EndBattleText"] = "Mancato il\ngrosso colpo!",
  ["_Route8SuperNerd1AfterBattleText"] = "Me la cavo meglio\na scuola che qui!",
  ["_Route8SuperNerd1BattleText"] = "Te la cavi coi\nPOKéMON, ma come\11vani in chimica?",
  ["_Route8SuperNerd1EndBattleText"] = "Ahi!\nCollasso nucleare!",
  ["_Route8SuperNerd2AfterBattleText"] = "Vai con GRIMER\nprima... e...\11...e... poi...",
  ["_Route8SuperNerd2BattleText"] = "Ci vuole strategia\nper vincere qui!",
  ["_Route8SuperNerd2EndBattleText"] = "Non ha\nsenso logico!",
  ["_Route8SuperNerd3AfterBattleText"] = "Siamo bloccati\nqui a causa dei\11cancelli di ZAFFERANO.",
  ["_Route8SuperNerd3BattleText"] = "La scuola é\ndivertente, ma anche\11i POKéMON.",
  ["_Route8SuperNerd3EndBattleText"] = "Resto a\nstudiare.",
  ["_Route8UndergroundSignText"] = "SOTTERRANEO\nCELADOPOPOLI -\11LAVANDULA",
  ["_Route9CooltrainerF1AfterBattleText"] = "Ti serve luce per\nattraversare quel\11tunnel buio piu' avanti.",
  ["_Route9CooltrainerF1BattleText"] = "Hai con te dei\nPOKéMON!\11Sei mio!",
  ["_Route9CooltrainerF1EndBattleText"] = "Mi hai\ningannato!",
  ["_Route9CooltrainerF2AfterBattleText"] = "Hai talento! In\n bocca al lupo!",
  ["_Route9CooltrainerF2BattleText"] = "Non osare\ncompatirmi!",
  ["_Route9CooltrainerF2EndBattleText"] = "No!\nSei troppo forte!",
  ["_Route9CooltrainerM1AfterBattleText"] = "Continua a camminare!",
  ["_Route9CooltrainerM1BattleText"] = "Chi é quello che\ncammina con quei\11bellissimi POKéMON?",
  ["_Route9CooltrainerM1EndBattleText"] = "Spento\ncome una lampadina!",
  ["_Route9CooltrainerM2AfterBattleText"] = "Vai alla GROTTA DIGLETT\nanche tu?",
  ["_Route9CooltrainerM2BattleText"] = "Prendo la GROTTA DIGLETT\nper andare a\11LAVANDULA...",
  ["_Route9CooltrainerM2EndBattleText"] = "Non sono\nall'altezza!",
  ["_Route9Hiker1AfterBattleText"] = "Hai avuto fegato\na venirmi contro,\11eh?",
  ["_Route9Hiker1BattleText"] = "Bwahaha!\nOttimo! Mi annoiavo,\11eh!",
  ["_Route9Hiker1EndBattleText"] = "Vieni pure,\neh!\12Oh aspetta. Non\nho piu' POKéMON!",
  ["_Route9Hiker2AfterBattleText"] = "Hahaha! I ragazzi\ndevono essere tosti!",
  ["_Route9Hiker2BattleText"] = "Hahaha!\nNon sei un bel\11peperino!",
  ["_Route9Hiker2EndBattleText"] = "Che\ncos'é?",
  ["_Route9Hiker3AfterBattleText"] = "Hahahaha!\nNoi tipacci ridiamo\11sempre!",
  ["_Route9Hiker3BattleText"] = "Hahahaha!\nForza, amico!",
  ["_Route9Hiker3EndBattleText"] = "Hahahaha!\nMi hai battuto lealmente!",
  ["_Route9SignText"] = "PERCORSO 9\nCERULOPOLI -\11GROTTA DIGLETT",
  ["_Route9Youngster1AfterBattleText"] = "Devo raccogliere\npiu' di qualche\11insetto per fortificarmi...",
  ["_Route9Youngster1BattleText"] = "Mi alzo presto ogni\ngiorno per far\11crescere i POKéMON\11dai bozzoli!",
  ["_Route9Youngster1EndBattleText"] = "COSA?\12Che totale\nperdita di tempo!",
  ["_Route9Youngster2AfterBattleText"] = "Se non ti piacciono\ni POKéMON insetto,\11mi stai antipatico!",
  ["_Route9Youngster2BattleText"] = "Vai, mio super\nPOKéMON insetto!",
  ["_Route9Youngster2EndBattleText"] = "I miei\ninsetti...",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "Hai ferito il mio\npovero POKéMON!\12Prendo a pretese\nche tu lo curi in\11un CENTRO POKéMON!",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "Ho raccolto questi\nPOKéMON in tutto\11il mondo!",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "Oh no!\nHo girato il mondo\11per trovarli!",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "Dovresti essere\ngentile con gli amici!",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "Viaggio da solo nei\nmiei viaggi!\12I POKéMON sono i\nmiei unici amici!",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "I miei,\nmiei amici...",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "Voglio essere\nlasciato solo! Fuori!",
  ["_Route6CooltrainerM2BattleText"] = "Tu, marmocchio!\nCome osi irrompere!",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "Uhm!\nBimbo maleducato!",
  ["_SSAnne1FRoomsGentleman3Text"] = "Ssh! Sono un\nagente di POLIZIA!\12Sulle tracce del\nTEAM ROCKET!",
  ["_SSAnne1FRoomsGirl1Text"] = "Cameriere, vorrei\nuna torta di ciliegie,\11per favore!",
  ["_SSAnne1FRoomsGirl2Text"] = "Facciamo una crociera\nintorno al mondo.",
  ["_SSAnne1FRoomsLittleGirlText"] = "Viaggio sempre\ncon WIGGLYTUFF!",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "Una crociera é\nelegante ma accogliente!",
  ["_SSAnne1FRoomsWigglytuffText"] = "WIGGLYTUFF: Puup\npupuu!",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Diventiamo amici, OK?\12Cosi' potremo scambiare\nPOKéMON!",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "Adoro i POKéMON!\nE tu?",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "Wow!\nSei fantastico!",
  ["_SSAnne1FSailorText"] = "I passeggeri sono\nagitati!\12Potresti essere sfidato\ndai piu' annoiati!",
  ["_SSAnne1FWaiterText"] = "Bonjour!\nSono il cameriere\11di questa nave!\12Saro' felice di\nservirti qualsiasi\11cosa desideri!\12Ah! Il tipo forte\ne silenzioso!",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Ho sentito\nche a bordo c'era\11un esperto di TAGLIO.\12Ma era solo un\nvecchio mal di mare!\12Comunque TAGLIO é\nmolto utile!\12Dovresti andare a\nvederlo! Ci si vede!",
  ["_SSAnne2FRivalDefeatedText"] = "Uhm!\12Almeno stai\nallevando i tuoi\11POKéMON!",
  ["_SSAnne2FRivalText"] = "{RIVAL}: Bonjour!\n{PLAYER}!\12Che sorpresa\nvederti qui!\12{PLAYER}, sei stato\ninvitato davvero?\12Come va col tuo\nPOKéDEX?\12Io ne ho gia' presi\n40 tipi, amico!\12Ce ne sono di\nogni tipo ovunque!\12Cerca nelle zone\nerbose!",
  ["_SSAnne2FRivalVictoryText"] = "{PLAYER}! Che hai,\nil mal di mare?\12Dovresti darti\nuna mossa, amico!",
  ["_SSAnne2FRoomsBeautyText"] = "Sento che molta\ngente ha il mal di mare!",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "Il CAPITANO sembrava\nmolto malato e\11pallido!",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "Oh, adoro i tuoi\nforti POKéMON!",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Non ti ho mai\nvisto alla festa.",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "Prendila\ncon filosofia!",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "La festa?\12La festa sulla nave\ndovrebbe essere\11finita ormai.",
  ["_SSAnne2FRoomsFisherBattleText"] = "Guarda che cosa\nho pescato!",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "Ho finito\nle scorte!",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "15 anni fa avrei\nvinto di sicuro!",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "Gareggiare con i\ngiovani mi mantiene\11giovanile.",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "Bella lotta!\nAh, mi sento di\11nuovo giovane!",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "Preferisco POKéMON\nforti e rari.",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "Quale preferisci,\nun POKéMON forte o\11raro?",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "Devo\nsalutarti!",
  ["_SSAnne2FRoomsGentleman3Text"] = "In tutti i miei\nviaggi non ho mai\11visto un POKéMON\11dormire cosi'!\12Era qualcosa di\nsimile!",
  ["_SSAnne2FRoomsGentleman4Text"] = "Ah si', ho visto\nalcuni POKéMON\n traghettare la\11 gente sull'acqua!",
  ["_SSAnne2FRoomsGentleman5Text"] = "Sei stato alla\nZONA SAFARI a\11FUCSIAPOLI?\12C'erano tanti tipi\nrarissimi di POKéMON!!",
  ["_SSAnne2FRoomsGrampsText"] = "I POKéMON possono\nTAGLIARE piccoli arbusti.",
  ["_SSAnne2FRoomsLittleBoyText"] = "Io e il mio babbo\npensiamo che la ZONA\11SAFARI sia magnifica!",
  ["_SSAnne2FWaiterText"] = "Questa nave é una\nnave di lusso per\11allenatori!\12A ogni porto facciamo\nfeste con invitati!",
  ["_SSAnne3FSailorText"] = "Il nostro CAPITANO\né un maestro di\11spada! Insegna\11anche TAGLIO ai POKéMON!",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "Volevo fare anche\nte mio assistente!",
  ["_SSAnneB1FRoomsFisherBattleText"] = "Salve straniero!\nFermati a chiacchierare!\12Tutti i miei POKéMON\nprovengono dal mare!",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "Acciderboli!\nQuello mi é scappato!",
  ["_SSAnneB1FRoomsMachokeText"] = "MACHOKE: Gwoh!\nGoggoh!",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "Haha! Vuoi fare\nil marinaio, compagno?",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "Sai cosa dicono\nsu marinai e lotte!",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "Esatto!\nBel match, compagno!",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "Hai visto il GURU\nPESCATORE a\11VERMIGLIA?",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "Il mio orgoglio di\nmarinaio é in gioco!",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "Il tuo spirito\nmi ha affondato!",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "Abbiamo preso tutti\ni POKéMON mentre\11eravamo in mare!",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "Anche noi marinai\nabbiamo POKéMON!",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "OK, non\nte la cavi male.",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "I POKéMON marini\nvivono in acque\11profonde. Ti serve\11un AMO!",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "Mi piacciono i\npivelli vispi come te!",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "Argh!\nPerso!",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "A volte qualche\nmedusa alla deriva\11finisce sulla nave.",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "Compagno, camminerai\ncon l'asse se\11perdi!",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "Argh!\nBattuto da un ragazzino!",
  ["_SSAnneB1FRoomsSuperNerdText"] = "Il mio amico MACHOKE\né fortissimo!\12Ha abbastanza FORZA\nper spostare grandi\11massi!",
  ["_SSAnneBowCooltrainerMText"] = "Urf. Sto male.\nSono uscito a\11prendere aria.",
  ["_SSAnneBowSailor1Text"] = "Scrofare i ponti é\nun lavoro duro!",
  ["_SSAnneBowSailor2AfterBattleText"] = "Quanti tipi di POKéMON\ncrediti che ci siano\11in tutto?",
  ["_SSAnneBowSailor2BattleText"] = "Ehi compagno!\nFacciamo un saltello!",
  ["_SSAnneBowSailor2EndBattleText"] = "Sei\nimpressionante!",
  ["_SSAnneBowSailor3AfterBattleText"] = "Mio padre ha detto\nche ci sono 100 tipi\11di POKéMON. Secondo\11me ce ne sono di piu'.",
  ["_SSAnneBowSailor3BattleText"] = "Ahoi la'!\nHai il mal di mare?",
  ["_SSAnneBowSailor3EndBattleText"] = "Sono stato\nsolo distratto!",
  ["_SSAnneBowSuperNerdText"] = "La festa é finita.\nLa nave partira'\11presto.",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "Oh no! Non hai\nabbastanza spazio!",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "CAPITANO: Uff!\nGrazie! Sto molto\11meglio!\12Vuoi vedere la mia\ntecnica TAGLIO?\12Te la mostrerei se\nnon stessi male...\12Lo so! Prendi\nquesta!\12Insegnala ai tuoi\nPOKéMON e potrai\11TAGLIARE ogni volta!",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "CAPITANO: Uff!\12Ora che non sto\npiu' male, credo sia\11l'ora.",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "CAPITANO: Ooargh...\nChe schifo...\11Urrp! Mal di mare...\12{PLAYER} ha strofinato\nla schiena del\11CAPITANO!\12Strofina-strofina...\nStrofina-strofina...",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "Come sconfiggere il\nmal di mare...\11Il CAPITANO sta\11leggendo questo!",
  ["_SSAnneCaptainsRoomTrashText"] = "Che schifo!\nNon avrei dovuto guardare!",
  ["_SSAnneKitchenCook1Text"] = "Tu, mon petit!\nSiamo occupati qui!\11Fuori dai piedi!",
  ["_Route6KitchenCook2Text"] = "Ho visto una strana\npalla nella spazzatura.",
  ["_SSAnneKitchenCook3Text"] = "Sono cosi' occupato\nche ho le vertigini!",
  ["_SSAnneKitchenCook4Text"] = "Um-de-hum-de-\nho...\12Sbuccio patate\ntutti i giorni!\11Um-hum...",
  ["_SSAnneKitchenCook5Text"] = "Hai saputo di\nSNORLAX?\12Fa solo una vita a\nmangiare e dormire!",
  ["_SSAnneKitchenCook6Text"] = "Piagnuc... Sniff...\12Devo solo pelare\ncipolle...\11Piagnuc...",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "Ehm-ehm! Certo che\nsono lo CHEF!\12La portata principale é",
  ["_SSTicketNoRoomText"] = "Hai troppa roba,\namico!",
  ["_SSTicketReceivedText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",







["_SafariZoneAngryText"] = "Il {RAM:wEnemyMonNick}\nselvaggio é arrabbiato!",
  ["_SafariZoneCenterRestHouseGirlText"] = "SARA: Dove sara'\nandato il mio\11ragazzo ERIK?",
  ["_SafariZoneCenterRestHouseScientistText"] = "Sto catturando\nPOKéMON da portare\11a casa come regali!",
  ["_SafariZoneCenterRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneCenterTrainerTipsSignText"] = "CONSIGLI UTILI\12Premi il Pulsante\nSTART per vedere\11il tempo residuo!",
  ["_SafariZoneEastRestHouseRockerText"] = "Ho catturato un\nCHANSEY!\12Ne é valsa\nla pena!",
  ["_SafariZoneEastRestHouseScientistText"] = "Quanti ne hai\ncatturati? Sono\11distrutto dal lavoro!",
  ["_SafariZoneEastRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneEastRestHouseSilphWorkerMText"] = "Uff! Sono stanco\ndi tutto questo svago!",
  ["_SafariZoneEastSignText"] = "AREA CENTRALE\nNORD: AREA 2",
  ["_SafariZoneEastTrainerTipsText"] = "CONSIGLI UTILI\12Il tempo rimasto\ndiminuisce solo\11mentre cammini!",
  ["_SafariZoneEatingText"] = "Il {RAM:wEnemyMonNick}\nselvaggio sta mangiando!",
  ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "\12Ti chiameremo con\nl'altoparlante se\11finisce il tempo o\11le SAFARI BALL!",
  ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "é stato un buon\nbottino?\11Torna a trovarci!",
  ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "Buona fortuna!",
  ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "Te ne vai gia'?",
  ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "Ops! Non hai\nabbastanza soldi!",
  ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "OK! Torna a\ntrovarci presto!",
  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Restituisci le\nSAFARI BALL\11che ti sono rimaste.",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "Benvenuto nella\nZONA SAFARI!",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "Costano 500\nPokémon-dollari!\12Qui usiamo solo\nSAFARI BALL.\12{PLAYER} riceve\n30 SAFARI BALL!",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "Per soli 500\nPokémon-dollari\11puoi catturare tutti\11i POKéMON che vuoi!\12Vuoi partecipare\nalla caccia?",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "Ciao! é la tua\nprima volta qui?",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "La ZONA SAFARI ha\n4 zone diverse.\12In ogni zona ci sono\nPOKéMON differenti.\11Usate le SAFARI\11BALL per catturarli!\12Se finiscono tempo\no SAFARI BALL,\11la partita é finita!\12Prima di partire,\napri un POKéMON BOX\11vuoto per fare\11spazio ai nuovi!",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "Spiacente, tu sei\nun cliente abituale!",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "Il mio EEVEE si é\nevoluto in FLAREON!\12Ma quello di un\namico é diventato\11un VAPOREON!\11Chissa' perché?",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Vai nella parte\npiu' profonda della\11ZONA SAFARI. Vinci-\11rai un premio!",
  ["_SafariZoneNorthRestHouseScientistText"] = "Puoi tenere ogni\noggetto trovato\11per terra qui.\12Ma finira' il tempo\nse provi a prender-\11li tutti insieme!",
  ["_SafariZoneNorthRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneNorthSignText"] = "AREA 2",
  ["_SafariZoneNorthTrainerTips1Text"] = "CONSIGLI UTILI\12La CASA SEGRETA\né ancora piu' avanti!",
  ["_SafariZoneNorthTrainerTips2Text"] = "CONSIGLI UTILI\12I POKéMON si\nnascondono nell'erba!\12Cammina a zig-zag\nnell'erba alta per\11farli uscire.",
  ["_SafariZoneNorthTrainerTips3Text"] = "CONSIGLI UTILI\12Vinci una MN gratis\ntrovando la\11CASA SEGRETA!",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "La MN03 é SURF!\12I POKéMON potranno\ntraghettarti\11sull'acqua!\12Questa MN non si\n rompe! Puoi usarla\11tutte le volte che\11vuoi!\12Sei fortunatissimo\na vincere questo\11favoloso premio!",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "Non hai abbastanza\nspazio per questo\11favoloso premio!",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "Ah! Finalmente!\12Sei il primo ad\narrivare alla\11CASA SEGRETA!\12Temevo che nessuno\ncirca avrebbe vinto\11il nostro premio.\12Congratulazioni!\nHai vinto!",
  ["_SafariZoneWestFindWardensTeethSignText"] = "AVVISO RICHIESTA\12Cercate i DENTI\nD'ORO smarriti dal\11GUARDIANO SAFARI.\11Devono essere da\11queste parti.\12Ricompensa offerta!\nContattare: GUARDIA",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "Usare l'ESCA\nrende i POKéMON\11piu' facili da pigliare.",
  ["_SafariZoneWestRestHouseScientistText"] = "Lanciare SASSI ai\nPOKéMON li fa\11scappare, ma sono\11piu' facili da\11catturare.",
  ["_SafariZoneWestRestHouseSignText"] = "AREA DI RIPOSO",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "Ho camminato molto,\nma non ho visto\11POKéMON che volevo.",
  ["_SafariZoneWestSignText"] = "AREA 3\nEST: AREA CENTRALE",
  ["_SafariZoneWestTrainerTipsText"] = "CONSIGLI UTILI\12Campagna esplo-\nrazione zone!\12Alla ricerca della\nCASA SEGRETA!",
  ["_SaffronCityFightingDojoSignText"] = "DOJO LOTTA",
  ["_SaffronCityGentlemanText"] = "Sono volato qui\ncol mio PIDGEOT\11leggendo della SILPH.\12é gia' finita?\nMi sono perso\11tutta la cronaca.",
  ["_SaffronCityGymSignText"] = "PALESTRA POKéMON\ndi ZAFFERANOPOLI\11CAPOPALESTRA: SABRINA\12Maestra dei\nPOKéMON psico!",
  ["_SaffronCityMrPsychicsHouseSignText"] = "CASA DEL\nSIG. PSI",
  ["_SaffronCityPidgeotText"] = "PIDGEOT: Bi bibii!",
  ["_SaffronCityPokecenterGuyText1"] = "Sarebbe bello se\ni SUPERQUATTRO\11venissero a dare\11una lezione al\11TEAM ROCKET!",
  ["_SaffronCityPokecenterGuyText2"] = "Il TEAM ROCKET é\nscomparso! Possiamo\11uscire in sicurezza!\12Fantastico!",
  ["_SaffronCityRockerText"] = "Ho visto il CAPO\ndel ROCKET scappare\11dall'edificio SILPH.",
  ["_SaffronCityRocket1Text"] = "Che vuoi?\nSparisci!",
  ["_SaffronCityRocket2Text"] = "Il CAPO ha detto\nche prendera'\11questa citta'!",
  ["_SaffronCityRocket3Text"] = "Togliti di mezzo!",
  ["_SaffronCityRocket4Text"] = "ZAFFERANOPOLI\nappartiene al\11TEAM ROCKET!",
  ["_SaffronCityRocket5Text"] = "Essere malvagi\nmi fa sentire vivo!",
  ["_SaffronCityRocket6Text"] = "Ahi! Guarda dove\nmetti i piedi!",
  ["_SaffronCityRocket7Text"] = "Con la SILPH sotto\ncontrollo, possia-\11mo sfruttare i\11POKéMON del mondo!",
  ["_SaffronCityRocket8Text"] = "Sono una guardia.\nNon lascio pas-\11sare bambini",
  ["_SaffronCityRocket9Text"] = "...\nRonf...\12Ha! Si sta\nfacendo un pisolino!",
  ["_SaffronCityScientistText"] = "Hai battuto il\nTEAM ROCKET da\11solo? Incredibile!",
  ["_SaffronCitySignText"] = "ZAFFERANOPOLI\nSplendente e d'oro\11Terra del Commercio",
  ["_SaffronCitySilphCoLatestProductSignText"] = "L'ultimo prodotto\ndella SILPH!\12Uscita da\ndefinire...",
  ["_SaffronCitySilphCoSignText"] = "SOCIETA' SILPH\nEDIFICIO UFFICI",
  ["_SaffronCitySilphWorkerFText"] = "La gente dovrebbe\ntornare a frotte\11a ZAFFERANOPOLI ora.",
  ["_SaffronCitySilphWorkerMText"] = "Si'! Il TEAM ROCKET\né andato via!\11é sicuro uscire\11di nuovo!",
  ["_SaffronCityTrainerTips1Text"] = "CONSIGLI UTILI\12TOTALCURA cura\ntutti i problemi\11come sonno e ustioni.\12Costa un po' di piu',\nma é molto\11piu' comodo.",
  ["_SaffronCityTrainerTips2Text"] = "CONSIGLI UTILI\12Le nuove SUPER\nBALL offrono una\11miglior cattura.\12Provale su quei\nPOKéMON difficili\11da catturare.",
  ["_SaffronGateGuardGeeImThirstyText"] = "Sono di guardia.\nUffa, ho una sete!\12Aspetta un attimo,\nla strada é chiusa.",
  ["_SaffronGateGuardImParchedText"] = "Ehi, ragazzo!\nHo la gola secca!\12...\11Eh? Posso bere\11questa bibita?\11Oh, grazie!",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "Ciao, grazie per\nle bevande fresche!",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "\12...\nGlub glub...\11...\11Gulp...\11Se vuoi andare a\11ZAFFERANOPOLI...\11...\11Puoi passare.\nLo condividero' con\11le altre guardie!",
  ["_SaffronGymChanneler1AfterBattleText"] = "In una lotta tra\nuguali, vince chi\11ha la volonta' piu'\11forte!\12Se vuoi battere\nSABRINA, pensa\11solo a vincere!",
  ["_SaffronGymChanneler1BattleText"] = "SABRINA é piu'\ngiovane di me,\11ma la rispetto!",
  ["_SaffronGymChanneler1EndBattleText"] = "Non\nbasta!",
  ["_SaffronGymChanneler2AfterBattleText"] = "Devo insegnare\ntecniche migliori\11ai miei POKéMON!",
  ["_SaffronGymChanneler2BattleText"] = "I POKéMON assomi-\ngliono ai propri\11allenatori.\12I tuoi POKéMON\ndevono essere tosti!",
  ["_SaffronGymChanneler2EndBattleText"] = "Lo\nsapevo!",
  ["_SaffronGymChanneler3AfterBattleText"] = "Sapevo che\nsarebbe successo\11tutto questo.",
  ["_SaffronGymChanneler3BattleText"] = "Io e te, i nostri\nPOKéMON lotteranno!",
  ["_SaffronGymChanneler3EndBattleText"] = "Ho perso\nal termine!",
  ["_SaffronGymGuideBeatSabrinaText"] = "Poteri psichici,\neh?\12Se li avessi io,\nfarei un sacco\11di soldi alle slot!",
  ["_SaffronGymGuideChampInMakingText"] = "Ehila'! Campione!\12I POKéMON di\nSABRINA usano la\11mente anziché la\11forza!\12I POKéMON Lotta\nsono deboli contro\11i POKéMON psico!\12Vengono stesi\nprima di poter\11sferrare un pugno!",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "La MEDAGLIA PALUDE\nubbidisce ai POKéMON\11fino al Lv 70!\12I POKéMON piu' forti\ndiventano selvaggi\11e ti ignorano!\12Non far crescere\ntroppo i tuoi\11POKéMON!\12Aspetta, prendi\nquesta MT!",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "Ognuno ha poteri\npsichici!\12La gente non se\nne rende conto!",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "Sono\nscioccata!\12Ma una sconfitta\né una sconfitta.\12Ammetto di non\naver studiato abbastanza!\12Hai vinto la\nMEDAGLIA PALUDE!",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER} riceve\nla MT46!",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "Il tuo zaino é\ncormo di roba!",
  ["_SaffronGymSabrinaText"] = "Avevo previsto\nla tua venuta!\12Ho poteri psichici\nda quando ero\11piccola.\12Ho iniziato piegando\ni cucchiai con\11la mente.\12Odio lottare, ma\nse lo desideri,\nti mostrero' i poteri!",
  ["_SaffronGymYoungster1AfterBattleText"] = "I POKéMON psico\ntemono solo spettri\11e insetti!",
  ["_SaffronGymYoungster1BattleText"] = "Il nostro potere\ninvisibile ti spaventa?",
  ["_SaffronGymYoungster1EndBattleText"] = "Non\nl'avevo previsto!",
  ["_SaffronGymYoungster2AfterBattleText"] = "SABRINA ha appena\nsteso il MAESTRO DI\11KARATE qui accanto!",
  ["_SaffronGymYoungster2BattleText"] = "Sai che la forza\nnuda e cruda non\11basta!",
  ["_SaffronGymYoungster2EndBattleText"] = "Non ci\nposso credere!",
  ["_SaffronGymYoungster3AfterBattleText"] = "C'erano 2 palestre\nPOKéMON a ZAFFERANOPOLI.\12Il DOJO qui vicino\nha perso lo status\11quando li abbiamo\11stroncati!",
  ["_SaffronGymYoungster3BattleText"] = "SABRINA é giovane,\nma é anche la\11nostra CAPO!\12Non arriverai a\nlei facilmente!",
  ["_SaffronGymYoungster3EndBattleText"] = "Ho perso\nla concentrazione!",
  ["_SaffronGymYoungster4AfterBattleText"] = "Esatto! Ho usato\nla telepatia per\11leggerti la mente!",
  ["_SaffronGymYoungster4BattleText"] = "La palestra di\nZAFFERANOPOLI é famosa\11per i suoi psico!\12Vuoi vedere SABRINA!\11Lo so!",
  ["_SaffronGymYoungster4EndBattleText"] = "Arrrgh!",
  ["_SaffronMartCooltrainerFText"] = "IL RIVITALIZZA é\ncostoso, ma rimette\11in sesto i POKéMON!",
  ["_SaffronMartSuperNerdText"] = "Il REPELL MAX dura\npiu' del SUPER REP\11per tenere lontani\11i POKéMON piu'\11deboli!",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "Grazie per aver\nscritto. Spero di\11vederti presto!\12Ehi! Non guardare\nla mia lettera!",
  ["_SaffronPidgeyHousePaperText"] = "Mi hanno regalato\nuna PROTEINA.\12Serve per aumen-\ntare la potenza\11delle mosse!",
  ["_SaffronPidgeyHousePidgeyText"] = "PIDGEY: Kurukkoo!",
  ["_SaffronPidgeyHouseYoungsterText"] = "La COPIONA é carina!\nLe compro una\11BAMBOLA POKé!",
  ["_SaffronPokecenterBeautyText"] = "I tassi di cresci-\nta dei POKéMON\11variano da specie\11a specie.",
  ["_SaffronPokecenterGentlemanText"] = "La SILPH é molto\nfamosa. Ecco perché\11ha attirato il\11TEAM ROCKET!",
  ["_SandshrewDexEntry"] = "Si scava una tana\nprofonda\nsottoterra in zone\12aride lontano\ndall'acqua. Emerge\nsolo per cercare\12cibo.",
  ["_SandslashDexEntry"] = "Si appallottola in\nuna sfera spinosa\nse minacciato.\12Puo' rotolare da\nappallottolato per\nattaccare o\12fuggire.",
  ["_SaveOptionText"] = "L'opzione SALVA\né nel MENU.",
  ["_SavingEnergyText"] = "{USER}\nsta accumulando\nenergia!",
  ["_ScaredText"] = "{RAM:wBattleMonNick} ha\ntroppa paura per\nmuoversi!",
  ["_ScytherDexEntry"] = "Con agilita' e\nvelocita' da\nninja, puo' creare\12l'illusione che ce\nne sia piu' di\nuno.",
  ["_SeadraDexEntry"] = "Capace di nuotare\nall'indietro\nbattendo\12rapidamente le\npinne pettorali\nsimili a ali e la\12robusta coda.",
  ["_SeafoamIslandsB4FArticunoBattleText"] = "Gyaoo!",
  ["_SeafoamIslandsB4FBouldersSignText"] = "I massi potreb-\nbero deviare\11il flusso d'acqua!",
  ["_SeafoamIslandsB4FDangerSignText"] = "PERICOLO\nCorrente forte!",
  ["_SeakingDexEntry"] = "Nella stagione\ndella deposizione,\nsi possono vedere\12mentre risalgono\npotentemente fiumi\ne torrenti.",
  ["_SeelDexEntry"] = "Il corno sporgente\nsulla testa é\nmolto duro. Viene\12usato per sfondare\nil ghiacchio\nspesso.",
  ["_SentToBoxText"] = "Non c'é piu'\nposto per i POKéMON!\11{RAM:wBoxMonNicks} é\11stato spedito al\11BOX POKéMON\11{RAM:wStringBuffer} sul PC!",
  ["_ShallWeHealYourPokemonText"] = "Vuoi curare i\ntuoi POKéMON?",
  ["_ShellderDexEntry"] = "Il suo guscio duro\nrespinge ogni tipo\ndi attacco. é\12vulnerabile solo\nquando il guscio é\naperto.",
  ["_ShroudedInMistText"] = "{USER}\né avvolto nella\nnebbia!",
  ["_SilphCo10FGiovanniILostAgainText"] = "Arrgh!!\nHo perso di nuovo!?",
  ["_SilphCo10FPorygonText"] = "Il monitor ha\nun POKéMON sopra!",
  ["_SilphCo10FRocketAfterBattleText"] = "Bel tentativo,\nma la sala riunio-\11ni é un piano su!",
  ["_SilphCo10FRocketBattleText"] = "Benvenuto al 10° piano!\nChe piacere averti\11qui con me!",
  ["_SilphCo10FRocketEndBattleText"] = "Sono\nstupito!",
  ["_SilphCo10FScientistAfterBattleText"] = "Sei soddisfatto\ndi avermi battuto?\11Allora torna a casa!",
  ["_SilphCo10FScientistBattleText"] = "Basta con questi\ngiochi sciocchi!",
  ["_SilphCo10FScientistEndBattleText"] = "Nessun\ncontinua rimasto!",
  ["_SilphCo10FSilphWorkerFImScaredText"] = "Waaaaa!\11Ho paura!",
  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "Ti prego, sta' zitto\nsul mio pianto!",
  ["_SilphCo11FBeautyText"] = "SEGRETARIA: Grazie\nper averci liberato\11tutti!\12Ammiriamo molto\nil tuo coraggio.",
  ["_SilphCo11FGiovanniText"] = "Ah {PLAYER}!\nCi rincontriamo!\12Il PRESIDENTE ed\nio stiamo parlando\11di affari.\11Non ficcare il naso\11nelle cose dei grandi...\11O proverai il dolore!",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "Accidenti!\nHai rovinato i\11nostri piani SILPH!\12Ma il TEAM ROCKET\nnon cadra' mai!\12{PLAYER}! Ricorda\nche i POKéMON sono\11del TEAM ROCKET!\12Devo andare, ma\ntornero'!",
  ["_SilphCo11FRocket1AfterBattleText"] = "Vuoi vedere il\nmio CAPO, eh?",
  ["_SilphCo11FRocket1BattleText"] = "Fermati li'!\nNon muoverti!",
  ["_SilphCo11FRocket1EndBattleText"] = "Non...\nTi prego!",
  ["_SilphCo11FRocket2AfterBattleText"] = "Attento, al mio\nCAPO piacciono i\11POKéMON tosti!",
  ["_SilphCo11FRocket2BattleText"] = "Alt! Hai un appun-\ntamento col CAPO?",
  ["_SilphCo11FRocket2EndBattleText"] = "Gaah!\nDistrutto!",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PRESIDENTE: Non\npuoi comprarla\11da nessuna parte!\12é la nostra\nMASTER BALL segreta!\12Catturera' qual-\nsiasi POKéMON\11senza fallire!\12Pero' tieni il\nsegreto sull'uso.",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "Non hai posto\nper questo.",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SilphCo11FSilphPresidentText"] = "PRESIDENTE: Grazie\nper aver salvato\11la SILPH!\12Non dimentichero'\nche ci hai salvati\11nel pericolo!\12Devo ringraziarti\nin qualche modo!\12Essendo ricco,\nposso darti tutto!\12Ecco, forse questo\nandra' bene!",
  ["_SilphCo1FLinkReceptionistText"] = "Benvenuto!\12Il PRESIDENTE é\nall'11° piano nella sala\11riunioni!",
  ["_SilphCo2FRocket1AfterBattleText"] = "Le piastrelle a\nforma di rombo\11sono teletrasporti!\11Sono hi-tech!",
  ["_SilphCo2FRocket1BattleText"] = "I bambini non\npossono entrare!",
  ["_SilphCo2FRocket1EndBattleText"] = "Duro!",
  ["_SilphCo2FRocket2AfterBattleText"] = "La SILPH si unire-\nra' al TEAM ROCKET!",
  ["_SilphCo2FRocket2BattleText"] = "Ehi tu! Che\nfai qui?",
  ["_SilphCo2FRocket2EndBattleText"] = "Ho toppato!",
  ["_SilphCo2FScientist1AfterBattleText"] = "Lavoro per SILPH\ne TEAM ROCKET!",
  ["_SilphCo2FScientist1BattleText"] = "Aiuto! Lavoro\nalla SILPH.",
  ["_SilphCo2FScientist1EndBattleText"] = "Come\nfacevi a sapere\11che ero ROCKET?",
  ["_SilphCo2FScientist2AfterBattleText"] = "Sai risolvere il\nlabirinto qui?",
  ["_SilphCo2FScientist2BattleText"] = "Zona vietata!\nVai a casa!",
  ["_SilphCo2FScientist2EndBattleText"] = "Sei\nbravo.",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "La MT36 é AUTODISTRUZIONE!\12é forte, ma il\nPOKéMON va K.O.!\11Fai attenzione.",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "Non hai abbastanza\nspazio per questo.",
  ["_SilphCo3FRocketAfterBattleText"] = "Un indizio? Puoi\naprire le porte\11con una SCHEDA!",
  ["_SilphCo3FRocketBattleText"] = "Smetti di darci\nfastidio, moccioso!",
  ["_SilphCo3FRocketEndBattleText"] = "Mi\narrendo!",
  ["_SilphCo3FScientistAfterBattleText"] = "Uhm...\12Il TEAM ROCKET\nha detto che mi\11avrebbe fatto stu-\ndiare i POKéMON!",
  ["_SilphCo3FScientistBattleText"] = "Sostengo il TEAM\nROCKET piu' della\11stessa SILPH!",
  ["_SilphCo3FScientistEndBattleText"] = "Mi hai\nproprio preso!",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Lavoro alla SILPH.\nChe devo fare?",
  ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "{PLAYER}! Tu e i\ntuoi POKéMON ci\11avete salvati!",
  ["_SilphCo4FRocket1AfterBattleText"] = "Fwahahaha!\nIl mio CAPO punta\11questo posto!",
  ["_SilphCo4FRocket1BattleText"] = "Il TEAM ROCKET ha\npreso il comando\11della SILPH S.P.A.!",
  ["_SilphCo4FRocket1EndBattleText"] = "Arrgh!",
  ["_SilphCo4FRocket2AfterBattleText"] = "Meglio avvisare\nil CAPO all'11° piano!",
  ["_SilphCo4FRocket2BattleText"] = "Intruso avvistato!",
  ["_SilphCo4FRocket2EndBattleText"] = "Tu\nchi sei?",
  ["_SilphCo4FScientistAfterBattleText"] = "Le porte sono\nchiuse! Una SCHEDA\11le apre!",
  ["_SilphCo4FScientistBattleText"] = "I miei POKéMON\nsono i miei leali\11soldati!",
  ["_SilphCo4FScientistEndBattleText"] = "Accidenti!\nChe POKéMON deboli!",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "Sssh! Non vedi\nche mi nascondo?",
  ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "Eh? Il TEAM\nROCKET é sparito?",
  ["_SilphCo5FPokemonReport1Text"] = "é un RAPPORTO!\nIL LABORATORIO ha\11creato PORYGON, il\11primo POKéMON\11virtuale.",
  ["_SilphCo5FPokemonReport2Text"] = "é un RAPPORTO!\nOltre 160 mosse\11POKéMON sono\11state confermate.",
  ["_SilphCo5FPokemonReport3Text"] = "é un RAPPORTO!\n4 POKéMON si\11evolvono solo con\11lo scambio tramite cavo Link.",
  ["_SilphCo5FRockerAfterBattleText"] = "Sei solo al 5° piano.\nLa strada per il\11CAPO é lunga!",
  ["_SilphCo5FRockerBattleText"] = "Cosa? Non dovrebbero\nesserci bambini!",
  ["_SilphCo5FRockerEndBattleText"] = "Oh\ncielo!",
  ["_SilphCo5FRocket1AfterBattleText"] = "Non é saggio\nattaccare briga\11col TEAM ROCKET!",
  ["_SilphCo5FRocket1BattleText"] = "Ho sentito che un\nbimbo gironzola.",
  ["_SilphCo5FRocket1EndBattleText"] = "Boom!",
  ["_SilphCo5FRocket2AfterBattleText"] = "A proposito.\nKOFFING si evolve\11in WEEZING!",
  ["_SilphCo5FRocket2BattleText"] = "Rispetta un\npo' il TEAM ROCKET!",
  ["_SilphCo5FRocket2EndBattleText"] = "Cof...\nCof...",
  ["_SilphCo5FScientistAfterBattleText"] = "Lavoravamo alla\nsuper POKé BALL\11che catturava\11qualsiasi cosa!",
  ["_SilphCo5FScientistBattleText"] = "Studiamo le POKé\nBALL su questo\11piano!",
  ["_SilphCo5FScientistEndBattleText"] = "Accidenti!\nDannazione!",
  ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "Il TEAM ROCKET é\nin subbuglio per un\11intruso. Sei tu?",
  ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "Il TEAM ROCKET é\nfuggito! Sei il\11nostro eroe!",
  ["_SilphCo6FRocket1AfterBattleText"] = "Non importa!\nI miei fratelli\11mi vendicheranno!",
  ["_SilphCo6FRocket1BattleText"] = "Sono uno dei 4\nFRATELLI ROCKET!",
  ["_SilphCo6FRocket1EndBattleText"] = "Fiamma\nspenta!",
  ["_SilphCo6FRocket2AfterBattleText"] = "Chi sta con la\ngiustizia, tradisce\11il male!",
  ["_SilphCo6FRocket2BattleText"] = "Osi tradire il\nTEAM ROCKET?",
  ["_SilphCo6FRocket2EndBattleText"] = "Tradit-\ntore!",
  ["_SilphCo6FScientistAfterBattleText"] = "FILIALE ESTERNA?\né in una zona\11davvero remota!",
  ["_SilphCo6FScientistBattleText"] = "Quel marrano del\nPRESIDENTE!\12Non doveva man-\ndarmi in questa\11filiale sperduta!",
  ["_SilphCo6FScientistEndBattleText"] = "Accidenti!",
  ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "Mi dispiace tanto\nper lui, lo devo\11sposare!",
  ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "Guardalo! é un\nvero codardo!",
  ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "Il TEAM ROCKET\nvuole conquistare\11il mondo coi\11POKéMON!",
  ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "Il TEAM ROCKET\né fuggito per colpa\11tua!",
  ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "Bene, é ora di\ntornare al lavoro!",
  ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "I ROCKET sono\nvenuti a occupare\11l'edificio!",
  ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "Avranno preso di\nmira la SILPH per\11i nostri prodotti.",
  ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "Vieni a lavorare\nalla SILPH quando\11sarai grande!",
  ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "Mio Dio, aiuto!\nAiutami ti prego!",
  ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "Ci siamo fidanzati!\nEheheh!",
  ["_SilphCo7FRivalDefeatedText"] = "Oh ho!\nSei pronto per\11il CAPO ROCKET!",
  ["_SilphCo7FRivalGoodLuckToYouText"] = "Beh, {PLAYER}!\12Vado avanti e\nsopra!\12Guardando il mio\nPOKéDEX capisco\11chi é forte e\11come si evolvono!\12Vado alla LEGA\nPOKéMON a cacciare\11i SUPERQUATTRO!\12Diventero' il piu'\nforte allenatore!\12{PLAYER}, buona\nfortuna!\11Ci si vede!",
  ["_SilphCo7FRivalText"] = "{RIVAL}: Cosa\nti ha trattenuto?",
  ["_SilphCo7FRivalVictoryText"] = "{RIVAL}: Come\ndire?\12Non sei ancora\npronto per giocare\11con i grandi!",
  ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}: Ahahah!\nSapevo che saresti\11venuto!\12Il TEAM ROCKET\nti ha rallentato!\12Ti ho visto a\nZAFFERANOPOLI e ho\11voluto vedere se\11sei migliorato!",
  ["_SilphCo7FRocket1AfterBattleText"] = "Non troverai il\nmio CAPO girando\11a caso!",
  ["_SilphCo7FRocket1BattleText"] = "Oh ho! Sento\npuzza di topo!",
  ["_SilphCo7FRocket1EndBattleText"] = "Luce\nspenta!",
  ["_SilphCo7FRocket2AfterBattleText"] = "Non importa.\nI miei fratelli\11renderanno il favore!",
  ["_SilphCo7FRocket2BattleText"] = "Sono uno dei 4\nFRATELLI ROCKET!",
  ["_SilphCo7FRocket2EndBattleText"] = "Aack!\nFratelli, ho perso!",
  ["_SilphCo7FRocket3AfterBattleText"] = "Vattene a casa\nprima che il CAPO\11si arrabbi!",
  ["_SilphCo7FRocket3BattleText"] = "Un bimbo intruso?\nSarai tu!",
  ["_SilphCo7FRocket3EndBattleText"] = "Va bene!\nHo perso!",
  ["_SilphCo7FScientistAfterBattleText"] = "Nonostante l'eta',\nsei un abile\11allenatore!",
  ["_SilphCo7FScientistBattleText"] = "Eheheh!\12Mi hai scambiato\nper un operaio?",
  ["_SilphCo7FScientistEndBattleText"] = "Ho\nchiuso!",
  ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "Oh! Ciao! Non\nsei un ROCKET!\11Sei venuto a\nsalvarci? Grazie!\12Voglio darti un\nPOKéMON per questo.",
  ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "Il CAPO del ROCKET\né nella sala!\12Il PRESIDENTE sta\nbene?",
  ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "é un LAPRAS, molto\nintelligente.\12Era nel laboratorio\nma stara' meglio\11con te!\12Penso che sarai\nun buon allenatore!\12é un ottimo nuo-\ntore, ti dara' un\11passaggio!",
  ["_SilphCo7FSilphWorkerM1SavedText"] = "Salvo alla fine!\nGrazie!",
  ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "Il TEAM ROCKET\nvoleva la MASTER\11BALL per catturare\11qualsiasi POKéMON!",
  ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "Abbiamo chiuso\nil progetto MASTER\11BALL per colpa del\11TEAM ROCKET.",
  ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "Sarebbe un guaio\nse il TEAM ROCKET\11prendesse la SILPH\11o i nostri POKéMON!",
  ["_SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText"] = "Wow! Hai messo\nin fuga il TEAM\11ROCKET da solo?",
  ["_SilphCo7FSilphWorkerM4ItsReallyDangerousHereText"] = "Tu! Qui é peri-\ncoloso!\11Sei venuto a\nsalvarmi? Non puoi!",
  ["_SilphCo7FSilphWorkerM4SafeAtLastText"] = "Al sicuro!\nOh grazie!",
  ["_SilphCo8FRocket1AfterBattleText"] = "Se non torni\nindietro, chiamo\11rinforzi!",
  ["_SilphCo8FRocket1BattleText"] = "Da qui non\npasserai!",
  ["_SilphCo8FRocket1EndBattleText"] = "Manca\nla grinta!",
  ["_SilphCo8FRocket2AfterBattleText"] = "Lascio fare ai\nmiei fratelli!",
  ["_SilphCo8FRocket2BattleText"] = "Sono uno dei 4\nFRATELLI ROCKET!",
  ["_SilphCo8FRocket2EndBattleText"] = "Whoo!\nOh fratelli!",
  ["_SilphCo8FScientistAfterBattleText"] = "Allora, che ne\npensi del labiri-\11nto della SILPH?",
  ["_SilphCo8FScientistBattleText"] = "Ci stai creando\nproblemi!",
  ["_SilphCo8FScientistEndBattleText"] = "Eh?\nHo perso?",
  ["_SilphCo8FSilphWorkerMSilphIsFinishedText"] = "Chissa' se la\nSILPH é finita...",
  ["_SilphCo8FSilphWorkerMThanksForSavingUsText"] = "Grazie per averci\nsalvati!",
  ["_SilphCo9FRocket1AfterBattleText"] = "Se avessi iniziato\nalla tua eta'...",
  ["_SilphCo9FRocket1BattleText"] = "I tuoi POKéMON\nti adorano, ragazzo!",
  ["_SilphCo9FRocket1EndBattleText"] = "Ghaaah!",
  ["_SilphCo9FRocket2AfterBattleText"] = "I miei fratelli\nmi vendicheranno!",
  ["_SilphCo9FRocket2BattleText"] = "Sono uno dei 4\nFRATELLI ROCKET!",
  ["_SilphCo9FRocket2EndBattleText"] = "Warg!\nFratelli, ho perso!",
  ["_SilphCo9FScientistAfterBattleText"] = "Sfruttare i punti\ndeboli funziona!\11Pensa ai tipi\11elementali!",
  ["_SilphCo9FScientistBattleText"] = "I tuoi POKéMON\nhanno debolezze!\11Le colpiro'!",
  ["_SilphCo9FScientistEndBattleText"] = "Mi hai\ndistrutto!",
  ["_SkyAttackGlowingText"] = "\nsta brillando!",
