  ["_TM21ExplanationText"] = "\12La MT21 contiene\nMEGAASSORBIMENTO.\12Drena meta' del\ndanno inflitto\11per curare i tuoi!",
  ["_TM24ExplanationText"] = "\12La MT24 contiene\nFULMINE!\12Insegnalo a un\nPOKéMON elettro!",
  ["_TM34ExplanationText"] = "\12Una MT contiene una\ntecnica da inseg-\11nare ai POKéMON!\12Una MT é mono-\nuso! Scegli bene\11il POKéMON!\12La MT34 contiene\nPAZIENZA!\12Il POKéMON subisce\ne restituisce il\11doppio del danno!",
