  ["_VaporeonDexEntry"] = "Vicina all'acqua.\nLa lunga coda ha\nuna pinna spesso\12scambiata per\nquella di una\nsirena.",
  ["_VendingMachineText1"] = "Un distributore!\nEcco il menu!",
