  ["_VendingMachineText6"] = "Non c'é piu'\nspazio per roba!",
  ["_VendingMachineText7"] = "Non ho sete!",
  ["_VenomothDexEntry"] = "Le scaglie simili\na polvere sulle\nali indicano i\12vari tipi di\nveleno che\npossiede.",
  ["_VenonatDexEntry"] = "Vive all'ombra di\nalberi alti dove\nmangia insetti. é\12attratto dalla\nluce di notte.",
  ["_VenusaurDexEntry"] = "La pianta fiorisce\nassorbendo energia\nsolare. Si sposta\12continuamente in\ncerca di luce.",
