  ["_VermilionCityNoticeSignText"] = "AVVISO!\12Il PERCORSO 12 é\nbloccato da un\11POKéMON addormentato.\12Deviazione per il\nTUNNEL ROCCO per\11LAVANDONIA.\12POLIZIA ARANCIOPOLI",
