  ["_VermilionGymGentlemanAfterBattleText"] = "La porta non si\napre?\12LT.SURGE é sempre\nstato prudente!",
  ["_VermilionGymGentlemanBattleText"] = "Ero nell'esercito,\ne LT.SURGE era il\11mio sergente!",
  ["_VermilionGymGentlemanEndBattleText"] = "Basta!\nSei bravissimo!",
  ["_VermilionGymGymGuideBeatLTSurgeText"] = "Uff! Quella lotta\nera elettrizzante!",
  ["_VermilionGymGymGuideChampInMakingText"] = "Ehila'! Campione!\12LT.SURGE ha un\nsoprannome: il Fulmine\11Americano!\12é un esperto di\nPOKéMON elettro!\12I volatili e l'acqua\nrischiano molto!\12Attento anche alla\nparalisi!\12LT.SURGE é molto\ncauto!\11Dovrai violare un\ncodice per arrivargli!",
  ["_VermilionGymLTSurgePostBattleAdviceText"] = "Un piccolo consi-\nglio, ragazzo!\12L'elettricita' é\npotente!\12Ma é inutile con\ni POKéMON terra!",
  ["_VermilionGymLTSurgePreBattleText"] = "Ehi, ragazzo! Che\nfai qui?\12Non durerai molto\nin combattimento!\12Te lo assicuro!\12I POKéMON elettro\nmi hanno salvato\11durante la guerra!\12Hanno fulminato\ni miei nemici!\12Faro' lo stesso\ncon te!",
  ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "Urca!\12Sei davvero in\ngamba, ragazzo!\12Prendi la MEDAGLIA\nTUONO!",
  ["_VermilionGymLTSurgeTM24NoRoomText"] = "Ragazzo, fai spazio\nnel tuo zaino!",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "La MEDAGLIA TUONO\naccende la VELOCITA'\11del tuo POKéMON!\12Ti permette anche\ndi usare FLASH!\12Sei speciale!\nPrendi questo!",
  ["_VermilionGymSailorAfterBattleText"] = "LT.SURGE ha messo\ndue serrature!\11Un indizio!\12La seconda é sem-\npre vicina alla\11prima aperta!",
  ["_VermilionGymSailorBattleText"] = "Questo non é un\nposto per bambini!",
  ["_VermilionGymSailorEndBattleText"] = "Wow!\nChe sorpresa!",
  ["_VermilionGymSuperNerdAfterBattleText"] = "OK, parlo!\nLT.SURGE ha nascosto\11gli interruttori\11dentro qualcosa!",
  ["_VermilionGymSuperNerdBattleText"] = "Sono un peso\nleggero, ma me\11la cavo con l'elettr.",
  ["_VermilionGymSuperNerdEndBattleText"] = "Folgorato!",
  ["_VermilionGymTrashFailTest"] = "No! C'é solo\nspazzatura.\11Ehi! Le serrature\11elettriche sono\11state azzerate!",
  ["_VermilionGymTrashSuccessText1"] = "Ehi! C'é un\ninterruttore sotto\11la spazzatura!\11Attivalo!\12La 1ª serratura\nsi é aperta!",
  ["_VermilionGymTrashSuccessText2"] = "Ehi! C'é un\naltro interruttore\11sotto la spazzatura!\11Attivalo!",
  ["_VermilionGymTrashSuccessText3"] = "La 2ª serratura\nsi é aperta!\12La porta motoriz-\nzata si apre!",
  ["_VermilionGymTrashText"] = "No, c'é solo\nspazzatura qui.",
  ["_VermilionMartCooltrainerFText"] = "I POKéMON possono\nessere buoni o\11cattivi a seconda\11dell'allenatore.",
  ["_VermilionMartCooltrainerMText"] = "Ci sono persone\ncattive che usano\11i POKéMON per\11delitti.\12Il TEAM ROCKET\ntratta POKéMON rari\11e abbandona quelli\11che non ritiene\11utili.",
  ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "Sono il GURU\nPESCATORE!\12Adoro pescare!\nTi piace pescare?",
  ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "\12La pesca é uno\nstile di vita!\12Dai mari ai fiumi,\nesci e prendi\11quello grosso!",
  ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "Ciao, {PLAYER}!\nAboccano i pesci?",
  ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "Oh no!\nNon hai spazio\nper il mio dono!",
  ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "Ottimo! Mi piace\nil tuo stile!\12Prendi questo,\ngiovane!\12{PLAYER} riceve\nun {RAM:wStringBuffer}!",
  ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "Oh... Che delu-\nsione...",
  ["_VermilionPidgeyHouseLetterText"] = "Cara PIPPI, spero\ndi vederti presto.\12Ho sentito che\nZAFFERANOPOLI ha guai\11col TEAM ROCKET.\12ARANCIOPOLI sembra\nincolume.",
  ["_VermilionPidgeyHousePidgeyText"] = "PIDGEY: Kurukkoo!",
  ["_VermilionPidgeyHouseYoungsterText"] = "Mando il mio PIDGEY\na portare una\11lettera a ZAFFERANOPOLI!",
  ["_VermilionPokecenterFishingGuruText"] = "Anche allo stesso\nlivello, i POKéMON\11hanno abilita'\11molto diverse.\12Un POKéMON alleva-\nto é piu' forte di\11uno selvaggio.",
  ["_VermilionPokecenterGuyText"] = "é vero che un\nlivello piu' alto\11rende piu' forte...\12Ma ogni POKéMON\nha punti deboli\11verso altri tipi.\12Quindi non esiste\nil POKéMON asso\11assoluto.",
  ["_VermilionPokecenterSailorText"] = "Il mio POKéMON era\navvelenato! é an-\ndato K.O. mentre\11camminavamo!",
  ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "Non volevo per-\ndere con nessuno!",
  ["_VictoryRoad1FCooltrainerFBattleText"] = "Chissa' se sei\nall'altezza!",
  ["_VictoryRoad1FCooltrainerFEndBattleText"] = "Ho\nperso!",
  ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "Lo ammetto, sei\npiu' bravo di me!",
  ["_VictoryRoad1FCooltrainerMBattleText"] = "Vedo che vali!\nFammi vedere\11quanto vali!",
  ["_VictoryRoad1FCooltrainerMEndBattleText"] = "Ci speravo...",
  ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "Ti sei meritato la\nVIA VITTORIA!",
  ["_VictoryRoad2FCooltrainerMBattleText"] = "Avanti!\nTi concio per le feste!",
  ["_VictoryRoad2FCooltrainerMEndBattleText"] = "Mi hanno\nsuonato!",
  ["_VictoryRoad2FHikerAfterBattleText"] = "Se ti blocchi, prova\na spostare qualche\11masso!",
  ["_VictoryRoad2FHikerBattleText"] = "La VIA VITTORIA é\nil test finale\11per gli allenatori!",
  ["_VictoryRoad2FHikerEndBattleText"] = "Aiyah!",
  ["_VictoryRoad2FMoltresBattleText"] = "Gyaoo!",
  ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "Anche {RIVAL} é\npassato di qui!",
  ["_VictoryRoad2FSuperNerd1BattleText"] = "Ah, vuoi sfidare\ni SUPERQUATTRO?",
  ["_VictoryRoad2FSuperNerd1EndBattleText"] = "Mi hai\npreso!",
  ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "Posso batterti in\nquanto a cono-\nscenza POKéMON!",
  ["_VictoryRoad2FSuperNerd2BattleText"] = "Se passi di qui,\npuoi incontrare\11i SUPERQUATTRO!",
  ["_VictoryRoad2FSuperNerd2EndBattleText"] = "No!\nIncredibile!",
  ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "Molti allenatori\nrinunciano qui.",
  ["_VictoryRoad2FSuperNerd3BattleText"] = "La VIA VITTORIA\né troppo dura?",
  ["_VictoryRoad2FSuperNerd3EndBattleText"] = "Ben\nfatto!",
  ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "Mi hai mostrato\nquanto valgo!",
  ["_VictoryRoad3FCooltrainerF1BattleText"] = "Ti mostrero'\nquanto vali!",
  ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "Sono\nfuriosa!",
  ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "Lottando duro,\nsi diventa forti!",
  ["_VictoryRoad3FCooltrainerF2BattleText"] = "Gli allenatori\ncerchano rivali\11piu' forti!",
  ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "Oh!\nChe forza!",
  ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "Hai battuto GIOVANNI\ndel TEAM ROCKET?",
  ["_VictoryRoad3FCooltrainerM1BattleText"] = "Ho sentito voci di\nun bimbo prodigio!",
  ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "Le voci\nerano vere!",
  ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "Tutti qui vanno\nalla LEGA POKéMON!\11Attento!",
  ["_VictoryRoad3FCooltrainerM2BattleText"] = "Solo i prescelti\npassano di qui!",
  ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "Non ci\nposso credere!",
  ["_VictreebelDexEntry"] = "Vive in colonie\nenormi nel\nprofondo della\12giungla, anche se\nnessuno é mai\ntornato da quel\12posto.",
  ["_VileplumeDexEntry"] = "Piu' i petali sono\nampi, piu' polline\ntossico\12contengono. La\ngrossa testa é\npesante e dura da\12reggere.",
  ["_ViridianBlackboardBurnText"] = "Una scottatura\nriduce potenza e\11velocita' e causa\11danni continui.\12Resta anche dopo\nla lotta.\12Usa ANTIBRUCIATURA!",
  ["_ViridianBlackboardFrozenText"] = "Se congelato, un\nPOKéMON resta\11immobile!\12Non si scongela\nneppure dopo la\11lotta.\12Usa ANTIGELO!",
  ["_ViridianBlackboardPoisonText"] = "Da avvelenato, la\nsalute cala sempre.\12Il veleno resta\nanche dopo la lotta.\12Usa un ANTIDOTO\nper guarirlo!",
  ["_ViridianBlackboardPrlzText"] = "La paralisi puo'\nfallire le mosse!\12Resta anche dopo\nla lotta.\12Usa l'ANTIPARALISI\nper curarlo!",
  ["_ViridianBlackboardSleepText"] = "Un POKéMON non\nattacca se dorme!\12Resta addormentato\nanche dopo la lotta.\12Usa la SVEGLIA\nper svegliarlo!",
  ["_ViridianCityFisherReceivedTM42Text"] = "{PLAYER} riceve\nla MT42!",
  ["_ViridianCityFisherTM42ExplanationText"] = "La MT42 contiene\nSOGNIDORO...\11...Ronf...",
  ["_ViridianCityFisherTM42NoRoomText"] = "Hai gia' troppa\nroba con te.",
  ["_ViridianCityGambler1GymAlwaysClosedText"] = "Questa palestra\né sempre chiusa.\12Chissa' chi é il\nCAPOPALESTRA?",
  ["_ViridianCityGambler1GymLeaderReturnedText"] = "Il CAPOPALESTRA\né tornato!",
  ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "Oh nonno! Non\nessere cattivo!\11Non ha ancora\nbevuto il caffé.",
  ["_ViridianCityGirlWhenIGoShopText"] = "Quando vado a\nPLUMBEOPOLI, devo\11fare il sentiero\11del BOSCO SMERALDO.",
  ["_ViridianCityGymLockedText"] = "Le porte della\npalestra sono chiuse",
  ["_ViridianCityGymSignText"] = "PALESTRA POKéMON\ndi SMERALDOPOLI",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "Ahh, ho bevuto il\ncaffé e sto bene!\12Ora puoi passare!\11Hai fretta?",
  ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Usi il POKéDEX, vedo.\nCatturando un POKé-\11MON si aggiorna\11automaticamente.\12Che c'é? Non sai\ncome catturarli?\12Te lo mostro io.",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "Non puoi passare!\nQuesta é proprieta'\nprivata!",
  ["_ViridianCityOldManTimeIsMoneyText"] = "Il tempo é denaro...\nCammina.",
  ["_ViridianCityOldManYouNeedToTheTargetText"] = "Prima devi indebo-\nlire il POKéMON.",
  ["_ViridianCityPokecenterGuyText"] = "I CENTRI POKéMON\ncurano i POKéMON\11stanchi, feriti\11o esausti!",
  ["_ViridianCitySignText"] = "SMERALDOPOLI\nIl Verde Paradiso\11Eterno",
  ["_ViridianCityTrainerTips1Text"] = "CONSIGLI UTILI\12Cattura POKéMON\ne amplia la tua\11collezione!\12Piu' ne hai, piu'\né facile lottare!",
  ["_ViridianCityTrainerTips2Text"] = "CONSIGLI UTILI\12Le mosse dei POKé-\nMON dipendono dai\11PUNTI POTERE, PP.\12Ripristinali ripo-\nsando al CENTRO\11POKéMON!",
  ["_ViridianCityYoungster1Text"] = "Quelle POKé BALL\nin vita!\12Hai dei POKéMON!\12é bello poterli\nportare e usare\11ovunque e sempre!",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "Vuoi sapere dei\n2 tipi di POKéMON\11bruco?",
  ["_ViridianForestLeavingSignText"] = "USCITA\nBOSCO SMERALDO\11PLUMBEOPOLI PIU' AVANTI",
  ["_ViridianForestNorthGateGrampsText"] = "Hai notato i\ncespugli lungo\11la strada?\12Possono essere\n tagliati da una mossa\11speciale.",
  ["_ViridianForestNorthGateSuperNerdText"] = "Molti POKéMON vi-\nvono solo nei boschi\11e grotte.\12Devi cercare ovun-\nque per trovarli!",
  ["_ViridianForestSouthGateGirlText"] = "Vai al BOSCO\nSMERALDO? Attento,\11é un labirinto!",
  ["_ViridianForestSouthGateLittleGirlText"] = "RATTATA é piccolo,\nma il suo morso\11é feroce! Ne hai uno?",
  ["_ViridianForestTrainerTips1Text"] = "CONSIGLI UTILI\12Se vuoi evitare\nlotte, stai lontano\11dall'erba alta!",
  ["_ViridianForestTrainerTips2Text"] = "CONSIGLI UTILI\12Contatta il PROF.OAK\ndal PC per far\11valutare il POKéDEX!",
  ["_ViridianForestTrainerTips3Text"] = "CONSIGLI UTILI\12Non rubare POKéMON\naltrui! Cattura\11solo quelli selvatici!",
  ["_ViridianForestTrainerTips4Text"] = "CONSIGLI UTILI\12Indebolisci i POKéMON\nprima di catturarli!\12Se sani, pos-\nsono fuggire!",
  ["_ViridianForestUseAntidoteSignText"] = "Per il veleno,\nusa l'ANTIDOTO!\11Nei POKéMON MART!",
  ["_ViridianForestYoungster1Text"] = "Sono venuto qui\ncon degli amici!\12Cercano lotte\ncon i POKéMON!",
  ["_ViridianForestYoungster2AfterBattleText"] = "Ssh! Spaventerai\ngli insetti!",
  ["_ViridianForestYoungster2BattleText"] = "Ehi! Hai POKé\nMON! Forza,\11lottiamo!",
  ["_ViridianForestYoungster2EndBattleText"] = "No!\nCATERPIE non\11ce la fa!",
  ["_ViridianForestYoungster3AfterBattleText"] = "Accidenti! Ne\ncaturero' di piu'\11forti!",
  ["_ViridianForestYoungster3BattleText"] = "Ehi! Non puoi\nfarti valere se\11sei un allenatore!",
  ["_ViridianForestYoungster3EndBattleText"] = "Eh?\nHo finito i\11POKéMON!",
  ["_ViridianForestYoungster4AfterBattleText"] = "A volte trovi\nroba per terra!\12Cerco quello che\nho perso io!",
  ["_ViridianForestYoungster4BattleText"] = "Ehi, aspetta!\nTanta fretta?",
  ["_ViridianForestYoungster4EndBattleText"] = "Mi\narrendo! Sei bravo\11in questo!",
  ["_ViridianForestYoungster5Text"] = "Ho finito le POKé\nBALL per cattura-\11re i POKéMON!\12Portane sempre di\nscorta!",
  ["_ViridianGymCooltrainerM1AfterBattleText"] = "Serve potenza per\nreggere il ritmo\11del nostro CAPO!",
  ["_ViridianGymCooltrainerM1BattleText"] = "Heh! Ti stara'\nfinendo il fiato!",
  ["_ViridianGymCooltrainerM1EndBattleText"] = "Ho\nesaurito la spinta!",
  ["_ViridianGymCooltrainerM2AfterBattleText"] = "Il CAPO mi\nsgridera'!",
  ["_ViridianGymCooltrainerM2BattleText"] = "I veri talenti\nvincono con stile!",
  ["_ViridianGymCooltrainerM2EndBattleText"] = "Ho\nperso la presa!",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "Puoi andare alla\nLEGA POKéMON solo\11battendo il CAPO!",
  ["_ViridianGymCooltrainerM3BattleText"] = "La palestra fu\nchiusa a lungo,\11ma ora il CAPO é\11tornato!",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "Sono\nstato battuto?",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "La MEDAGLIA TERRA\nfa' ubbidire i POKéMON\11di ogni livello!\12é la prova della\ntua maestria!\12Con essa puoi\nentrare nella LEGA!\12é il mio dono per\nla tua sfida!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "Avendo perso,\nnon posso guar-\11dare i subordinati!\11Il TEAM ROCKET\11é finito per sempre!\12Dedicchero' la mia\nvita allo studio!\12Ci rivedremo\nun giorno!\11Addio!",
  ["_ViridianGymGiovanniPreBattleText"] = "Fwahahaha! Questo é\nil mio covo!\12Volevo risurreci-\ntare il ROCKET qui!\12Ma mi hai ripreso!\11E sia! Stavolta\11non mi trattengo!\12Affronterai GIOVAN-\nNI, il piu' grande!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "Ha!\nUna lotta intensa!\12Hai vinto!\11Ecco la prova con\nla MEDAGLIA TERRA!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER} riceve\nla MT27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "\12La MT27 é ABISSO!\nStende i POKéMON\11con un sol colpo!\12La feci quando\ngestivo la palestra,\11molto tempo fa...",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "Non hai spazio\nper questo!",
  ["_ViridianGymGuidePostBattleText"] = "Incredibile!\nGIOVANNI era il\11CAPOPALESTRA qui?",
  ["_ViridianGymGuidePreBattleText"] = "Ehila'! Campione!\12Neanche io so chi\nsia il CAPO di QUI!\12Sara' il piu' duro\ndi tutti i capi!\12Ho sentito che\namano i POKéMON\11di tipo terra!",
  ["_ViridianGymHiker1AfterBattleText"] = "Non sono ancora\ndegno!",
  ["_ViridianGymHiker1BattleText"] = "Rrrroar! Mi sto\ninfuriando!",
  ["_ViridianGymHiker1EndBattleText"] = "Wargh!",
  ["_ViridianGymHiker2AfterBattleText"] = "Se i miei POKéMON\nfossero bravi a\11Karate come me...",
  ["_ViridianGymHiker2BattleText"] = "Il karate é la\nforma suprema di\11arti marziali!",
  ["_ViridianGymHiker2EndBattleText"] = "Atcho!",
  ["_ViridianGymHiker3AfterBattleText"] = "La LEGA POKéMON?\nTu? Non montarti",
  ["_ViridianGymHiker3BattleText"] = "Sono il RE del\nKARATE! Il tuo\11destino é qui!",
  ["_ViridianGymHiker3EndBattleText"] = "Ayah!",
  ["_ViridianGymRocker1AfterBattleText"] = "Conosci l'identita'\ndel nostro CAPO?",
  ["_ViridianGymRocker1BattleText"] = "Io e i POKéMON\nfacciamo musica\11meravigliosa!",
  ["_ViridianGymRocker1EndBattleText"] = "Siete in\nperfetta armonia!",
  ["_ViridianGymRocker2AfterBattleText"] = "Aspetta! Sono\nstato distratto!",
  ["_ViridianGymRocker2BattleText"] = "I tuoi POKéMON\ntremaranno alla\11mia frusta!",
  ["_ViridianGymRocker2EndBattleText"] = "Ahi!\nFrustata!",
  ["_ViridianMartClerkParcelQuestText"] = "Conosci il PROF.\nOAK, giusto?\12Il suo ordine é\narrivato. Glielo\11porti?\12{PLAYER} prende\nil PACCO di OAK!",
  ["_ViridianMartClerkSayHiToOakText"] = "Ok! Salutami\nil PROF.OAK!",
  ["_ViridianMartClerkYouCameFromPalletTownText"] = "Ehi! Vieni da\nBIANCAVILLA?",
  ["_ViridianMartCooltrainerMText"] = "No! Le POZIONI\nsono esaurite.",
  ["_ViridianMartYoungsterText"] = "Questo negozio\nvende molti ANTIDOTI",
  ["_ViridianNicknameHouseBaldingGuyText"] = "Inventare i nomi\né bello ma duro.\12I nomi semplici\nsono i piu' facili\11da ricordare.",
  ["_ViridianNicknameHouseLittleGirlText"] = "Anche il mio papa'\nadora i POKéMON.",
  ["_ViridianNicknameHouseSpearowText"] = "SPEARY: Tetweet!",
  ["_ViridianNicknameHouseSpearySignText"] = "SPEAROW\nNome: SPEARY",
  ["_ViridianPokecenterCooltrainerMText"] = "C'é un CENTRO\nPOKéMON in ogni\11citta' davanti.\12E non si paga\nassolutamente nulla!",
  ["_ViridianPokecenterGentlemanText"] = "Puoi usare quel\nPC nell'angolo.\12Me l'ha detto la\nreception. Che carini!",
  ["_ViridianSchoolBlackboardText1"] = "La lavagna de-\nscrive i cambi di\11STATO dei POKéMON\11durante la lotta.",
  ["_ViridianSchoolBlackboardText2"] = "Quale voce vuoi\nleggere?",
  ["_ViridianSchoolHouseBrunetteGirlText"] = "Uff! Studio per\nmemorizzare tutti\11i miei appunti.",
  ["_ViridianSchoolHouseCooltrainerFText"] = "Bene!\nLeggi attentamente\11la lavagna!",
  ["_ViridianSchoolNotebookText1"] = "Guarda il qua-\nderno!\12Prima pagina...\12Le POKé BALL ser-\nvono per catturare\11i POKéMON.\12Si portano fino\na 6 POKéMON.\12Chi li alleva e\nfa lottare é un\11allenatore POKéMON.",
  ["_ViridianSchoolNotebookText2"] = "Seconda pagina...\12Un POKéMON sano é\nduro da catturare,\nindeboliscilo!\12Veleno, ustioni e\ndanni aiutano!",
  ["_ViridianSchoolNotebookText3"] = "Terza pagina...\12Gli allenatori\n cercano sfide.\12Si lotta sempre\nin palestra.",
  ["_ViridianSchoolNotebookText4"] = "Quarta pagina...\12L'obiettivo é bat-\ntere gli 8 CAPO.\12Fallito cio', si\affrontano...\12I SUPERQUATTRO\ndella LEGA POKéMON!",
  ["_ViridianSchoolNotebookText5"] = " RAGAZZA: Ehi!\nNon guardare i\11miei appunti!",
  ["_VitaminNoEffectText"] = "Non avra' alcun\neffetto.",
  ["_VitaminStatRoseText"] = "{RAM:wStringBuffer}\ndi {RAM:wNameBuffer}\né aumentato.",
  ["_VoltorbDexEntry"] = "Solitamente nelle\ncentrali\nelettriche. Spesso\12scambiato per una\nPOKé BALL, ha\nfulminato molte\12persone.",
  ["_VulpixDexEntry"] = "Alla nascita ha\nsolo una coda. La\ncoda si divide\12dalla punta man\nmano che cresce.",
  ["_WannaTrade1Text"] = "Cerco {RAM:wInGameTradeGiveMonName}!\nVuoi scambiarlo\12con {RAM:wInGameTradeReceiveMonName}?",
  ["_WannaTrade2Text"] = "Ciao! Vuoi scam-\nbiare il tuo\12{RAM:wInGameTradeGiveMonName}\nper {RAM:wInGameTradeReceiveMonName}?",
  ["_WannaTrade3Text"] = "Ciao! Hai un\n{RAM:wInGameTradeGiveMonName}?\12Vuoi scambiarlo\nper {RAM:wInGameTradeReceiveMonName}?",
  ["_WardensHouseDisplayMerchandiseText"] = "Vecchi oggetti\nPOKéMON.",
  ["_WardensHouseDisplayPhotosAndFossilsText"] = "Foto e fossili\ndi POKéMON.",
  ["_WardensHouseWardenGaveTheGoldTeethText"] = "{PLAYER} da' i\nDENTI D'ORO al\11GUARDIANO!",
  ["_WardensHouseWardenGibberish1Text"] = "GUARDIA: Hif fuff\nhefifoo!\12Ha lof ha feef ee\nhafahi ho. Heff\11hee fwee!",
  ["_WardensHouseWardenGibberish2Text"] = "Ah howhee ho hoo!\nEef ee hafahi ho!",
